-- =============================================================================
-- 412 — LE CATALOGUE DES CONTRÔLES BLANCS : 1re (spcl, sport, svt)
--
-- 117 sujets écrits d'avance et relus : pour chaque fiche, un sujet
-- Facile, un Moyen, un Difficile, chacun avec son barème sur 20 et son corrigé
-- type (`contenu.corrige`, jamais envoyé à l'élève avant sa copie). L'IA ne fait
-- plus que les corriger ; elle ne rédige que « Un autre sujet ».
--
-- ⚠️ FICHIER GÉNÉRÉ — ne pas éditer à la main. Source : contenu/controles/.
--    Regénérer : node node_modules/jiti/lib/jiti-cli.mjs scripts/controles-sql.ts --num 412 --niveau 1re --matieres spcl,sport,svt
--
--   spcl.m1                      45 sujets · 15 fiches
--   sport.jumelles                9 sujets · 3 fiches
--   svt.21ra                     33 sujets · 11 fiches
--   svt.21rb                     30 sujets · 10 fiches
--
-- L'identifiant d'un sujet est dérivé de (fiche, niveau) : rejouer la migration
-- met le sujet à jour au lieu de le dupliquer. Une fiche absente est sautée.
--
-- PRÉREQUIS : 360 puis 364. Idempotent. À exécuter à la main dans :
-- Supabase Dashboard → SQL Editor → New query → Run.
-- =============================================================================

INSERT INTO public.chapter_exercices
  (id, chapter_id, style, contenu, difficulte, origine, created_by)
SELECT
  md5('exercice-catalogue:' || v.chapter_id::text || ':' || v.difficulte::text)::uuid,
  v.chapter_id,
  v.style,
  v.contenu,
  v.difficulte,
  'catalogue',
  NULL
FROM (VALUES
  ('107e042d-818a-5b99-aecd-ef8c2e5676cd'::uuid, 1, 'application', $exo${"titre":"La pipette de Maëlys et les deux groupes","consigne":"Réponds à chaque question en justifiant. Donne les résultats avec leur unité.","enonce":"**Situation.** En TP, Maëlys prélève un volume de solution avec une pipette jaugée de 20,00 mL. Le fabricant indique une tolérance de ± 0,03 mL.\n\nDeux autres groupes mesurent la même concentration, dont la valeur de référence est 5,00 mmol·L⁻¹ :\n\n| Groupe | Mesures (mmol·L⁻¹) |\n|---|---|\n| A | 5,21 ; 5,22 ; 5,20 ; 5,21 |\n| B | 4,80 ; 5,25 ; 4,95 ; 5,10 |\n\n1. Définis la fidélité et la justesse d'une série de mesures.\n2. Pour chaque groupe, dis si la série est fidèle et si elle est juste. Justifie (tu peux calculer la moyenne de chaque série).\n3. Maëlys ne fait qu'une seule mesure. Calcule l'incertitude-type u(V) sur le volume prélevé, puis écris le résultat de la mesure.","bareme":[{"critere":"Définitions justes : fidélité = mesures proches entre elles ; justesse = moyenne proche de la référence","points":6},{"critere":"Groupe A fidèle mais pas juste, groupe B juste en moyenne mais peu fidèle, avec moyennes ou écarts cités","points":8},{"critere":"u(V) = 0,03/√3 ≈ 0,017 mL et résultat écrit avec valeur, incertitude et unité, arrondis cohérents","points":6}],"dureeMin":7,"corrige":"1. Une série est **fidèle** si les mesures répétées sont **proches les unes des autres** (faible dispersion, peu d'erreurs aléatoires). Elle est **juste** si sa **moyenne est proche de la valeur de référence** (pas de décalage, pas d'erreur systématique).\n\n2. **Groupe A** : moyenne = (5,21 + 5,22 + 5,20 + 5,21) / 4 = **5,21 mmol·L⁻¹**. Les valeurs ne s'écartent que de 0,02 au plus : la série est **fidèle**. Mais la moyenne est décalée de 0,21 par rapport à 5,00 : elle **n'est pas juste** (erreur systématique probable). Image de la cible : impacts groupés loin du centre.\n**Groupe B** : moyenne = 20,10 / 4 ≈ **5,03 mmol·L⁻¹**, très proche de 5,00 : la série est **juste en moyenne**. Mais les valeurs vont de 4,80 à 5,25 : elle est **peu fidèle** (grande dispersion). Impacts éparpillés autour du centre.\n\n3. Mesure unique avec une tolérance ± Δ (évaluation de type B) : u(V) = Δ / √3 = 0,03 / √3 ≈ **0,017 mL**.\nRésultat : **V = 20,000 mL avec u(V) = 0,017 mL** (ou, avec un seul chiffre significatif, V = 20,00 mL avec u(V) = 0,02 mL). La valeur est arrondie au même rang que l'incertitude."}$exo$::jsonb),
  ('107e042d-818a-5b99-aecd-ef8c2e5676cd'::uuid, 2, 'application', $exo${"titre":"Six titrages pour un volume équivalent","consigne":"Réponds en détaillant tes calculs. Arrondis l'incertitude-type à un ou deux chiffres significatifs.","enonce":"**Situation.** Six binômes titrent la même solution et relèvent le volume à l'équivalence V_E (en mL) :\n\n| Binôme | 1 | 2 | 3 | 4 | 5 | 6 |\n|---|---|---|---|---|---|---|\n| V_E (mL) | 12,4 | 12,6 | 12,5 | 12,7 | 12,3 | 12,5 |\n\nLa calculatrice donne l'écart-type de la série : s = 0,141 mL.\nLe professeur, qui connaît la concentration exacte, attend V_réf = 12,60 mL.\n\n1. Calcule la moyenne des six mesures.\n2. De quel type d'évaluation s'agit-il ? Calcule l'incertitude-type u sur la moyenne.\n3. Écris le résultat de la mesure de V_E.\n4. Le résultat est-il compatible avec la valeur attendue ? Justifie par un calcul.","bareme":[{"critere":"Moyenne juste : 12,50 mL","points":4},{"critere":"Évaluation de type A identifiée et u = s/√n ≈ 0,058 mL calculée","points":6},{"critere":"Résultat écrit : V_E = 12,50 mL avec u = 0,06 mL (ou 0,058 mL), unité présente","points":3},{"critere":"z = |12,50 − 12,60| / u ≈ 1,7, comparé à 2 : résultat compatible","points":7}],"dureeMin":10,"corrige":"1. Somme : 12,4 + 12,6 + 12,5 + 12,7 + 12,3 + 12,5 = 75,0 mL. Moyenne : 75,0 / 6 = **12,50 mL**.\n\n2. On exploite statistiquement une **série de mesures répétées** : c'est une **évaluation de type A**. L'incertitude-type sur la moyenne vaut u = s / √n = 0,141 / √6 = 0,141 / 2,449 ≈ **0,058 mL** (ou 0,06 mL avec un chiffre significatif).\n\n3. **V_E = 12,50 mL avec u(V_E) = 0,06 mL** (ou 12,500 mL avec u = 0,058 mL : la valeur est arrondie au rang de l'incertitude).\n\n4. On calcule l'écart en nombre d'incertitudes-types : z = |12,50 − 12,60| / 0,058 = 0,10 / 0,058 ≈ **1,7**.\nComme z ≤ 2, le résultat est **compatible** avec la valeur attendue : l'écart s'explique par la variabilité normale des mesures, il n'est pas nécessaire de chercher une erreur systématique."}$exo$::jsonb),
  ('107e042d-818a-5b99-aecd-ef8c2e5676cd'::uuid, 3, 'application', $exo${"titre":"Masse volumique de l'eau : qui a raison ?","consigne":"Analyse les deux démarches. Chaque réponse doit être justifiée par un calcul ou par une notion du cours.","enonce":"**Situation.** Deux élèves mesurent la masse volumique ρ de l'eau distillée à 20 °C. Valeur de référence : ρ_réf = 0,998 g·mL⁻¹.\n\n**Inès** pèse cinq fois un volume prélevé avec la même pipette et obtient (en g·mL⁻¹) : 1,012 ; 1,010 ; 1,013 ; 1,011 ; 1,014. La calculatrice donne s ≈ 0,0016 g·mL⁻¹.\n\n**Tom** fait une seule mesure : ρ = 0,995 g·mL⁻¹. D'après les données des instruments, sa mesure est connue à ± 0,005 g·mL⁻¹ près.\n\n1. Calcule la moyenne d'Inès et l'incertitude-type sur cette moyenne. Précise le type d'évaluation.\n2. Calcule l'incertitude-type de Tom. Précise le type d'évaluation.\n3. Pour chaque élève, calcule z et conclus sur la compatibilité avec la référence.\n4. Qualifie la série d'Inès en termes de fidélité et de justesse. Pourquoi refaire encore dix mesures avec le même matériel ne corrigerait-il pas son résultat ?\n5. Propose deux sources d'erreur possibles pour Inès, en les classant (instrument, opérateur, méthode, conditions).","bareme":[{"critere":"Moyenne 1,012 g·mL⁻¹ et u = s/√5 ≈ 0,0007 g·mL⁻¹, type A","points":4},{"critere":"u = 0,005/√3 ≈ 0,003 g·mL⁻¹, type B","points":3},{"critere":"z ≈ 20 pour Inès (incompatible), z ≈ 1 pour Tom (compatible), comparaison à 2","points":5},{"critere":"Inès fidèle mais pas juste ; répéter réduit l'effet des erreurs aléatoires mais pas une erreur systématique","points":5},{"critere":"Deux sources d'erreur systématique plausibles, correctement classées","points":3}],"dureeMin":18,"corrige":"1. Moyenne d'Inès : (1,012 + 1,010 + 1,013 + 1,011 + 1,014) / 5 = 5,060 / 5 = **1,012 g·mL⁻¹**. Série de mesures répétées : **type A**. u = s / √n = 0,0016 / √5 = 0,0016 / 2,236 ≈ **0,0007 g·mL⁻¹**.\nRésultat : ρ = 1,0120 g·mL⁻¹ avec u = 0,0007 g·mL⁻¹.\n\n2. Mesure unique, tolérance ± Δ : **type B**. u = Δ / √3 = 0,005 / 1,732 ≈ **0,003 g·mL⁻¹**.\n\n3. Inès : z = |1,012 − 0,998| / 0,0007 = 0,014 / 0,0007 ≈ **20** : z > 2, résultat **incompatible** avec la référence.\nTom : z = |0,995 − 0,998| / 0,003 = 0,003 / 0,003 = **1** (≈ 1,0) : z ≤ 2, résultat **compatible**.\n\n4. La série d'Inès est **fidèle** (valeurs très proches, s faible) mais **pas juste** (moyenne décalée de 0,014 par rapport à la référence) : c'est la cible aux impacts groupés loin du centre. Ce décalage traduit une **erreur systématique** : elle affecte toutes les mesures de la même façon. Répéter les mesures réduit l'incertitude liée aux erreurs aléatoires (u diminue avec √n), mais **ne détecte ni ne corrige** une erreur systématique : la moyenne resterait décalée.\n\n5. Exemples attendus (deux suffisent) :\n- **instrument** : balance mal tarée ou mal étalonnée, pipette dont le volume réel diffère du volume annoncé ;\n- **opérateur** : lecture du ménisque toujours faite au-dessus du trait de jauge ;\n- **méthode** : récipient de pesée humide ou non taré avec le bon contenant ;\n- **conditions** : eau à une température différente de 20 °C.\nConclusion : la mesure de Tom est moins précise mais compatible ; celle d'Inès est précise mais fausse. Il faut chercher et supprimer la cause du décalage (par exemple vérifier la balance avec une masse étalon)."}$exo$::jsonb),
  ('64406e4c-bdf6-5f8a-97ae-4eea97193e89'::uuid, 1, 'application', $exo${"titre":"Lire les pictogrammes du laboratoire","consigne":"Réponds aux questions à l'aide de tes connaissances du règlement CLP.","enonce":"**Situation.** Nathan range la réserve du laboratoire. Il relève cinq pictogrammes sur les flacons :\n\n- a) une flamme ;\n- b) une flamme au-dessus d'un cercle ;\n- c) une main et une surface rongées par un liquide ;\n- d) une silhouette avec une étoile sur la poitrine ;\n- e) un arbre et un poisson.\n\n1. Donne la signification de chacun des cinq pictogrammes.\n2. Quelle est la différence entre une phrase H et une phrase P ? Illustre avec un exemple de chaque.\n3. Entre les mentions « Danger » et « Attention », laquelle signale les dangers les plus graves ?\n4. Cite deux règles de base de sécurité à respecter avant de manipuler.","bareme":[{"critere":"Les cinq pictogrammes correctement interprétés","points":10},{"critere":"H = nature du danger, P = conseil de prudence, avec un exemple juste de chaque","points":6},{"critere":"« Danger » identifiée comme la plus grave et deux règles de base correctes","points":4}],"dureeMin":7,"corrige":"1. a) Flamme : produit **inflammable** (ex. éthanol, acétone).\nb) Flamme sur un cercle : produit **comburant** (ex. dioxygène, permanganate).\nc) Corrosion : produit **corrosif** (ex. soude, acide chlorhydrique concentré).\nd) Silhouette avec étoile : **danger grave pour la santé** (cancérogène, mutagène… ex. dichlorométhane).\ne) Arbre et poisson : **dangereux pour le milieu aquatique** (ex. sulfate de cuivre).\n\n2. Une **phrase H** (*hazard*, mention de danger) décrit la **nature du danger** : H225 « liquide et vapeurs très inflammables », ou H314 « provoque des brûlures de la peau et des lésions oculaires graves ». Une **phrase P** (*precaution*, conseil de prudence) dit **quoi faire** : P280 « porter des gants de protection, un équipement de protection des yeux », ou P210 « tenir à l'écart de la chaleur et des flammes ».\n\n3. La mention **« Danger »** signale les dangers les plus graves ; « Attention » est moins grave.\n\n4. Deux règles parmi : blouse en coton fermée, lunettes de protection, gants adaptés, cheveux attachés, ne jamais manger ni boire, ne jamais pipeter à la bouche, travailler sous hotte pour les produits volatils toxiques ou inflammables, repérer le rince-œil, la douche et l'extincteur, lire la FDS avant la manipulation."}$exo$::jsonb),
  ('64406e4c-bdf6-5f8a-97ae-4eea97193e89'::uuid, 2, 'application', $exo${"titre":"L'étiquette de l'acétone","consigne":"Exploite l'étiquette pour répondre. Chaque mesure de protection doit être reliée à une information de l'étiquette.","enonce":"**Document – Étiquette d'un flacon d'acétone**\n\n> Pictogrammes : flamme ; point d'exclamation.\n> Mention d'avertissement : **Danger**.\n> H225 : liquide et vapeurs très inflammables.\n> H319 : provoque une sévère irritation des yeux.\n> H336 : peut provoquer somnolence ou vertiges.\n> P210 : tenir à l'écart de la chaleur et des flammes.\n\n**Situation.** Chloé doit utiliser 50 mL d'acétone pour nettoyer de la verrerie. Sur la paillasse voisine, un camarade chauffe de l'eau avec un bec Bunsen.\n\n1. Identifie les dangers de l'acétone à partir des pictogrammes et des phrases H.\n2. Indique les équipements de protection individuelle nécessaires et justifie-les.\n3. Où Chloé doit-elle manipuler ? Justifie à l'aide de deux phrases de l'étiquette.\n4. Où ranger le flacon après usage, et à côté de quelle famille de produits ne faut-il surtout pas le placer ?\n5. Quel document Chloé devrait-elle consulter pour savoir quoi faire en cas de projection dans les yeux, et à quel moment ?","bareme":[{"critere":"Dangers identifiés : très inflammable, irritant pour les yeux, somnolence ou vertiges (vapeurs)","points":5},{"critere":"Lunettes, gants, blouse justifiés par l'étiquette (H319, contact)","points":4},{"critere":"Manipulation sous hotte et loin du bec Bunsen, justifiée par H225/P210 et H336","points":5},{"critere":"Stockage en armoire ventilée des inflammables, loin des oxydants (comburants)","points":3},{"critere":"FDS citée (rubrique premiers secours), lue avant la manipulation","points":3}],"dureeMin":11,"corrige":"1. La **flamme** et H225 : l'acétone est un liquide **très inflammable**, ses vapeurs aussi. Le **point d'exclamation**, H319 et H336 : elle est **irritante pour les yeux** et ses **vapeurs** peuvent provoquer **somnolence ou vertiges**. La mention « Danger » indique un niveau de danger élevé.\n\n2. **Lunettes de protection** (H319 : irritation sévère des yeux), **gants** adaptés et **blouse en coton fermée** (éviter tout contact avec la peau et les vêtements), cheveux attachés.\n\n3. Chloé doit manipuler **sous la hotte** : les vapeurs peuvent provoquer somnolence ou vertiges (H336) et elles sont très inflammables (H225). Elle doit être **loin de toute flamme** : le bec Bunsen voisin doit être éteint ou éloigné, conformément à P210 (« tenir à l'écart de la chaleur et des flammes »).\n\n4. On range l'acétone dans l'**armoire ventilée des produits inflammables**, avec des produits compatibles. Il ne faut **jamais** la placer à côté d'un **oxydant** (produit comburant, comme le permanganate) : un oxydant à côté d'un inflammable est interdit.\n\n5. La **fiche de données de sécurité (FDS)**, fournie par le fabricant : sa rubrique **premiers secours** indique la conduite à tenir. On la lit **avant** la manipulation, pas après l'accident (en cas de projection, on utilise le rince-œil)."}$exo$::jsonb),
  ('64406e4c-bdf6-5f8a-97ae-4eea97193e89'::uuid, 3, 'application', $exo${"titre":"Préparer une séance de TP en sécurité","consigne":"Tu es chargé de la sécurité d'une séance. Analyse les étiquettes et rédige des réponses argumentées.","enonce":"**Situation.** Pour une séance de TP, le technicien sort trois flacons :\n\n| Produit | Pictogrammes | Mention | Phrases H |\n|---|---|---|---|\n| Éthanol | flamme, point d'exclamation | Danger | H225, H319 |\n| Permanganate de potassium (solide) | flamme sur un cercle, point d'exclamation, arbre et poisson | Danger | H272 (peut aggraver un incendie ; comburant), H302 (nocif en cas d'ingestion), H410 (très toxique pour les organismes aquatiques) |\n| Acide chlorhydrique à 37 % | corrosion, point d'exclamation | Danger | H290, H314, H335 |\n\nPour gagner de la place, un élève propose de ranger les trois flacons sur la même étagère, puis de nettoyer une flaque d'acide chlorhydrique avec de l'eau de Javel. En fin de séance, un autre veut vider les restes de solution de permanganate dans l'évier.\n\n1. Pour chaque produit, indique la nature du danger principal.\n2. La proposition de rangement est-elle acceptable ? Explique quels produits doivent être séparés et pourquoi.\n3. Pourquoi l'idée d'utiliser l'eau de Javel sur la flaque d'acide est-elle dangereuse ?\n4. Faut-il vider la solution de permanganate dans l'évier ? Justifie avec l'étiquette.\n5. Rédige la liste des protections et des conditions de travail pour manipuler l'acide chlorhydrique à 37 %, en justifiant chaque point.","bareme":[{"critere":"Dangers principaux : éthanol inflammable, permanganate comburant et dangereux pour le milieu aquatique, acide corrosif","points":4},{"critere":"Rangement refusé : oxydant séparé de l'inflammable ; acide stocké avec les acides, loin des bases et de l'eau de Javel","points":5},{"critere":"Acide + eau de Javel : dégagement de dichlore toxique","points":3},{"critere":"Pas d'évier : pictogramme environnement et H410, collecte comme déchet","points":3},{"critere":"Protections et hotte justifiées par H314 et H335 (lunettes, gants, blouse, hotte)","points":5}],"dureeMin":18,"corrige":"1. **Éthanol** : liquide **inflammable** (flamme, H225), irritant pour les yeux (H319).\n**Permanganate de potassium** : **comburant** (flamme sur un cercle, H272 : il peut aggraver un incendie), nocif (H302) et **dangereux pour le milieu aquatique** (arbre et poisson, H410).\n**Acide chlorhydrique à 37 %** : **corrosif** (H314 : brûlures de la peau et lésions oculaires graves), irritant pour les voies respiratoires (H335).\n\n2. **Non.** On stocke par **familles compatibles** : jamais un **oxydant à côté d'un inflammable**. Le permanganate (comburant) et l'éthanol (inflammable) doivent être séparés : en cas de fuite ou de feu, le comburant aggraverait l'incendie. L'éthanol va dans l'armoire ventilée des inflammables. L'acide chlorhydrique se range avec les **acides**, loin des bases et de l'eau de Javel.\n\n3. Mélanger de l'acide chlorhydrique et de l'**eau de Javel** libère du **dichlore**, un gaz **toxique**. Il ne faut jamais les mettre en contact (une flaque d'acide se traite selon les indications de la FDS, rubrique mesures en cas de dispersion).\n\n4. **Non.** Le pictogramme arbre et poisson et la phrase H410 indiquent que le permanganate est très toxique pour les organismes aquatiques : l'évier mène aux eaux usées. La solution est récupérée comme **déchet** dans un bidon adapté.\n\n5. Pour l'acide chlorhydrique à 37 % :\n- **lunettes de protection** et **gants** adaptés, **blouse en coton fermée** : H314, le produit brûle la peau et les yeux (conseil de type P280) ;\n- manipulation **sous la hotte** : H335, les vapeurs irritent les voies respiratoires ;\n- ne jamais pipeter à la bouche, cheveux attachés ;\n- repérer le **rince-œil** et la **douche** avant de commencer ;\n- avoir lu la **FDS** avant (premiers secours, conduite en cas de dispersion) ;\n- tenir le flacon loin des bases et de l'eau de Javel."}$exo$::jsonb),
  ('66d17b6a-2283-59c9-b3ca-c543c78fe1d0'::uuid, 1, 'application', $exo${"titre":"Reconnaître les principes de la chimie verte","consigne":"Réponds en citant le principe de la chimie verte concerné et en justifiant brièvement.","enonce":"**Situation.** Une entreprise modifie cinq de ses procédés :\n\n- a) elle remplace le dichlorométhane, solvant dangereux, par de l'eau ;\n- b) elle fabrique un plastique à partir d'amidon de maïs au lieu du pétrole ;\n- c) elle utilise un catalyseur au lieu d'un réactif en large excès ;\n- d) elle mène une réaction à 25 °C au lieu de 150 °C ;\n- e) elle conçoit un emballage qui se décompose en compost au lieu de persister des années.\n\n1. Associe chaque modification à un principe de la chimie verte.\n2. Quelle est l'idée du premier principe de la chimie verte ?\n3. Un industriel affirme : « Mon procédé a un rendement de 95 %, il est donc vert. » Explique pourquoi ce raisonnement est insuffisant.","bareme":[{"critere":"Les cinq modifications associées au bon principe (solvants, renouvelables, catalyse, énergie, dégradabilité)","points":10},{"critere":"Premier principe : prévenir les déchets plutôt que les traiter","points":4},{"critere":"Le rendement ne suffit pas : économie d'atomes, toxicité des solvants et énergie comptent aussi","points":6}],"dureeMin":7,"corrige":"1. a) **Solvants et auxiliaires** : éviter les solvants dangereux ou choisir les plus sûrs, comme l'eau.\nb) **Matières premières renouvelables** : la biomasse (maïs) plutôt que le pétrole.\nc) **Catalyse** : un catalyseur n'est pas consommé, il remplace un réactif en excès et réduit les déchets.\nd) **Énergie** : travailler à température et pression ambiantes économise l'énergie.\ne) **Dégradabilité** : concevoir des produits qui se décomposent sans persister dans l'environnement.\n\n2. **Prévenir les déchets** : mieux vaut ne pas produire de déchet que d'avoir à le traiter ensuite.\n\n3. Le rendement ne dit que la part du produit maximal effectivement obtenue. Un procédé à 95 % de rendement peut rester très polluant : il peut avoir une faible **économie d'atomes** (beaucoup d'atomes des réactifs partent en sous-produits), utiliser des **solvants toxiques**, consommer beaucoup d'**énergie**. Un procédé se juge aussi sur ses impacts environnemental, économique et social."}$exo$::jsonb),
  ('66d17b6a-2283-59c9-b3ca-c543c78fe1d0'::uuid, 2, 'application', $exo${"titre":"L'économie d'atomes de l'arôme de banane","consigne":"Détaille tes calculs. Donne les pourcentages arrondis à l'unité.","enonce":"**Situation.** L'acétate d'isoamyle (arôme de banane) est synthétisé selon l'équation :\n\nalcool isoamylique + acide éthanoïque → acétate d'isoamyle + eau\n\n**Données** (masses molaires en g·mol⁻¹) : alcool isoamylique 88 ; acide éthanoïque 60 ; acétate d'isoamyle 130 ; eau 18 ; éthène 28.\n\n1. Calcule l'économie d'atomes de cette synthèse.\n2. Quels atomes sont « perdus » ? Ce sous-produit est-il gênant pour l'environnement ?\n3. L'éthanol (46 g·mol⁻¹) peut être fabriqué par addition d'eau sur l'éthène : éthène + eau → éthanol. Calcule l'économie d'atomes de cette réaction et commente.\n4. Le protocole de la synthèse de l'ester utilise du dichlorométhane pour l'extraction. Propose une amélioration et nomme le principe concerné.","bareme":[{"critere":"Économie d'atomes de l'estérification : 130 / 148 ≈ 88 %","points":6},{"critere":"Sous-produit identifié : l'eau, sans danger","points":4},{"critere":"Addition : 46 / 46 = 100 %, justifiée par le fait que tous les atomes se retrouvent dans le produit","points":6},{"critere":"Remplacement du dichlorométhane par un solvant plus sûr, principe des solvants cité","points":4}],"dureeMin":11,"corrige":"1. Économie d'atomes = M(produit voulu) / somme des M des réactifs = 130 / (88 + 60) = 130 / 148 ≈ 0,878, soit **environ 88 %**.\n\n2. Les atomes perdus forment le sous-produit, l'**eau** (18 g·mol⁻¹ ; on vérifie : 148 − 130 = 18). L'eau n'est **ni toxique ni polluante** : cette perte est peu gênante. C'est une réaction économe en atomes même si elle n'atteint pas 100 %.\n\n3. Somme des réactifs : 28 + 18 = 46 g·mol⁻¹. Économie d'atomes = 46 / 46 = **100 %**. C'est une **addition** : tous les atomes des réactifs se retrouvent dans le produit, il n'y a aucun sous-produit.\n\n4. Remplacer le **dichlorométhane** (danger grave pour la santé) par un solvant plus sûr, ou supprimer cette étape si possible (par exemple séparer l'ester par décantation après relargage à l'eau salée). Principe : **solvants et auxiliaires** (les éviter ou choisir les plus sûrs) ; on peut aussi citer « réduire les dangers »."}$exo$::jsonb),
  ('66d17b6a-2283-59c9-b3ca-c543c78fe1d0'::uuid, 3, 'application', $exo${"titre":"Trois chemins vers l'éthanol","consigne":"Exploite le document pour comparer les procédés. Tes calculs et ton argumentation doivent s'appuyer sur les principes de la chimie verte et sur le triple impact.","enonce":"**Document – Trois voies de fabrication de l'éthanol** (masses molaires en g·mol⁻¹ : bromoéthane 109 ; hydroxyde de sodium 40 ; éthanol 46 ; bromure de sodium 103 ; éthène 28 ; eau 18 ; glucose 180 ; dioxyde de carbone 44)\n\n| Voie | Équation | Conditions |\n|---|---|---|\n| A | bromoéthane + hydroxyde de sodium → éthanol + bromure de sodium | 80 °C, solvant organique, réactifs issus du pétrole |\n| B | éthène + eau → éthanol | environ 300 °C et 60 à 70 bar, catalyseur acide ; éthène issu du pétrole |\n| C | glucose → 2 éthanol + 2 dioxyde de carbone | fermentation par des levures, vers 30 °C, dans l'eau ; glucose issu de betterave ou de maïs |\n\n1. Calcule l'économie d'atomes des voies A, B et C (pour C, tiens compte des deux molécules d'éthanol).\n2. Quel type de réaction est la voie B ? Relie-le à ton résultat.\n3. Pour chaque voie, cite un avantage et un inconvénient au regard des principes de la chimie verte.\n4. Un industriel doit choisir une voie. Rédige un paragraphe argumenté qui compare au moins deux voies sur les trois plans (environnemental, économique, social) et conclut.","bareme":[{"critere":"Économies d'atomes justes : A ≈ 31 %, B = 100 %, C ≈ 51 %","points":6},{"critere":"Voie B reconnue comme une addition, ce qui explique les 100 %","points":2},{"critere":"Un avantage et un inconvénient pertinents par voie, reliés à un principe","points":6},{"critere":"Paragraphe comparant au moins deux voies sur les trois plans, avec une conclusion nuancée","points":6}],"dureeMin":20,"corrige":"1. **Voie A** : 46 / (109 + 40) = 46 / 149 ≈ **31 %**.\n**Voie B** : 46 / (28 + 18) = 46 / 46 = **100 %**.\n**Voie C** : produit voulu = 2 éthanol = 2 × 46 = 92 g·mol⁻¹ ; 92 / 180 ≈ **51 %** (le reste part en CO₂ : 2 × 44 = 88 ; 92 + 88 = 180).\n\n2. La voie B est une **addition** : deux molécules s'unissent, la double liaison de l'éthène devient simple. Tous les atomes des réactifs se retrouvent dans le produit, d'où **100 %**.\n\n3. Exemples attendus :\n- **A** : avantage, température modérée (80 °C). Inconvénients : économie d'atomes faible (près de 70 % de la masse des réactifs finit en bromure de sodium), solvant organique, réactifs issus du pétrole.\n- **B** : avantage, économie d'atomes maximale, pas de sous-produit ; utilisation d'un catalyseur. Inconvénients : forte consommation d'**énergie** (300 °C, 60 à 70 bar), matière première **fossile**, risques liés aux hautes pressions.\n- **C** : avantages, matière première **renouvelable** (biomasse), réaction à température proche de l'ambiante (économie d'énergie), dans l'eau. Inconvénient : économie d'atomes moyenne (51 %), rejet de CO₂ ; utilise des terres agricoles.\n\n4. Exemple de paragraphe : sur le plan **environnemental**, la voie A est la moins satisfaisante : faible économie d'atomes, solvant organique, pétrole. La voie B ne produit aucun déchet mais consomme beaucoup d'énergie et dépend du pétrole ; la voie C utilise une ressource renouvelable, de l'eau et peu d'énergie, mais rejette du CO₂. Sur le plan **économique**, B demande des installations coûteuses (haute pression, chauffage) mais aucun traitement de sous-produit ; C demande peu d'énergie mais dépend du prix des récoltes ; A paie des réactifs perdus et le traitement du bromure de sodium. Sur le plan **social**, B expose les salariés aux risques des hautes pressions ; C crée des emplois agricoles. **Conclusion** : aucune voie n'est parfaite ; A est à écarter ; le choix entre B et C dépend du critère prioritaire (économie d'atomes et absence de déchet pour B, ressource renouvelable et énergie pour C). Toute conclusion argumentée est acceptée si elle ne se fonde pas sur un seul critère."}$exo$::jsonb),
  ('aad28990-b793-57bd-9233-a2f7393703d2'::uuid, 1, 'application', $exo${"titre":"Le montage à reflux","consigne":"Réponds en phrases courtes et précises.","enonce":"**Situation.** Pour synthétiser un ester, Samir réalise un chauffage à reflux. Son montage comporte : un ballon contenant les réactifs et quelques grains de pierre ponce, un chauffe-ballon posé sur un support élévateur, et un réfrigérant à boules vertical relié au robinet.\n\n1. Quelles sont les trois étapes d'une synthèse organique, avant l'analyse du produit ?\n2. Pourquoi chauffe-t-on le mélange ? Pourquoi ne chauffe-t-on pas simplement dans un ballon ouvert ?\n3. Quel est le rôle du réfrigérant ? Par où l'eau doit-elle entrer ?\n4. Donne le rôle de la pierre ponce et celui du support élévateur.","bareme":[{"critere":"Transformation, isolement, purification cités dans l'ordre","points":4},{"critere":"Chauffer accélère la réaction ; sans reflux, les espèces volatiles s'échapperaient","points":6},{"critere":"Réfrigérant : condense les vapeurs qui retombent dans le ballon ; eau entrant par le bas","points":6},{"critere":"Pierre ponce : régulariser l'ébullition ; support élévateur : retirer vite le chauffage","points":4}],"dureeMin":6,"corrige":"1. **Transformation** (on fait réagir), **isolement** (on sépare le produit du milieu réactionnel), **purification** (on élimine les impuretés restantes). L'analyse vient ensuite.\n\n2. Chauffer **accélère la réaction**. Mais dans un ballon ouvert, les espèces **volatiles** (réactifs, produit, solvant) s'échapperaient sous forme de vapeur : on perdrait de la matière.\n\n3. Dans le **réfrigérant**, les vapeurs se **condensent** et **retombent** dans le ballon : on peut chauffer longtemps sans perte de matière. L'eau entre **par le bas** et sort par le haut.\n\n4. La **pierre ponce** régularise l'ébullition. Le **support élévateur** permet de **retirer rapidement** le chauffe-ballon (en cas d'emballement ou pour arrêter le chauffage)."}$exo$::jsonb),
  ('aad28990-b793-57bd-9233-a2f7393703d2'::uuid, 2, 'application', $exo${"titre":"Choisir le bon solvant extracteur","consigne":"Exploite le tableau de données et justifie chacun de tes choix.","enonce":"**Situation.** Julie doit extraire le limonène (molécule odorante) d'un mélange aqueux, à l'aide d'une ampoule à décanter.\n\n**Données**\n\n| Espèce | Densité | Miscibilité avec l'eau | Solubilité du limonène | Pictogrammes |\n|---|---|---|---|---|\n| Eau | 1,00 | — | très faible | aucun |\n| Éthanol | 0,79 | miscible | très grande | flamme, point d'exclamation |\n| Cyclohexane | 0,78 | non miscible | très grande | flamme, point d'exclamation, arbre et poisson |\n| Dichlorométhane | 1,33 | non miscible | très grande | point d'exclamation, silhouette avec étoile |\n\n1. Rappelle les trois qualités d'un bon solvant extracteur.\n2. Pourquoi l'éthanol ne convient-il pas ?\n3. Entre le cyclohexane et le dichlorométhane, lequel Julie doit-elle choisir ? Justifie.\n4. Avec le solvant choisi, la phase contenant le limonène sera-t-elle en haut ou en bas de l'ampoule ? Justifie.\n5. Pourquoi faut-il dégazer régulièrement l'ampoule pendant l'agitation ?","bareme":[{"critere":"Trois qualités : non miscible, dissout mieux l'espèce, peu dangereux (et facile à éliminer)","points":5},{"critere":"Éthanol rejeté car miscible à l'eau : pas de deux phases","points":4},{"critere":"Cyclohexane choisi : danger moindre que le dichlorométhane (danger grave pour la santé)","points":5},{"critere":"Phase organique en haut car densité 0,78 < 1,00","points":4},{"critere":"Dégazage : évacuer la surpression des vapeurs","points":2}],"dureeMin":10,"corrige":"1. Un bon solvant extracteur doit : **ne pas être miscible** avec le premier solvant (ici l'eau) ; **mieux dissoudre** l'espèce à extraire ; être **peu dangereux** et, si possible, facile à éliminer (volatil).\n\n2. L'éthanol est **miscible** avec l'eau : il ne formerait pas deux phases, on ne pourrait pas séparer par décantation.\n\n3. Les deux sont non miscibles et dissolvent très bien le limonène. Le **dichlorométhane** porte la silhouette avec étoile : **danger grave pour la santé** (cancérogène, mutagène…). Le **cyclohexane** est inflammable, irritant et dangereux pour le milieu aquatique, mais c'est le **moins dangereux pour l'opérateur** : Julie choisit le **cyclohexane** (en travaillant loin de toute flamme, sous hotte, et en récupérant les déchets).\n\n4. La phase la plus **dense** est en bas. Le cyclohexane a une densité de 0,78, inférieure à celle de l'eau (1,00) : la phase organique, qui contient le limonène, est **en haut**.\n\n5. L'agitation fait passer des vapeurs de solvant dans l'ampoule fermée : la pression augmente. On **dégaze** pour évacuer cette **surpression** et éviter que le bouchon saute."}$exo$::jsonb),
  ('aad28990-b793-57bd-9233-a2f7393703d2'::uuid, 3, 'application', $exo${"titre":"Synthèse de l'arôme d'ananas","consigne":"Analyse le protocole étape par étape. Chaque réponse doit être justifiée par une donnée ou une notion du cours.","enonce":"**Protocole – Synthèse du butanoate d'éthyle (arôme d'ananas)**\n\n1. Dans un ballon de 100 mL, introduire 20 mL d'acide butanoïque, 25 mL d'éthanol (en excès), 1 mL d'acide sulfurique concentré et quelques grains de pierre ponce. Chauffer à reflux 30 minutes.\n2. Refroidir, verser le mélange dans une ampoule à décanter contenant 50 mL d'eau salée. Agiter, décanter, éliminer la phase aqueuse.\n3. Laver la phase organique avec une solution d'hydrogénocarbonate de sodium, en dégazant souvent. Décanter.\n4. Sécher la phase organique sur sulfate de magnésium anhydre, filtrer.\n5. Distiller.\n\n**Données**\n\n| Espèce | Densité | Température d'ébullition | Solubilité dans l'eau salée |\n|---|---|---|---|\n| Butanoate d'éthyle | 0,88 | 121 °C | très faible |\n| Éthanol | 0,79 | 78 °C | grande |\n| Acide butanoïque | 0,96 | 164 °C | grande |\n| Eau salée | 1,2 | — | — |\n\n1. Classe les étapes 1 à 5 en transformation, isolement et purification.\n2. Quel est le rôle de l'acide sulfurique ? Justifie le choix d'un ballon de 100 mL et le matériel pour mesurer les 25 mL d'éthanol.\n3. Étape 2 : pourquoi utiliser de l'eau salée plutôt que de l'eau pure ? Dans quelle phase se trouve l'ester ?\n4. Étape 3 : quelle espèce le lavage élimine-t-il ? Pourquoi faut-il dégazer ?\n5. Étape 5 : la distillation simple est-elle adaptée pour séparer l'ester de l'éthanol restant ? Quelle espèce est recueillie en premier ?","bareme":[{"critere":"Étapes classées : 1 transformation ; 2 isolement ; 3, 4 et 5 purification","points":3},{"critere":"Catalyseur ; ballon rempli au plus à moitié (environ 46 mL) ; éprouvette pour un réactif en excès","points":4},{"critere":"Relargage : le sel diminue la solubilité de l'ester ; ester dans la phase du haut (0,88 < 1,2)","points":5},{"critere":"Lavage : élimine l'acide restant ; dégazage à cause du CO₂ formé","points":4},{"critere":"Distillation adaptée (121 °C et 78 °C très différents) ; éthanol recueilli en premier","points":4}],"dureeMin":18,"corrige":"1. Étape 1 : **transformation** (chauffage à reflux). Étape 2 : **isolement** (extraction, décantation). Étapes 3, 4 et 5 : **purification** (lavage, séchage, distillation).\n\n2. L'acide sulfurique est un **catalyseur** : il accélère la réaction sans être consommé. Le volume total est d'environ 20 + 25 + 1 = 46 mL : un ballon de **100 mL** est **rempli au plus à moitié**, comme le veut la règle. L'éthanol est en **excès** : son volume n'a pas besoin d'être précis, on le mesure à l'**éprouvette**.\n\n3. Le sel **diminue la solubilité de l'ester dans l'eau** : c'est le **relargage**, qui améliore la séparation. L'ester a une densité de 0,88, inférieure à celle de l'eau salée (1,2) : il est dans la **phase du haut** (phase organique). L'éthanol et l'acide restants, solubles dans l'eau salée, passent en grande partie dans la phase aqueuse.\n\n4. La solution d'hydrogénocarbonate de sodium élimine l'**acide restant** (acide butanoïque et acide sulfurique). Cette réaction produit du **dioxyde de carbone** gazeux : la pression monte dans l'ampoule, il faut **dégazer** souvent.\n\n5. **Oui** : la distillation simple sépare des liquides de températures d'ébullition **très différentes** ; ici 78 °C pour l'éthanol et 121 °C pour l'ester. Le plus **volatil**, l'**éthanol**, se vaporise, se condense et est recueilli **en premier** ; on recueille ensuite l'ester vers 121 °C."}$exo$::jsonb),
  ('c3d67f85-7fa1-5f25-8445-4a93b12bdef7'::uuid, 1, 'application', $exo${"titre":"Le rendement de l'aspirine","consigne":"Détaille tes calculs et donne le rendement en pourcentage.","enonce":"**Situation.** Léo synthétise l'aspirine selon l'équation :\n\nacide salicylique + anhydride éthanoïque → aspirine + acide éthanoïque\n\nIl introduit 0,050 mol d'acide salicylique et 0,080 mol d'anhydride éthanoïque. Il récupère 6,3 g d'aspirine pure. Masse molaire de l'aspirine : M = 180 g·mol⁻¹.\n\nIl réalise ensuite une CCM : il dépose l'acide salicylique (dépôt 1), son produit (dépôt 2) et de l'aspirine pure du commerce (dépôt 3). Le dépôt 2 donne **une seule tache**, à la même hauteur que le dépôt 3 ; aucune tache au niveau du dépôt 1.\n\n1. Quel est le réactif limitant ? Justifie.\n2. Calcule la masse maximale d'aspirine m_max.\n3. Calcule le rendement de la synthèse.\n4. Que peut conclure Léo de sa CCM ?","bareme":[{"critere":"Réactif limitant : l'acide salicylique (0,050 < 0,080, coefficients 1)","points":4},{"critere":"m_max = 0,050 × 180 = 9,0 g","points":5},{"critere":"η = 6,3 / 9,0 = 70 %","points":5},{"critere":"CCM : produit identique à la référence, pur, sans réactif restant","points":6}],"dureeMin":7,"corrige":"1. Les coefficients sont tous égaux à 1 : x_max est la plus petite des quantités initiales. 0,050 mol < 0,080 mol : l'**acide salicylique** est le **réactif limitant** (l'anhydride est en excès).\n\n2. On obtient au plus n_max = 0,050 mol d'aspirine, soit m_max = n × M = 0,050 × 180 = **9,0 g**.\n\n3. η = m obtenue / m_max = 6,3 / 9,0 = 0,70, soit **70 %**. (Il est inférieur à 100 % : pertes lors des transferts et de la purification.)\n\n4. Le produit donne **une seule tache**, au même niveau que l'**aspirine de référence** : c'est bien de l'aspirine, et elle est **pure** (dans la limite de détection). Aucune tache au niveau de l'acide salicylique : il ne reste **pas de réactif** dans le produit."}$exo$::jsonb),
  ('c3d67f85-7fa1-5f25-8445-4a93b12bdef7'::uuid, 2, 'application', $exo${"titre":"Estérification : du volume au rendement","consigne":"Détaille chaque calcul avec sa formule et son unité.","enonce":"**Situation.** Pour préparer l'acétate d'isoamyle, Emma mélange 15,0 mL d'alcool isoamylique et 20,0 mL d'acide éthanoïque. L'équation est :\n\nalcool isoamylique + acide éthanoïque → acétate d'isoamyle + eau\n\n**Données**\n\n| Espèce | Masse volumique (g·mL⁻¹) | Masse molaire (g·mol⁻¹) |\n|---|---|---|\n| Alcool isoamylique | 0,81 | 88 |\n| Acide éthanoïque | 1,05 | 60 |\n| Acétate d'isoamyle | 0,87 | 130 |\n\nAprès purification, Emma récupère 12,6 g d'ester.\n\n1. Calcule les quantités de matière initiales des deux réactifs.\n2. Détermine le réactif limitant.\n3. Calcule la masse maximale d'ester.\n4. Calcule le rendement.\n5. Pourquoi a-t-on intérêt à mettre l'acide éthanoïque en excès ? Pourquoi le rendement reste-t-il inférieur à 100 % ?","bareme":[{"critere":"n = ρV/M : n(alcool) ≈ 0,138 mol et n(acide) = 0,350 mol","points":6},{"critere":"Alcool isoamylique identifié comme réactif limitant","points":3},{"critere":"m_max = 0,138 × 130 ≈ 18,0 g","points":4},{"critere":"η = 12,6 / 18,0 ≈ 70 %","points":3},{"critere":"Excès : consommer totalement le réactif précieux ; pertes (transferts, extraction, purification) et réaction limitée","points":4}],"dureeMin":12,"corrige":"1. n = ρ × V / M.\nAlcool isoamylique : n = 0,81 × 15,0 / 88 = 12,15 / 88 ≈ **0,138 mol**.\nAcide éthanoïque : n = 1,05 × 20,0 / 60 = 21,0 / 60 = **0,350 mol**.\n\n2. Coefficients égaux à 1 : x_max est la plus petite quantité, 0,138 mol. Le **réactif limitant est l'alcool isoamylique**.\n\n3. n_max(ester) = 0,138 mol ; m_max = 0,138 × 130 ≈ **18,0 g** (17,9 à 18,0 g selon les arrondis).\n\n4. η = 12,6 / 18,0 = 0,70, soit **70 %** (avec 17,95 g on trouve aussi 70 %).\n\n5. On met en **excès** le réactif le moins cher ou le plus facile à éliminer (l'acide, qu'on élimine au lavage) pour **consommer totalement** le réactif le plus précieux (l'alcool) et améliorer le rendement. Le rendement reste inférieur à 100 % car la **réaction est limitée** et qu'on **perd du produit** lors des transferts, de l'extraction et de la purification."}$exo$::jsonb),
  ('c3d67f85-7fa1-5f25-8445-4a93b12bdef7'::uuid, 3, 'application', $exo${"titre":"Aspirine brute ou purifiée ?","consigne":"Exploite toutes les données. Tes conclusions doivent s'appuyer sur les calculs et sur les contrôles de pureté.","enonce":"**Situation.** Rayan synthétise de l'aspirine :\n\nacide salicylique + anhydride éthanoïque → aspirine + acide éthanoïque\n\n**Données** : acide salicylique, M = 138 g·mol⁻¹ ; anhydride éthanoïque, M = 102 g·mol⁻¹, ρ = 1,08 g·mL⁻¹ ; aspirine, M = 180 g·mol⁻¹, température de fusion tabulée 135 °C.\n\n**Réactifs** : 5,52 g d'acide salicylique et 10,0 mL d'anhydride éthanoïque.\n\n**Résultats**\n\n| | Masse | Banc Kofler | CCM |\n|---|---|---|---|\n| Produit brut | 6,80 g | fond de 128 à 132 °C | deux taches : une au niveau de l'aspirine pure, une au niveau de l'acide salicylique |\n| Après recristallisation | 5,40 g | fond nettement à 135 °C | une seule tache, au niveau de l'aspirine pure |\n\n1. Calcule les quantités de matière initiales et détermine le réactif limitant.\n2. Calcule la masse maximale d'aspirine.\n3. Rayan annonce un rendement de 94 % avec le produit brut. Vérifie son calcul et explique pourquoi ce résultat n'a pas de sens.\n4. Analyse les contrôles de pureté du produit brut puis du produit recristallisé.\n5. Calcule le rendement réel de la synthèse. Comment le banc Kofler doit-il être préparé pour que la mesure soit fiable ?","bareme":[{"critere":"n(acide salicylique) = 0,0400 mol, n(anhydride) ≈ 0,106 mol, acide salicylique limitant","points":5},{"critere":"m_max = 0,0400 × 180 = 7,20 g","points":3},{"critere":"6,80 / 7,20 ≈ 94 % vérifié, mais produit brut impur : masse surestimée","points":4},{"critere":"Brut : fusion basse et sur un intervalle, tache de réactif ; recristallisé : fusion nette à 135 °C, une seule tache","points":5},{"critere":"Rendement réel 5,40 / 7,20 = 75 % ; banc étalonné avec des substances de fusion connue","points":3}],"dureeMin":20,"corrige":"1. n(acide salicylique) = m / M = 5,52 / 138 = **0,0400 mol**.\nn(anhydride) = ρ × V / M = 1,08 × 10,0 / 102 = 10,8 / 102 ≈ **0,106 mol**.\nCoefficients égaux à 1 : x_max = 0,0400 mol ; l'**acide salicylique est limitant**, l'anhydride est en excès.\n\n2. m_max = 0,0400 × 180 = **7,20 g**.\n\n3. 6,80 / 7,20 ≈ 0,944 : le calcul donne bien 94 %. Mais le rendement doit porter sur le produit **pur** : le produit brut contient encore des impuretés (dont de l'acide salicylique, visible en CCM). Sa masse est donc **surestimée** et ce rendement n'a pas de sens.\n\n4. **Produit brut** : il fond **plus bas** que 135 °C et **sur un intervalle** (128 à 132 °C) : c'est le signe d'un solide **impur**. La CCM montre une tache au niveau de l'acide salicylique : il reste du **réactif** non transformé ou non éliminé.\n**Produit recristallisé** : fusion **nette à 135 °C**, égale à la valeur tabulée ; **une seule tache** au niveau de l'aspirine de référence : le produit est de l'**aspirine pure** (dans la limite de détection). La recristallisation a éliminé les impuretés, restées dissoutes dans le solvant froid.\n\n5. η = 5,40 / 7,20 = **0,75, soit 75 %**. Le banc Kofler doit être **étalonné** avec des substances de température de fusion connue, de valeur proche de celle attendue."}$exo$::jsonb),
  ('63eeb696-8889-5ff9-9d88-d1440f713a96'::uuid, 1, 'application', $exo${"titre":"Quatre réactions à classer","consigne":"Nomme le type de chaque réaction et justifie en comparant réactifs et produits.","enonce":"**Situation.** Voici quatre réactions :\n\n- a) CH₃–CH=CH₂ + H₂ → CH₃–CH₂–CH₃\n- b) CH₃–CH₂–Cl + HO⁻ → CH₃–CH₂–OH + Cl⁻\n- c) CH₃–CH(OH)–CH₃ → CH₃–CH=CH₂ + H₂O\n- d) CH₃–COOH + HO⁻ → CH₃–COO⁻ + H₂O\n\n1. Donne le type de chaque réaction (substitution, addition, élimination ou acide-base) et justifie.\n2. Définis un site nucléophile et un site électrophile, avec un exemple de chaque.\n3. Que représente une flèche courbe, et d'où part-elle toujours ?","bareme":[{"critere":"Quatre types justes et justifiés : a addition, b substitution, c élimination, d acide-base","points":10},{"critere":"Définitions justes des sites nucléophile et électrophile, avec un exemple chacun","points":6},{"critere":"Flèche courbe : mouvement d'un doublet d'électrons, part toujours d'un doublet","points":4}],"dureeMin":7,"corrige":"1. a) **Addition** : deux molécules s'unissent et la double liaison C=C devient simple (hydrogénation d'un alcène).\nb) **Substitution** : l'atome de chlore est **remplacé** par le groupe OH.\nc) **Élimination** : l'alcool perd une petite molécule (H₂O) et une **double liaison apparaît** (déshydratation).\nd) **Acide-base** : transfert d'un ion **H⁺** de l'acide éthanoïque vers l'ion hydroxyde.\n\n2. Un **site nucléophile** est **riche en électrons** (doublet non liant, charge négative, charge partielle δ−, liaison multiple) : par exemple l'oxygène de HO⁻. Un **site électrophile** est **pauvre en électrons** (charge positive ou partielle δ+) : par exemple le carbone lié au chlore dans R–Cl, ou le carbone de C=O.\n\n3. Une flèche courbe représente le **mouvement d'un doublet d'électrons**. Elle part **toujours d'un doublet** (non liant ou liant) et pointe vers l'atome qui le reçoit ou vers la liaison qui va se former."}$exo$::jsonb),
  ('63eeb696-8889-5ff9-9d88-d1440f713a96'::uuid, 2, 'application', $exo${"titre":"Le chloroéthane rencontre l'ion hydroxyde","consigne":"Utilise les électronégativités fournies pour justifier tes réponses. Les flèches courbes sont à décrire en mots.","enonce":"**Données** – électronégativités : O (3,4) ; Cl (3,2) ; C (2,6) ; H (2,2).\n\n**Réaction étudiée** : CH₃–CH₂–Cl + HO⁻ → CH₃–CH₂–OH + Cl⁻\n\n1. Quel est le type de cette réaction ?\n2. Indique les charges partielles portées par les atomes de la liaison C–Cl. Justifie.\n3. Dans cette réaction, quel réactif apporte le site nucléophile, et quel atome est le site électrophile ? Justifie.\n4. Décris les deux flèches courbes qui modélisent la réaction : pour chacune, d'où elle part et où elle arrive.\n5. Dans la molécule de propanal CH₃–CH₂–CHO, repère un site électrophile. Justifie.","bareme":[{"critere":"Substitution identifiée","points":2},{"critere":"Cl δ− et C δ+ justifiés par l'électronégativité (3,2 > 2,6)","points":4},{"critere":"HO⁻ nucléophile (doublets non liants, charge négative) et carbone lié au chlore électrophile","points":5},{"critere":"Flèche 1 : doublet non liant de O vers le carbone δ+ ; flèche 2 : doublet de C–Cl vers Cl","points":6},{"critere":"Carbone du C=O du propanal électrophile (δ+, O plus électronégatif)","points":3}],"dureeMin":11,"corrige":"1. Le chlore est remplacé par OH : c'est une **substitution**.\n\n2. Le chlore (3,2) est plus électronégatif que le carbone (2,6) : il attire le doublet de la liaison. Le chlore porte une charge partielle **δ−**, le carbone une charge partielle **δ+**.\n\n3. L'ion **HO⁻** apporte le **site nucléophile** : son oxygène porte une charge négative et des doublets non liants, il est riche en électrons. Le **carbone lié au chlore** (δ+) est le **site électrophile**, pauvre en électrons. La réaction se fait entre ces deux sites : le nucléophile donne un doublet, l'électrophile le reçoit.\n\n4. **Flèche 1** : elle part d'un **doublet non liant de l'oxygène** de HO⁻ et pointe vers le **carbone δ+** : c'est la nouvelle liaison C–O qui se forme.\n**Flèche 2** : elle part du **doublet de la liaison C–Cl** et pointe vers l'**atome de chlore**, qui part sous forme d'ion **Cl⁻** en emportant ce doublet.\n\n5. Dans le groupe C=O du propanal, l'oxygène (3,4) est plus électronégatif que le carbone (2,6) : le **carbone du C=O** porte une charge δ+, c'est un **site électrophile** (l'oxygène, δ− et porteur de doublets non liants, est un site nucléophile)."}$exo$::jsonb),
  ('63eeb696-8889-5ff9-9d88-d1440f713a96'::uuid, 3, 'application', $exo${"titre":"De la propanone au propène","consigne":"Écris les formules semi-développées, nomme les produits et justifie chaque type de réaction.","enonce":"**Situation.** Au laboratoire, on enchaîne trois transformations à partir de la propanone CH₃–CO–CH₃.\n\n- **Étape 1** : la propanone réagit avec le dihydrogène H₂ (catalyseur métallique) et donne un produit P.\n- **Étape 2** : P est chauffé en milieu acide ; il se forme un produit gazeux Q et de l'eau.\n- **Étape 3** : dans une autre expérience, P est placé en milieu très basique : l'ion hydroxyde HO⁻ réagit avec P.\n\nDonnées – électronégativités : O (3,4) ; C (2,6) ; H (2,2).\n\n1. Écris l'équation de l'étape 1, nomme P et donne le type de réaction. À quelle famille appartient P ?\n2. Écris l'équation de l'étape 2, nomme Q et donne le type de réaction.\n3. Étape 3 : quel hydrogène de P est arraché ? Écris l'équation et donne le type de réaction.\n4. Explique pourquoi cet hydrogène est labile, alors que les hydrogènes liés aux carbones ne le sont pas.\n5. Décris les deux flèches courbes de l'étape 3.","bareme":[{"critere":"Étape 1 : CH₃–CO–CH₃ + H₂ → CH₃–CH(OH)–CH₃, propan-2-ol, addition, alcool secondaire","points":5},{"critere":"Étape 2 : propan-2-ol → CH₂=CH–CH₃ + H₂O, propène, élimination","points":4},{"critere":"Étape 3 : H lié à O arraché, formation de l'ion alcoolate et de l'eau, réaction acide-base","points":4},{"critere":"Labilité expliquée par la polarisation de O–H (3,4 > 2,2) ; C–H peu polarisée","points":3},{"critere":"Flèches : doublet de HO⁻ vers H ; doublet de O–H vers O","points":4}],"dureeMin":18,"corrige":"1. CH₃–CO–CH₃ + H₂ → CH₃–CH(OH)–CH₃. P est le **propan-2-ol**. C'est une **addition** (hydrogénation d'une cétone : la double liaison C=O devient simple). P est un **alcool secondaire**.\n\n2. CH₃–CH(OH)–CH₃ → CH₂=CH–CH₃ + H₂O. Q est le **propène**. C'est une **élimination** (déshydratation d'un alcool : la molécule perd H₂O et une double liaison C=C apparaît).\n\n3. L'hydrogène arraché est celui **lié à l'oxygène** : CH₃–CH(OH)–CH₃ + HO⁻ → CH₃–CH(O⁻)–CH₃ + H₂O. Il se forme un **ion alcoolate**. C'est une réaction **acide-base** (transfert d'un ion H⁺).\n\n4. L'oxygène (3,4) est bien plus électronégatif que l'hydrogène (2,2) : la liaison O–H est **polarisée**, l'hydrogène porte une charge δ+ et une base forte peut l'arracher sous forme de H⁺ : il est **labile**. Entre C (2,6) et H (2,2), l'écart est faible : la liaison C–H est peu polarisée, ces hydrogènes ne sont pas labiles.\n\n5. **Flèche 1** : d'un **doublet non liant de l'oxygène de HO⁻** vers l'**hydrogène** lié à l'oxygène de l'alcool (formation de la liaison O–H de l'eau).\n**Flèche 2** : du **doublet de la liaison O–H de l'alcool** vers l'**oxygène de l'alcool**, qui garde ce doublet et devient l'ion alcoolate R–O⁻."}$exo$::jsonb),
  ('a764617f-b186-572f-9f22-403bfffdd22e'::uuid, 1, 'application', $exo${"titre":"Tests d'ions et bandes infrarouges","consigne":"Réponds en t'appuyant sur les tableaux du cours.","enonce":"**Situation.** Zoé analyse plusieurs solutions et deux spectres.\n\n1. Elle ajoute quelques gouttes de soude à trois solutions. Elle observe : un précipité bleu (solution 1), un précipité rouille (solution 2), un précipité vert (solution 3). Quel ion contient chaque solution ?\n2. Quel réactif doit-elle utiliser pour mettre en évidence les ions chlorure ? Qu'observera-t-elle ?\n3. À quoi sert un témoin dans un test d'identification ?\n4. Sur un spectre infrarouge, elle observe une bande large vers 3 300 cm⁻¹. Sur un autre, une bande intense et fine vers 1 720 cm⁻¹. Quelle liaison révèle chaque bande ?\n5. Que renseigne la spectroscopie infrarouge sur une molécule ?","bareme":[{"critere":"Ions Cu²⁺, Fe³⁺ et Fe²⁺ correctement associés","points":6},{"critere":"Nitrate d'argent : précipité blanc qui noircit à la lumière","points":4},{"critere":"Témoin : comparer le résultat à une référence connue","points":3},{"critere":"O–H d'un alcool (large, 3 300) et C=O (intense, fine, 1 720)","points":5},{"critere":"L'IR renseigne sur les liaisons et groupes caractéristiques","points":2}],"dureeMin":7,"corrige":"1. Solution 1 : précipité **bleu** → ions **Cu²⁺**. Solution 2 : précipité **rouille** → ions **Fe³⁺**. Solution 3 : précipité **vert** → ions **Fe²⁺**.\n\n2. Elle utilise le **nitrate d'argent** : en présence d'ions chlorure, il se forme un **précipité blanc qui noircit à la lumière**.\n\n3. Le **témoin** permet de **comparer** le résultat obtenu à une **référence connue** (par exemple le même test sur une solution qui contient l'ion, ou sur de l'eau distillée) : on s'assure ainsi que l'observation vient bien de l'ion recherché.\n\n4. Bande **large** vers 3 300 cm⁻¹ : liaison **O–H d'un alcool** (élargie par les liaisons hydrogène). Bande **intense et fine** vers 1 720 cm⁻¹ : liaison **C=O**.\n\n5. La spectroscopie infrarouge excite les **vibrations des liaisons** : elle renseigne sur les **liaisons et les groupes caractéristiques** présents dans la molécule."}$exo$::jsonb),
  ('a764617f-b186-572f-9f22-403bfffdd22e'::uuid, 2, 'application', $exo${"titre":"Trois flacons sans étiquette","consigne":"Attribue chaque spectre à un flacon en justifiant par les bandes observées.","enonce":"**Situation.** Trois flacons ont perdu leur étiquette. On sait qu'ils contiennent de l'éthanol (un alcool), de l'acide éthanoïque (un acide carboxylique) et de l'éthanoate d'éthyle (un ester). On enregistre leurs spectres infrarouges :\n\n| Spectre | Bandes observées au-dessus de 1 500 cm⁻¹ |\n|---|---|\n| 1 | bande large et intense vers 3 300 cm⁻¹ ; bandes fines vers 2 900 cm⁻¹ ; rien entre 1 650 et 1 750 cm⁻¹ |\n| 2 | bandes fines vers 2 950 cm⁻¹ ; bande intense et fine à 1 740 cm⁻¹ ; aucune bande large au-dessus de 3 000 cm⁻¹ |\n| 3 | bande très large de 2 500 à 3 200 cm⁻¹ ; bande intense et fine à 1 710 cm⁻¹ |\n\n1. Quelle liaison est responsable des bandes fines vers 2 900 cm⁻¹, présentes dans les trois spectres ?\n2. Attribue chaque spectre à un flacon. Justifie.\n3. Calcule la longueur d'onde λ, en µm, correspondant au nombre d'onde σ = 1 740 cm⁻¹. Vérifie qu'elle appartient au domaine infrarouge.\n4. Pourquoi lit-on d'abord la zone au-dessus de 1 500 cm⁻¹ ?","bareme":[{"critere":"Bandes fines vers 2 900 cm⁻¹ attribuées aux liaisons C–H","points":3},{"critere":"Spectre 1 = éthanol, justifié par O–H d'alcool sans C=O","points":4},{"critere":"Spectre 2 = ester (C=O sans O–H) ; spectre 3 = acide (C=O et O–H très large)","points":6},{"critere":"λ = 1/σ ≈ 5,75 × 10⁻⁴ cm = 5,75 µm, dans le domaine 2,5 à 25 µm","points":5},{"critere":"Zone au-dessus de 1 500 cm⁻¹ : identifie les groupes caractéristiques","points":2}],"dureeMin":11,"corrige":"1. Les bandes fines entre 2 850 et 3 100 cm⁻¹ sont dues aux liaisons **C–H**, présentes dans les trois molécules.\n\n2. **Spectre 1 → éthanol** : bande **large** vers 3 300 cm⁻¹ = **O–H d'un alcool**, et aucune bande C=O.\n**Spectre 2 → éthanoate d'éthyle (ester)** : bande intense et fine à **1 740 cm⁻¹** = **C=O**, et **aucune bande O–H** : c'est un ester.\n**Spectre 3 → acide éthanoïque** : bande intense à 1 710 cm⁻¹ = **C=O**, et bande **très large** de 2 500 à 3 200 cm⁻¹ = **O–H d'un acide carboxylique**.\n\n3. σ = 1/λ, donc λ = 1/σ = 1 / 1 740 cm⁻¹ ≈ 5,75 × 10⁻⁴ cm = 5,75 × 10⁻⁶ m = **5,75 µm**. Cette valeur est comprise entre **2,5 et 25 µm** : c'est bien le domaine de l'**infrarouge**.\n\n4. La zone au-dessus de 1 500 cm⁻¹ permet d'**identifier les groupes caractéristiques** (O–H, C=O, N–H…). La zone en dessous (empreinte digitale) sert surtout à comparer avec un spectre de référence."}$exo$::jsonb),
  ('a764617f-b186-572f-9f22-403bfffdd22e'::uuid, 3, 'application', $exo${"titre":"Enquête sur un rejet coloré","consigne":"Mène l'enquête en exploitant chaque résultat. Justifie tes conclusions et signale ce qui reste incertain.","enonce":"**Situation.** Un laboratoire d'analyses reçoit un échantillon d'eau bleue prélevé près d'un atelier de traitement de surface. On réalise plusieurs analyses.\n\n**Résultats**\n\n| Analyse | Observation |\n|---|---|\n| Soude | précipité bleu |\n| Chlorure de baryum | précipité blanc |\n| Nitrate d'argent | aucun précipité |\n| Spectre UV-visible | absorption maximale dans le rouge |\n| Phase organique extraite, spectre IR | bande intense et fine à 1 715 cm⁻¹ ; bandes fines vers 2 950 cm⁻¹ ; aucune bande entre 2 500 et 3 500 cm⁻¹ en dehors des C–H |\n\nChaque test a été réalisé en parallèle sur de l'eau distillée : aucun précipité.\n\n1. Quels ions sont présents dans l'échantillon ? Lequel est absent ? Justifie.\n2. Explique pourquoi la solution paraît bleue, à l'aide du spectre UV-visible. Ce résultat est-il cohérent avec les tests ?\n3. Quel rôle ont joué les essais sur l'eau distillée ?\n4. Quel groupe de liaisons révèle le spectre IR de la phase organique ? Que peut-on exclure ?\n5. Pourquoi la spectroscopie UV-visible et la spectroscopie IR donnent-elles des informations différentes ?","bareme":[{"critere":"Cu²⁺ et SO₄²⁻ présents, Cl⁻ absent, chaque conclusion reliée au test","points":6},{"critere":"Absorbe le rouge donc paraît bleu-vert (couleur complémentaire), cohérent avec Cu²⁺","points":4},{"critere":"Témoin : les précipités viennent de l'échantillon, pas des réactifs ou de l'eau","points":2},{"critere":"Liaison C=O présente ; pas de O–H d'alcool ou d'acide, ni de N–H","points":5},{"critere":"UV-visible : électrons (couleur) ; IR : vibrations des liaisons","points":3}],"dureeMin":18,"corrige":"1. **Cu²⁺ présent** : la soude donne un précipité **bleu**. **SO₄²⁻ présent** : le chlorure de baryum donne un précipité **blanc**. **Cl⁻ absent** : le nitrate d'argent ne donne **aucun précipité** (il en donnerait un blanc noircissant à la lumière). L'eau contient donc probablement du **sulfate de cuivre**.\n\n2. La solution **absorbe le rouge** : elle prend la **couleur complémentaire**, le **bleu-vert** ; on la voit bleue. C'est **cohérent** avec la présence d'ions Cu²⁺ détectés par la soude, qui colorent les solutions en bleu.\n\n3. Ce sont des **témoins** : sur l'eau distillée, aucun précipité. Les précipités observés viennent donc bien des **ions de l'échantillon**, et non des réactifs ou de l'eau elle-même.\n\n4. La bande intense et fine à 1 715 cm⁻¹ révèle une liaison **C=O** ; les bandes vers 2 950 cm⁻¹ sont des **C–H**. Il n'y a **aucune bande O–H** (ni la bande large vers 3 300 d'un alcool, ni la bande très large de 2 500 à 3 200 d'un acide carboxylique) et **aucune bande N–H** : on exclut un alcool, un acide carboxylique et une amine. La molécule possède un groupe C=O sans O–H. Pour l'identifier exactement, il faudrait comparer toute la zone d'empreinte digitale avec des spectres de référence.\n\n5. L'**UV-visible** (200 à 800 nm) excite les **électrons** des molécules : elle renseigne sur la couleur et les liaisons conjuguées. L'**IR** (2,5 à 25 µm) excite les **vibrations des liaisons** : elle renseigne sur les groupes caractéristiques. Les deux sont complémentaires."}$exo$::jsonb),
  ('95b6d4cf-95b1-5a36-9c9d-d5fd225889f0'::uuid, 1, 'application', $exo${"titre":"Une droite d'étalonnage","consigne":"Détaille tes calculs et donne le résultat avec son unité.","enonce":"**Situation.** Pour doser le bleu patenté dans une boisson, Hugo prépare une gamme de solutions étalons et mesure leur absorbance à λmax :\n\n| c (× 10⁻⁵ mol·L⁻¹) | 1,0 | 2,0 | 3,0 | 4,0 |\n|---|---|---|---|---|\n| A | 0,13 | 0,26 | 0,39 | 0,52 |\n\nLa boisson donne une absorbance A = 0,34.\n\n1. Écris la loi de Beer-Lambert et nomme chaque grandeur avec son unité.\n2. Montre que A est proportionnelle à c et calcule le coefficient directeur k de la droite.\n3. Calcule la concentration en colorant de la boisson.\n4. Pourquoi règle-t-on le spectrophotomètre à λmax, et pourquoi fait-on d'abord le « zéro » avec le solvant ?","bareme":[{"critere":"A = ε × ℓ × c avec les quatre grandeurs et leurs unités","points":5},{"critere":"Rapport A/c constant, k = 1,3 × 10⁴ L·mol⁻¹","points":6},{"critere":"c = 0,34 / 13 000 ≈ 2,6 × 10⁻⁵ mol·L⁻¹","points":5},{"critere":"λmax : absorption maximale (mesure plus sensible) ; zéro : ne mesurer que l'absorption de l'espèce","points":4}],"dureeMin":8,"corrige":"1. **A = ε × ℓ × c** : A est l'absorbance (sans unité), ε le coefficient d'absorption molaire (L·mol⁻¹·cm⁻¹), ℓ la longueur de la cuve (cm), c la concentration (mol·L⁻¹).\n\n2. A / c = 0,13 / 1,0 × 10⁻⁵ = 0,26 / 2,0 × 10⁻⁵ = 0,39 / 3,0 × 10⁻⁵ = 0,52 / 4,0 × 10⁻⁵ = **1,3 × 10⁴ L·mol⁻¹** : le rapport est constant, A est **proportionnelle** à c (droite passant par l'origine). k = 13 000 L·mol⁻¹.\n\n3. c = A / k = 0,34 / 13 000 ≈ **2,6 × 10⁻⁵ mol·L⁻¹**. Cette valeur est bien comprise dans la gamme étalon.\n\n4. À **λmax**, l'absorbance est la plus grande : la mesure est la plus **sensible** et la plus précise. Le **zéro** avec le solvant permet de ne mesurer que l'absorption due à l'espèce dosée, pas celle du solvant ou de la cuve."}$exo$::jsonb),
  ('95b6d4cf-95b1-5a36-9c9d-d5fd225889f0'::uuid, 2, 'application', $exo${"titre":"Le vinaigre est-il conforme ?","consigne":"Détaille chaque étape du calcul. Donne les résultats avec trois chiffres significatifs.","enonce":"**Situation.** L'étiquette d'un vinaigre annonce une concentration en masse d'acide éthanoïque d'environ 84 g·L⁻¹. Lina dilue le vinaigre **10 fois**, puis titre V_A = 10,0 mL de la solution diluée par une solution d'hydroxyde de sodium de concentration C_B = 0,100 mol·L⁻¹, avec un suivi pH-métrique.\n\nÉquation de la réaction support : CH₃COOH + HO⁻ → CH₃COO⁻ + H₂O\n\nLe saut de pH permet de lire V_E = 14,2 mL. Masse molaire de l'acide éthanoïque : M = 60,0 g·mol⁻¹.\n\n1. Quelles conditions doit remplir une réaction support de titrage ?\n2. Définis l'équivalence. Quel réactif est limitant avant l'équivalence ?\n3. Comment Lina a-t-elle pu repérer précisément V_E sur la courbe pH = f(V) ?\n4. Calcule la concentration en acide éthanoïque de la solution diluée, puis du vinaigre.\n5. Calcule la concentration en masse du vinaigre et compare à l'étiquette.","bareme":[{"critere":"Réaction totale, rapide et unique","points":3},{"critere":"Équivalence : proportions stœchiométriques, changement de réactif limitant ; titrant limitant avant","points":4},{"critere":"Méthode des tangentes ou maximum de la dérivée dpH/dV","points":3},{"critere":"C_dil = 0,142 mol·L⁻¹ puis C = 1,42 mol·L⁻¹","points":6},{"critere":"Cm = 85,2 g·L⁻¹, proche des 84 g·L⁻¹ annoncés","points":4}],"dureeMin":12,"corrige":"1. La réaction support doit être **totale**, **rapide** et **unique**.\n\n2. À l'**équivalence**, les réactifs ont été introduits dans les **proportions stœchiométriques** : il y a changement de réactif limitant. **Avant** l'équivalence, le réactif limitant est le **titrant versé** (les ions HO⁻) ; après, c'est l'acide titré qui est épuisé.\n\n3. On repère le **saut de pH** et on lit V_E par la **méthode des tangentes** ou au **maximum de la dérivée** dpH/dV.\n\n4. Coefficients 1 et 1 : C_A × V_A = C_B × V_E, donc C_A = C_B × V_E / V_A = 0,100 × 14,2 / 10,0 = **0,142 mol·L⁻¹** (solution diluée).\nLe vinaigre a été dilué 10 fois : C(vinaigre) = 10 × 0,142 = **1,42 mol·L⁻¹**.\n\n5. Cm = C × M = 1,42 × 60,0 = **85,2 g·L⁻¹**. L'étiquette annonce environ 84 g·L⁻¹ : l'écart est de 1,2 g·L⁻¹, soit environ 1,4 % : le résultat est **cohérent** avec l'étiquette."}$exo$::jsonb),
  ('95b6d4cf-95b1-5a36-9c9d-d5fd225889f0'::uuid, 3, 'application', $exo${"titre":"Deux méthodes pour un même flacon de permanganate","consigne":"Mène les deux dosages puis compare-les de façon argumentée.","enonce":"**Situation.** On veut connaître la concentration C d'une solution de permanganate de potassium (ions MnO₄⁻, violets).\n\n**Méthode 1 – Étalonnage.** La solution est diluée **20 fois**. Une gamme d'étalons donne une droite A = k × c avec k = 2 300 L·mol⁻¹ à 525 nm. La solution diluée donne A = 0,46.\n\n**Méthode 2 – Titrage.** On place la solution de permanganate dans la burette. Dans le bécher : 10,0 mL d'une solution d'ions Fe²⁺ de concentration 2,00 × 10⁻² mol·L⁻¹, acidifiée. La teinte violette persiste à partir de V_E = 10,1 mL.\n\nÉquation : MnO₄⁻ + 5 Fe²⁺ + 8 H⁺ → Mn²⁺ + 5 Fe³⁺ + 4 H₂O\n\n1. Méthode 1 : calcule la concentration de la solution diluée, puis C. Pourquoi a-t-il fallu diluer la solution avant la mesure ?\n2. Méthode 2 : pourquoi la teinte violette qui persiste signale-t-elle l'équivalence ?\n3. Écris la relation à l'équivalence, puis calcule C.\n4. Les deux résultats sont-ils cohérents ?\n5. Compare les deux méthodes : espèce consommée ou non, condition nécessaire, point fort de chacune.","bareme":[{"critere":"c_dil = 2,0 × 10⁻⁴ mol·L⁻¹ puis C = 4,0 × 10⁻³ mol·L⁻¹ ; dilution car Beer-Lambert valable en solution assez diluée","points":5},{"critere":"Avant l'équivalence MnO₄⁻ est consommé et disparaît ; après, il est en excès et colore le milieu","points":3},{"critere":"n(Fe²⁺) = 5 n(MnO₄⁻) et C = 3,96 × 10⁻³ mol·L⁻¹","points":6},{"critere":"Résultats cohérents (écart d'environ 1 %)","points":2},{"critere":"Comparaison correcte des deux méthodes (espèce consommée ou non, condition, point fort)","points":4}],"dureeMin":20,"corrige":"1. c_dil = A / k = 0,46 / 2 300 = **2,0 × 10⁻⁴ mol·L⁻¹**. La solution a été diluée 20 fois : C = 20 × 2,0 × 10⁻⁴ = **4,0 × 10⁻³ mol·L⁻¹**. On dilue parce que la loi de Beer-Lambert (A proportionnelle à c) n'est valable que pour des solutions **assez diluées** ; la solution mère, très colorée, absorberait trop.\n\n2. Avant l'équivalence, les ions MnO₄⁻ versés sont **consommés** aussitôt par les ions Fe²⁺ (ils sont limitants) : la couleur violette disparaît. Après l'équivalence, les ions Fe²⁺ sont épuisés : MnO₄⁻ est en **excès** et colore le milieu en violet. Le permanganate sert lui-même d'indicateur de fin de titrage.\n\n3. À l'équivalence : n(Fe²⁺) / 5 = n(MnO₄⁻ versé), soit n(Fe²⁺) = 5 × C × V_E.\nn(Fe²⁺) = 2,00 × 10⁻² × 10,0 × 10⁻³ = 2,00 × 10⁻⁴ mol.\nn(MnO₄⁻) = 2,00 × 10⁻⁴ / 5 = 4,00 × 10⁻⁵ mol.\nC = 4,00 × 10⁻⁵ / 10,1 × 10⁻³ ≈ **3,96 × 10⁻³ mol·L⁻¹**.\n\n4. 4,0 × 10⁻³ et 3,96 × 10⁻³ mol·L⁻¹ : l'écart est d'environ 1 %. Les deux résultats sont **cohérents**.\n\n5. **Étalonnage** : l'espèce n'est **pas consommée** ; il faut une propriété mesurable **proportionnelle à c** (ici l'absorbance) et une gamme d'étalons ; point fort : rapide, adapté aux faibles concentrations. **Titrage** : l'espèce est **consommée** ; il faut une réaction support **totale, rapide et unique** ; point fort : exact, sans gamme à préparer."}$exo$::jsonb),
  ('84553740-9424-5e81-b623-8e151f93b6e9'::uuid, 1, 'application', $exo${"titre":"De la chambre noire à la rétine","consigne":"Réponds à chaque question par des phrases courtes et précises.","enonce":"**Situation.** Pour un exposé sur l'histoire de la photographie, Manon a noté quatre événements dans le désordre :\n\n- a) invention du capteur CCD ;\n- b) première image photographique durable, par Nicéphore Niépce ;\n- c) les frères Lumière commercialisent l'autochrome ;\n- d) le daguerréotype de Louis Daguerre est rendu public.\n\n1. Range ces quatre événements dans l'ordre chronologique et associe à chacun sa date.\n2. Recopie et complète le modèle optique de l'œil : iris et pupille → … ; cristallin (avec la cornée) → … ; rétine → … .\n3. Où doit se former l'image pour que l'œil voie net ? Comment l'œil fait-il pour voir de près ?\n4. Compare les cônes et les bâtonnets de la rétine : rôle et conditions d'éclairage.","bareme":[{"critere":"Ordre b (1826), d (1839), c (1907), a (1969) avec les dates justes","points":6},{"critere":"Modèle : diaphragme, lentille convergente, écran","points":6},{"critere":"Image sur la rétine ; accommodation : le cristallin se bombe","points":4},{"critere":"Cônes : couleurs, trois types ; bâtonnets : faible lumière, pas de couleurs","points":4}],"dureeMin":7,"corrige":"1. b) **1826** : Niépce fixe la première image photographique durable ; d) **1839** : le daguerréotype est rendu public ; c) **1907** : les frères Lumière commercialisent l'autochrome, premier procédé couleur ; a) **1969** : invention du capteur CCD, base de la photographie numérique.\n\n2. Iris et pupille → **diaphragme** (règle la quantité de lumière) ; cristallin avec la cornée → **lentille convergente** de vergence variable ; rétine → **écran** sur lequel se forme l'image.\n\n3. L'image doit se former **sur la rétine**. Pour voir de près, l'œil **accommode** : le cristallin se **bombe**, il devient plus convergent.\n\n4. Les **cônes** (environ 6 millions, concentrés dans la fovéa) permettent la **vision des couleurs** ; il en existe **trois types**, sensibles au bleu, au vert et au rouge ; ils ont besoin de lumière. Les **bâtonnets** (environ 120 millions) sont très sensibles et fonctionnent en **faible lumière**, mais ne distinguent **pas les couleurs**."}$exo$::jsonb),
  ('84553740-9424-5e81-b623-8e151f93b6e9'::uuid, 2, 'application', $exo${"titre":"Lumières de scène","consigne":"Justifie chaque réponse en précisant le type de synthèse des couleurs mis en jeu.","enonce":"**Situation.** Pour la fête du lycée, Enzo règle l'éclairage de la scène. Il dispose de trois projecteurs, rouge, vert et bleu, qu'il dirige sur un grand écran blanc. Il a aussi un projecteur de lumière blanche devant lequel il peut placer des filtres.\n\n1. Quelle couleur voit-on sur l'écran blanc éclairé par les projecteurs rouge et vert ? Par les trois projecteurs à la fois ? De quelle synthèse s'agit-il ?\n2. Enzo place un filtre jaune devant le projecteur blanc. Quelle(s) lumière(s) le filtre transmet-il, et laquelle absorbe-t-il ?\n3. Une danseuse porte une robe rouge. Quelle couleur a sa robe éclairée : a) en lumière blanche ? b) par le seul projecteur bleu ? Justifie.\n4. Sur l'affiche de la fête, imprimée, on superpose des encres. Quelles sont les couleurs primaires utilisées et que donne la superposition des trois ?","bareme":[{"critere":"Rouge + vert = jaune ; les trois = blanc ; synthèse additive","points":5},{"critere":"Filtre jaune : transmet rouge et vert, absorbe le bleu","points":4},{"critere":"Robe rouge : rouge en lumière blanche, noire en lumière bleue, justifié par la diffusion","points":6},{"critere":"Synthèse soustractive : cyan, magenta, jaune ; superposition noire","points":5}],"dureeMin":10,"corrige":"1. On **ajoute** des lumières : c'est la **synthèse additive**. Rouge + vert = **jaune**. Rouge + vert + bleu = **blanc**.\n\n2. Un filtre transmet sa propre couleur et absorbe les autres. Jaune = rouge + vert : le filtre **transmet le rouge et le vert** et **absorbe le bleu**. On voit une lumière jaune.\n\n3. a) En lumière blanche, la robe **diffuse le rouge** et absorbe les autres couleurs : elle paraît **rouge**.\nb) Éclairée en lumière bleue seulement, la robe absorbe le bleu et n'a **plus de rouge à diffuser** : elle paraît **noire**.\n\n4. L'impression utilise la **synthèse soustractive** : des pigments retirent des lumières. Les couleurs primaires sont le **cyan**, le **magenta** et le **jaune**. Leur superposition donne du **noir**."}$exo$::jsonb),
  ('84553740-9424-5e81-b623-8e151f93b6e9'::uuid, 3, 'application', $exo${"titre":"Aya au concert","consigne":"Réponds de façon argumentée en mobilisant l'optique de l'œil, la couleur des objets et le droit de l'image.","enonce":"**Situation.** Aya est myope. Au concert du lycée, elle a oublié ses lunettes : la chanteuse, au fond de la salle, lui paraît floue. La scène est éclairée uniquement par un projecteur rouge et un projecteur bleu. La chanteuse porte une chemise blanche et un chapeau vert.\n\nAvec son téléphone, Aya photographie son ami Jules dans le public, puis enregistre une photo de la chanteuse publiée par un photographe professionnel. Le soir, elle veut publier les deux photos sur son compte public.\n\n1. Explique pourquoi Aya voit flou la chanteuse : où se forme l'image, et pour quelle raison ? Quel type de lentille corrige ce défaut ?\n2. Quelle couleur Aya voit-elle pour la chemise ? Pour le chapeau ? Justifie.\n3. Quels types de cônes de la rétine d'Aya sont surtout stimulés par la lumière diffusée par la chemise ?\n4. À la fin du concert, les projecteurs baissent jusqu'à une très faible lumière. Aya distingue encore les formes mais plus les couleurs. Explique.\n5. Aya peut-elle publier les deux photos ? Explique en distinguant les deux droits en jeu.","bareme":[{"critere":"Myopie : œil trop convergent, image avant la rétine, correction par lentille divergente","points":4},{"critere":"Chemise magenta (rouge + bleu diffusés), chapeau noir (pas de vert à diffuser)","points":5},{"critere":"Cônes sensibles au rouge et au bleu","points":3},{"critere":"Faible lumière : seuls les bâtonnets fonctionnent, ils ne distinguent pas les couleurs","points":3},{"critere":"Droit à l'image (accord de Jules) et droit d'auteur (autorisation du photographe) distingués","points":5}],"dureeMin":18,"corrige":"1. L'œil myope est **trop convergent** : l'image d'un objet éloigné se forme **avant la rétine**, pas sur elle, d'où le flou. On corrige la myopie avec une lentille **divergente**.\n\n2. La **chemise blanche** diffuse toutes les couleurs qu'elle reçoit ; elle ne reçoit que du rouge et du bleu : elle diffuse rouge + bleu, elle paraît **magenta** (synthèse additive). Le **chapeau vert** ne diffuse que le vert ; il ne reçoit pas de vert : il absorbe le rouge et le bleu et paraît **noir**.\n\n3. La lumière diffusée par la chemise contient du rouge et du bleu : ce sont surtout les **cônes sensibles au rouge** et les **cônes sensibles au bleu** qui sont stimulés. Le cerveau reconstruit la couleur magenta à partir de leurs réponses.\n\n4. En très faible lumière, les cônes ne fonctionnent plus ; seuls les **bâtonnets**, très sensibles, permettent de voir. Or ils **ne distinguent pas les couleurs** : Aya voit les formes, en nuances de gris.\n\n5. **Photo de Jules** : le **droit à l'image** protège la personne photographiée ; Jules est reconnaissable, Aya doit obtenir **son accord** avant de publier. **Photo du photographe** : le **droit d'auteur** protège le créateur d'une photographie originale ; Aya ne peut pas la diffuser sans son **autorisation** (sauf exception, comme une courte citation avec mention de l'auteur, ce qui n'est pas le cas d'une republication). En l'état, elle ne peut publier aucune des deux photos sans accord."}$exo$::jsonb),
  ('a546fa4b-ed58-5240-92e7-6b98b002abb8'::uuid, 1, 'application', $exo${"titre":"L'image d'une bougie","consigne":"Utilise des mesures algébriques. Détaille tes calculs.","enonce":"**Situation.** Une bougie AB de hauteur 4,0 cm est placée à 60 cm avant une lentille mince convergente de distance focale f' = 20 cm. A est sur l'axe optique.\n\n1. Calcule la vergence V de la lentille, avec son unité.\n2. Donne la valeur algébrique de OA.\n3. Utilise la relation de conjugaison pour calculer OA'. L'image est-elle réelle ou virtuelle ?\n4. Calcule le grandissement γ et la taille A'B' de l'image. Décris l'image.\n5. Cite les trois rayons particuliers qui permettent de construire l'image.","bareme":[{"critere":"V = 1 / 0,20 = 5,0 δ","points":3},{"critere":"OA = −60 cm","points":2},{"critere":"OA' = 30 cm par la relation de conjugaison, image réelle","points":6},{"critere":"γ = −0,5, A'B' = −2,0 cm : image renversée, deux fois plus petite","points":5},{"critere":"Trois rayons particuliers justes","points":4}],"dureeMin":8,"corrige":"1. V = 1 / f' avec f' en mètres : V = 1 / 0,20 = **5,0 δ** (dioptries).\n\n2. L'objet est réel, avant la lentille : **OA = −60 cm**.\n\n3. 1/OA' − 1/OA = 1/f', donc 1/OA' = 1/f' + 1/OA = 1/20 − 1/60 = 3/60 − 1/60 = 2/60 = 1/30. **OA' = 30 cm**. OA' > 0 : l'image se forme après la lentille, elle est **réelle** (on peut la recueillir sur un écran).\n\n4. γ = OA' / OA = 30 / (−60) = **−0,5**. A'B' = γ × AB = −0,5 × 4,0 = **−2,0 cm**. γ < 0 : l'image est **renversée** ; |γ| < 1 : elle est **deux fois plus petite** que l'objet.\n\n5. Un rayon passant par le **centre optique O** n'est pas dévié ; un rayon **parallèle à l'axe** ressort en passant par le **foyer image F'** ; un rayon passant par le **foyer objet F** ressort **parallèle à l'axe**."}$exo$::jsonb),
  ('a546fa4b-ed58-5240-92e7-6b98b002abb8'::uuid, 2, 'application', $exo${"titre":"Le projecteur de diapositives","consigne":"Modélise l'objectif par une lentille mince convergente. Justifie chaque résultat par un calcul.","enonce":"**Situation.** Le club photo projette de vieilles diapositives de format 24 mm × 36 mm. L'objectif du projecteur est modélisé par une lentille convergente de distance focale f' = 10,0 cm. La diapositive est placée à 10,5 cm avant la lentille.\n\n1. Calcule la vergence de l'objectif.\n2. À quelle distance de la lentille faut-il placer l'écran pour obtenir une image nette ?\n3. Calcule le grandissement, puis les dimensions de l'image sur l'écran.\n4. Les diapositives sont glissées « à l'envers » dans le projecteur. Explique pourquoi.\n5. Pourquoi l'image obtenue ici n'est-elle pas une image de loupe ?","bareme":[{"critere":"V = 10 δ","points":2},{"critere":"OA = −10,5 cm et OA' = 210 cm (2,10 m) par la relation de conjugaison","points":7},{"critere":"γ = −20 et image de 48 cm × 72 cm","points":6},{"critere":"γ < 0 : image renversée, d'où la diapositive retournée","points":3},{"critere":"Objet au-delà de F : image réelle ; la loupe exige un objet entre F et O","points":2}],"dureeMin":11,"corrige":"1. V = 1 / f' = 1 / 0,100 = **10 δ**.\n\n2. OA = −10,5 cm. 1/OA' = 1/f' + 1/OA = 1/10,0 − 1/10,5 = 0,1000 − 0,0952 = 0,00476 cm⁻¹ (valeur exacte 1/210). **OA' = 210 cm** : l'écran doit être à **2,10 m** de la lentille.\n\n3. γ = OA' / OA = 210 / (−10,5) = **−20**. Dimensions : 24 mm × 20 = 480 mm = **48 cm** ; 36 mm × 20 = 720 mm = **72 cm**. L'image mesure **48 cm × 72 cm**.\n\n4. γ < 0 : l'image est **renversée** par rapport à l'objet. Pour que les spectateurs voient l'image à l'endroit, on place la diapositive à l'envers.\n\n5. La diapositive est placée **au-delà du foyer objet** (10,5 cm > 10,0 cm) : l'image est **réelle**, recueillie sur l'écran. L'effet loupe n'existe que si l'objet est **entre F et O** : l'image est alors virtuelle, droite, et ne peut pas être projetée."}$exo$::jsonb),
  ('a546fa4b-ed58-5240-92e7-6b98b002abb8'::uuid, 3, 'application', $exo${"titre":"Focométrie et loupe","consigne":"Exploite les mesures. Donne le résultat final avec son incertitude-type et justifie chaque conclusion.","enonce":"**Situation.** Pour vérifier la distance focale d'une lentille annoncée à f' = 12,5 cm, Noah forme sur un écran l'image nette d'un objet lumineux pour quatre positions. Il relève :\n\n| Mesure | 1 | 2 | 3 | 4 |\n|---|---|---|---|---|\n| OA (cm) | −20,0 | −25,0 | −30,0 | −40,0 |\n| OA' (cm) | 33,5 | 25,2 | 21,3 | 18,1 |\n| f' calculée (cm) | ? | 12,55 | 12,46 | 12,46 |\n\nL'écart-type des quatre valeurs de f' vaut s = 0,045 cm.\n\n1. Calcule f' pour la mesure 1 à l'aide de la relation de conjugaison.\n2. Calcule la moyenne des quatre valeurs de f' et l'incertitude-type sur cette moyenne. Écris le résultat.\n3. Le résultat est-il compatible avec la valeur annoncée ? Justifie par un calcul.\n4. Noah utilise ensuite cette lentille comme loupe : il place un timbre à 8,0 cm de la lentille. Calcule la position de l'image et le grandissement.\n5. Décris cette image et explique pourquoi elle ne peut pas être recueillie sur un écran.","bareme":[{"critere":"f'₁ = 1 / (1/33,5 + 1/20,0) ≈ 12,52 cm","points":4},{"critere":"Moyenne ≈ 12,50 cm, u = s/√4 ≈ 0,02 cm, résultat écrit","points":5},{"critere":"z = |12,50 − 12,5| / 0,02 ≈ 0 ≤ 2 : compatible","points":3},{"critere":"OA' ≈ −22,2 cm et γ ≈ 2,8","points":5},{"critere":"Image virtuelle, droite, agrandie, du même côté que l'objet : les rayons ressortent divergents","points":3}],"dureeMin":20,"corrige":"1. 1/f' = 1/OA' − 1/OA = 1/33,5 − 1/(−20,0) = 0,02985 + 0,05000 = 0,07985 cm⁻¹. **f'₁ ≈ 12,52 cm**.\n\n2. Moyenne : (12,52 + 12,55 + 12,46 + 12,46) / 4 = 49,99 / 4 ≈ **12,50 cm**. Évaluation de type A : u = s / √n = 0,045 / √4 = 0,045 / 2 ≈ **0,02 cm** (0,023 cm). Résultat : **f' = 12,50 cm avec u(f') = 0,02 cm**.\n\n3. z = |12,50 − 12,5| / 0,02 ≈ **0** (bien inférieur à 2) : le résultat est **compatible** avec la valeur annoncée.\n\n4. OA = −8,0 cm (objet entre F et O, car 8,0 cm < 12,5 cm). 1/OA' = 1/f' + 1/OA = 1/12,5 − 1/8,0 = 0,080 − 0,125 = −0,045 cm⁻¹. **OA' ≈ −22,2 cm**. γ = OA' / OA = (−22,2) / (−8,0) ≈ **2,8**.\n\n5. OA' < 0 : l'image est du **même côté que l'objet**, elle est **virtuelle**. γ > 0 : elle est **droite** ; |γ| > 1 : elle est **agrandie** (environ 2,8 fois). Les rayons ressortent de la lentille **divergents** : ils ne se croisent pas après la lentille, aucune image ne se forme sur un écran ; seul l'œil qui regarde à travers la lentille voit l'image : c'est le principe de la **loupe**."}$exo$::jsonb),
  ('93495817-b48c-5f4c-943c-49e859698714'::uuid, 1, 'application', $exo${"titre":"Le nombre d'ouverture","consigne":"Réponds en justifiant par un calcul ou par le modèle de l'appareil photographique.","enonce":"**Situation.** Lou découvre l'appareil photo numérique de sa grand-mère.\n\n1. Associe chaque élément réel à son modèle : objectif, diaphragme, capteur (lentille convergente, écran, ouverture circulaire de diamètre D).\n2. L'objectif a une focale f' = 50 mm et le diamètre de l'ouverture vaut D = 25 mm. Calcule le nombre d'ouverture N.\n3. Avec un téléobjectif de focale 200 mm réglé à f/4, quel est le diamètre de l'ouverture ?\n4. Entre les réglages f/2 et f/8, lequel laisse entrer le plus de lumière ? Justifie.\n5. Qu'appelle-t-on la mise au point ?","bareme":[{"critere":"Objectif = lentille convergente, diaphragme = ouverture de diamètre D, capteur = écran","points":4},{"critere":"N = 50 / 25 = 2 (f/2)","points":4},{"critere":"D = f'/N = 200 / 4 = 50 mm","points":4},{"critere":"f/2 : petit N, grande ouverture, plus de lumière","points":4},{"critere":"Mise au point : placer le capteur là où se forme l'image nette","points":4}],"dureeMin":7,"corrige":"1. **Objectif** → lentille convergente de focale f' (forme l'image) ; **diaphragme** → ouverture circulaire de diamètre D (dose la lumière) ; **capteur** → écran (reçoit l'image).\n\n2. N = f' / D = 50 / 25 = **2**, noté f/2.\n\n3. N = f' / D donc D = f' / N = 200 / 4 = **50 mm**.\n\n4. **f/2** : un **petit** nombre d'ouverture correspond à une **grande** ouverture, donc beaucoup de lumière. À f/8, le diamètre de l'ouverture est 4 fois plus petit (pour une même focale) : beaucoup moins de lumière.\n\n5. La **mise au point** consiste à placer le **capteur** là où se forme l'**image nette** : on déplace l'objectif selon la distance du sujet (relation de conjugaison)."}$exo$::jsonb),
  ('93495817-b48c-5f4c-943c-49e859698714'::uuid, 2, 'application', $exo${"titre":"Même exposition, autre réglage","consigne":"Justifie chaque réponse par le lien entre ouverture, temps de pose et quantité de lumière reçue.","enonce":"**Situation.** Karim photographie un match de handball. L'appareil propose une exposition correcte avec le réglage **f/8 et 1/125 s**.\n\nSérie des nombres d'ouverture : f/2 ; f/2,8 ; f/4 ; f/5,6 ; f/8 ; f/11 ; f/16.\n\n1. Karim passe à f/4. Par combien la lumière reçue par le capteur est-elle multipliée ? Justifie de deux façons (crans de la série, et variation en 1/N²).\n2. Quel temps de pose doit-il choisir pour garder la même exposition ? Quel est l'intérêt de ce réglage pour un match ?\n3. Son amie propose au contraire f/16. Quel temps de pose faut-il alors ? Quel risque cela présente-t-il ?\n4. Lequel des deux réglages (f/4 ou f/16) donne la plus grande profondeur de champ ?","bareme":[{"critere":"f/8 → f/4 : deux crans, lumière × 4, confirmé par (8/4)² = 4","points":6},{"critere":"Temps de pose 1/500 s, qui fige le mouvement","points":5},{"critere":"f/16 : lumière ÷ 4, temps 1/30 s environ, risque de flou de bougé","points":6},{"critere":"f/16 donne la plus grande profondeur de champ (N plus grand)","points":3}],"dureeMin":11,"corrige":"1. De f/8 à f/5,6 puis à f/4 : **deux crans**. Chaque cran vers un nombre plus petit double la surface de l'ouverture, donc la lumière : × 2 × 2 = **× 4**. Avec l'éclairement qui varie comme 1/N² : (8 / 4)² = **4**.\n\n2. L'énergie reçue est proportionnelle à l'éclairement × le temps de pose. La lumière est multipliée par 4 : il faut **diviser le temps de pose par 4** : 1/125 ÷ 4 = **1/500 s**. Un temps de pose **court** **fige le mouvement** des joueurs.\n\n3. De f/8 à f/16 : deux crans vers la fermeture, la lumière est **divisée par 4** ((16/8)² = 4). Il faut **multiplier** le temps de pose par 4 : 4/125 s = 1/31,25 s, soit environ **1/30 s**. Temps long : risque de **flou de bougé** (les joueurs bougent, et l'appareil tenu à la main aussi).\n\n4. La profondeur de champ **augmente** quand le nombre d'ouverture augmente : **f/16** donne la plus grande profondeur de champ."}$exo$::jsonb),
  ('93495817-b48c-5f4c-943c-49e859698714'::uuid, 3, 'application', $exo${"titre":"Trois photos, trois réglages","consigne":"Choisis et justifie les réglages à l'aide du modèle de l'appareil. Tous les calculs doivent être détaillés.","enonce":"**Situation.** Élise a un appareil dont le capteur compte 6 000 × 4 000 pixels. Elle dispose d'un objectif de focale 50 mm (ouvrant jusqu'à f/2) et d'un zoom qui va de 24 mm à 200 mm.\n\n**Photo 1 – Portrait** de son frère à 2,00 m, arrière-plan flou.\n**Photo 2 – Paysage** de montagne, net du premier plan à l'horizon.\n**Photo 3 – Oiseau** posé sur une branche lointaine, dans la pénombre du soir.\n\n1. Calcule le nombre de pixels du capteur.\n2. Photo 1 : avec l'objectif de 50 mm, à quelle distance de la lentille doit se trouver le capteur ? De combien l'objectif doit-il avancer par rapport à la mise au point sur un objet très lointain ?\n3. Photo 1 : quel nombre d'ouverture choisir ? Justifie.\n4. Photo 2 : quelle focale et quelle ouverture choisir ? Justifie.\n5. Photo 3 : quelle focale choisir, et pourquoi ? Pour compenser la faible lumière, Élise peut augmenter la sensibilité ISO : quel en est l'inconvénient ?","bareme":[{"critere":"24 millions de pixels","points":2},{"critere":"OA' = 1 / (1/50 − 1/2000) ≈ 51,3 mm ; avance d'environ 1,3 mm par rapport au plan focal","points":6},{"critere":"Portrait : grande ouverture (f/2), faible profondeur de champ","points":4},{"critere":"Paysage : courte focale (grand-angle) et grand N (f/11) pour une grande profondeur de champ","points":4},{"critere":"Oiseau : longue focale (200 mm), petit angle de champ ; ISO élevé = bruit plus visible","points":4}],"dureeMin":20,"corrige":"1. 6 000 × 4 000 = 24 000 000, soit **24 millions de pixels**.\n\n2. OA = −2,00 m = −2 000 mm ; f' = 50 mm. 1/OA' = 1/f' + 1/OA = 1/50 − 1/2 000 = 40/2 000 − 1/2 000 = 39/2 000. **OA' = 2 000 / 39 ≈ 51,3 mm**. Pour un objet très lointain, l'image se forme dans le plan focal image, à 50 mm. L'objectif doit donc être éloigné du capteur d'environ **1,3 mm** de plus.\n\n3. Pour isoler le sujet sur un arrière-plan flou, il faut une **faible profondeur de champ** : on choisit une **grande ouverture**, donc un **petit nombre d'ouverture**, par exemple **f/2**.\n\n4. Pour un paysage net du premier plan à l'horizon, il faut une **grande profondeur de champ** : **grand nombre d'ouverture** (f/11 par exemple) et **focale courte** (24 mm, grand-angle), qui augmente aussi la profondeur de champ et donne un **grand angle de champ** pour voir large. Le temps de pose sera plus long, ce qui ne gêne pas pour un paysage immobile (appareil stable).\n\n5. **Longue focale** (200 mm, téléobjectif) : l'angle de champ **diminue** quand la focale augmente, on voit un détail lointain en grand. Augmenter la **sensibilité ISO** amplifie le signal et permet de photographier dans la pénombre, mais au prix d'un **bruit** (grain) plus visible sur l'image."}$exo$::jsonb),
  ('1e2dfded-f4e7-5e6f-b057-58b12eee8ba2'::uuid, 1, 'application', $exo${"titre":"Le poids d'une image Full HD","consigne":"Détaille tes calculs et précise les unités.","enonce":"**Situation.** Une image d'écran « Full HD » compte 1 920 × 1 080 pixels, codée en RVB 24 bits.\n\n1. Sur combien de bits est codée chaque composante ? Combien de valeurs peut-elle prendre ?\n2. Calcule le nombre de pixels de l'image, puis sa taille en octets et en Mo, sans compression.\n3. Quelle serait sa taille en niveaux de gris sur 8 bits ?\n4. Quelle couleur correspond à chacun des codes suivants : (255, 0, 255) ; (0, 255, 255) ; (0, 0, 0) ; (128, 128, 128) ?","bareme":[{"critere":"8 bits par composante, 256 valeurs (0 à 255)","points":4},{"critere":"2 073 600 pixels ; 6 220 800 octets ≈ 6,2 Mo","points":7},{"critere":"Niveaux de gris : 2 073 600 octets ≈ 2,1 Mo","points":3},{"critere":"Magenta, cyan, noir, gris moyen","points":6}],"dureeMin":7,"corrige":"1. En RVB 24 bits, chaque composante est codée sur **8 bits** : elle prend 2⁸ = **256 valeurs**, de 0 à 255.\n\n2. Nombre de pixels : 1 920 × 1 080 = **2 073 600 pixels**. Chaque pixel occupe 24 bits = 3 octets. Taille : 2 073 600 × 3 = **6 220 800 octets ≈ 6,2 Mo** (1 Mo = 10⁶ octets).\n\n3. En niveaux de gris sur 8 bits : 1 octet par pixel, soit 2 073 600 octets ≈ **2,1 Mo**, trois fois moins.\n\n4. (255, 0, 255) : rouge + bleu = **magenta**. (0, 255, 255) : vert + bleu = **cyan**. (0, 0, 0) : **noir**. (128, 128, 128) : **gris moyen**."}$exo$::jsonb),
  ('1e2dfded-f4e7-5e6f-b057-58b12eee8ba2'::uuid, 2, 'application', $exo${"titre":"Envoyer les photos du voyage","consigne":"Détaille tes calculs et fais attention aux unités (octets et bits).","enonce":"**Situation.** Au retour d'un voyage scolaire, Ambre veut envoyer 20 photos à la classe. Son appareil a un capteur de 6 000 × 4 000 pixels et enregistre en RVB 24 bits. Sa connexion a un débit de 100 Mbit·s⁻¹.\n\n1. Calcule la taille d'une photo non compressée, puis celle des 20 photos, en octets.\n2. Calcule la durée de transmission des 20 photos non compressées. Exprime-la en minutes et secondes.\n3. En JPEG, chaque photo ne pèse plus que 6,0 Mo. Calcule la nouvelle durée de transmission.\n4. Quel est l'intérêt de la compression JPEG, et quelle peut être sa contrepartie ?\n5. Recopie dans l'ordre les maillons de la chaîne de transmission : récepteur, codage, canal, source, affichage, émetteur, décodage.","bareme":[{"critere":"72 Mo par photo, 1,44 × 10⁹ octets pour les 20","points":4},{"critere":"Conversion en bits (× 8) et durée ≈ 115 s, soit 1 min 55 s","points":6},{"critere":"JPEG : 120 Mo = 9,6 × 10⁸ bits, durée 9,6 s","points":4},{"critere":"Compression : fichier plus léger, parfois perte de qualité","points":3},{"critere":"Ordre : source, codage, émetteur, canal, récepteur, décodage, affichage","points":3}],"dureeMin":12,"corrige":"1. Nombre de pixels : 6 000 × 4 000 = 24 × 10⁶. Taille d'une photo : 24 × 10⁶ × 3 = **72 × 10⁶ octets = 72 Mo**. Pour 20 photos : 20 × 72 × 10⁶ = **1,44 × 10⁹ octets** (1,44 Go).\n\n2. Taille en bits : 1,44 × 10⁹ × 8 = 1,152 × 10¹⁰ bits. Débit : 100 Mbit·s⁻¹ = 1,00 × 10⁸ bit·s⁻¹. Durée = taille / débit = 1,152 × 10¹⁰ / 1,00 × 10⁸ = **115,2 s**, soit **1 min 55 s** environ.\n\n3. 20 × 6,0 Mo = 120 Mo = 1,2 × 10⁸ octets = 9,6 × 10⁸ bits. Durée = 9,6 × 10⁸ / 1,00 × 10⁸ = **9,6 s**.\n\n4. La compression JPEG **réduit fortement la taille** du fichier (ici 12 fois) : stockage et transmission plus rapides. Contrepartie : une **perte de qualité** possible.\n\n5. **Source** (fichier) → **codage** → **émetteur** → **canal** → **récepteur** → **décodage** → **affichage**."}$exo$::jsonb),
  ('1e2dfded-f4e7-5e6f-b057-58b12eee8ba2'::uuid, 3, 'application', $exo${"titre":"Du capteur à l'affiche","consigne":"Mène chaque calcul jusqu'au bout et conclus pour chaque question par une phrase. Donnée : 1 pouce = 2,54 cm.","enonce":"**Situation.** Le lycée organise une exposition photo. Tiago a pris une photo de 4 000 × 3 000 pixels, en RVB 24 bits. L'imprimeur demande un fichier imprimé à **300 ppp** (pixels par pouce) pour une bonne qualité.\n\n1. Calcule la définition de l'image en millions de pixels et sa taille non compressée en Mo.\n2. Avec quelles dimensions, en cm, la photo peut-elle être imprimée à 300 ppp ?\n3. Le comité veut une affiche de 60 cm de large. Quelle résolution d'impression, en ppp, obtiendrait-on avec cette photo ? Est-ce conforme à la demande de l'imprimeur ?\n4. Tiago envoie le fichier non compressé depuis son téléphone, avec un débit de 20 Mbit·s⁻¹. Calcule la durée de l'envoi.\n5. Il hésite entre l'envoyer en niveaux de gris (8 bits) ou en JPEG compressé 10 fois. Calcule la taille dans chaque cas et conseille-le, en tenant compte de l'exposition.","bareme":[{"critere":"12 millions de pixels ; 36 × 10⁶ octets = 36 Mo","points":3},{"critere":"13,3 pouces ≈ 33,9 cm par 10 pouces = 25,4 cm","points":5},{"critere":"60 cm ≈ 23,6 pouces ; 4 000 / 23,6 ≈ 169 ppp, inférieur à 300 : non conforme","points":4},{"critere":"36 Mo = 2,88 × 10⁸ bits ; durée 14,4 s","points":4},{"critere":"Gris 12 Mo, JPEG 3,6 Mo ; conseil argumenté (garder la couleur, compresser)","points":4}],"dureeMin":18,"corrige":"1. Définition : 4 000 × 3 000 = **12 × 10⁶ pixels** (12 millions). Taille : 12 × 10⁶ × 3 = **36 × 10⁶ octets = 36 Mo**.\n\n2. Largeur : 4 000 / 300 ≈ 13,3 pouces, soit 13,3 × 2,54 ≈ **33,9 cm**. Hauteur : 3 000 / 300 = 10 pouces, soit **25,4 cm**. La photo s'imprime en environ **34 cm × 25 cm**.\n\n3. 60 cm / 2,54 ≈ 23,6 pouces. Résolution : 4 000 / 23,6 ≈ **169 ppp**. C'est **inférieur aux 300 ppp** demandés : l'affiche serait moins fine que la qualité exigée. Pour 60 cm à 300 ppp, il faudrait environ 23,6 × 300 ≈ 7 090 pixels de large.\n\n4. 36 × 10⁶ octets × 8 = 2,88 × 10⁸ bits. Durée = 2,88 × 10⁸ / 2,0 × 10⁷ = **14,4 s**.\n\n5. Niveaux de gris : 1 octet par pixel, soit **12 Mo** (trois fois moins). JPEG compressé 10 fois : 36 / 10 = **3,6 Mo** (envoi en 3,6 × 10⁶ × 8 / 2,0 × 10⁷ = 1,44 s). Conseil : pour une exposition photo, perdre toutes les couleurs change l'œuvre ; mieux vaut garder la couleur et **compresser** (fichier le plus léger), en gardant une compression modérée pour limiter la perte de qualité, ou envoyer l'original non compressé si la durée de 14 s n'est pas un problème. Toute réponse argumentée avec les tailles justes est acceptée."}$exo$::jsonb),
  ('79f5875d-aa17-57cc-9c27-55c73466125f'::uuid, 1, 'application', $exo${"titre":"Les maillons d'un thermomètre numérique","consigne":"Réponds en justifiant. Détaille les calculs.","enonce":"**Situation.** Un thermomètre numérique de laboratoire est construit avec une thermistance CTN, un pont diviseur de tension, un convertisseur analogique-numérique (CAN) et un afficheur.\n\n1. Donne l'ordre des maillons de la chaîne de mesure et le rôle de chacun.\n2. Comment varie la résistance d'une thermistance CTN quand la température augmente ?\n3. Le CAN est un CAN de 8 bits, de plage 0 – 5 V. Combien de niveaux distingue-t-il ? Calcule son quantum.\n4. Même question pour un CAN de 10 bits sur la même plage. Lequel est le plus fin ?\n5. Définis la sensibilité d'un capteur.","bareme":[{"critere":"Grandeur → capteur → conditionneur → CAN → affichage, rôles justes","points":6},{"critere":"CTN : résistance qui diminue quand T augmente","points":2},{"critere":"8 bits : 256 niveaux, q ≈ 19,5 mV","points":4},{"critere":"10 bits : 1 024 niveaux, q ≈ 4,9 mV, plus fin","points":4},{"critere":"Sensibilité : variation de la sortie pour une variation unité de l'entrée","points":4}],"dureeMin":8,"corrige":"1. Grandeur physique (température) → **capteur** (thermistance : convertit la température en grandeur électrique, sa résistance) → **conditionneur** (pont diviseur : transforme ce signal en **tension** exploitable) → **CAN** (convertit la tension analogique en **nombre binaire**) → **traitement et affichage**.\n\n2. La résistance d'une thermistance **CTN diminue** quand la température augmente.\n\n3. 2⁸ = **256 niveaux**. q = plage / 2ⁿ = 5 / 256 ≈ 0,0195 V = **19,5 mV**.\n\n4. 2¹⁰ = **1 024 niveaux** ; q = 5 / 1 024 ≈ **4,9 mV**. Le CAN de 10 bits a un quantum plus petit : il distingue des écarts de tension plus faibles, il est **plus fin**.\n\n5. La **sensibilité** d'un capteur est la **variation de sa sortie pour une variation unité de l'entrée** (par exemple 10 mV·°C⁻¹) : c'est le coefficient k de la caractéristique de transfert."}$exo$::jsonb),
  ('79f5875d-aa17-57cc-9c27-55c73466125f'::uuid, 2, 'application', $exo${"titre":"Lire la température sur une carte d'acquisition","consigne":"Détaille chaque conversion avec son unité.","enonce":"**Situation.** Un capteur de température délivre une tension U proportionnelle à la température : U = k × T, avec k = 10 mV·°C⁻¹ (T en °C). Il est relié au CAN d'un microcontrôleur, de **10 bits** et de plage **0 – 5 V**. Le programme lit un nombre N et calcule U = N × q.\n\n1. Calcule le quantum q du CAN.\n2. Le programme lit N = 51. Calcule la tension U, puis la température T.\n3. Quelle est la plus petite variation de température que cette chaîne peut distinguer ?\n4. Le cahier des charges impose de distinguer 0,2 °C. La chaîne convient-elle ? On remplace le CAN par un CAN de 12 bits sur 0 – 5 V : la chaîne convient-elle alors ? Justifie par un calcul.","bareme":[{"critere":"q = 5 / 1 024 ≈ 4,88 mV","points":4},{"critere":"U = 51 × 4,88 ≈ 249 mV et T ≈ 24,9 °C","points":6},{"critere":"Résolution ≈ 4,88 / 10 ≈ 0,49 °C, fixée par le maillon le plus grossier","points":4},{"critere":"10 bits insuffisant ; 12 bits : q ≈ 1,22 mV soit ≈ 0,12 °C, conforme","points":6}],"dureeMin":11,"corrige":"1. q = plage / 2ⁿ = 5 / 2¹⁰ = 5 / 1 024 ≈ 4,88 × 10⁻³ V = **4,88 mV**.\n\n2. U = N × q = 51 × 4,88 mV ≈ **249 mV** = 0,249 V. T = U / k = 249 mV / 10 mV·°C⁻¹ ≈ **24,9 °C**.\n\n3. Le CAN ne distingue pas des tensions plus proches que q = 4,88 mV. Avec 10 mV par °C, cela correspond à 4,88 / 10 ≈ **0,49 °C** : la chaîne ne distingue qu'environ un demi-degré. La résolution de la chaîne est fixée par son **maillon le plus grossier**, ici le CAN.\n\n4. 0,49 °C > 0,2 °C : la chaîne **ne convient pas**.\nAvec un CAN de 12 bits : q = 5 / 4 096 ≈ **1,22 mV**, soit 1,22 / 10 ≈ **0,12 °C**. 0,12 °C < 0,2 °C : la chaîne **convient** (si le capteur lui-même est assez fin)."}$exo$::jsonb),
  ('79f5875d-aa17-57cc-9c27-55c73466125f'::uuid, 3, 'application', $exo${"titre":"Étalonner un thermomètre à thermistance","consigne":"Exploite l'étalonnage, puis évalue la chaîne de mesure au regard du cahier des charges. Justifie chaque conclusion.","enonce":"**Situation.** Des élèves construisent un thermomètre pour un bain-marie : thermistance CTN, pont diviseur alimenté en 5 V, CAN de 10 bits (0 – 5 V) d'un microcontrôleur.\n\n**Cahier des charges** : mesurer entre 20 °C et 80 °C ; distinguer des variations de 0,5 °C.\n\n**Étalonnage** : on plonge la thermistance dans de l'eau à différentes températures, mesurées par un thermomètre de référence (tolérance ± 0,5 °C). Sur cette plage, la tension de sortie du pont est :\n\n| T (°C) | 20 | 40 | 60 | 80 |\n|---|---|---|---|---|\n| U (V) | 1,20 | 1,60 | 2,00 | 2,40 |\n\n1. Pourquoi s'agit-il d'une mesure par étalonnage ? Quel est le rôle du pont diviseur ?\n2. Montre que la caractéristique de transfert est une droite U = k × T + U₀ et détermine k et U₀. Que représente k ?\n3. Le microcontrôleur mesure U = 1,85 V. Calcule la température du bain.\n4. Calcule le quantum du CAN et la plus petite variation de température détectable. Le cahier des charges est-il respecté ?\n5. Calcule l'incertitude-type apportée par le thermomètre de référence. Pourquoi limite-t-elle l'exactitude du thermomètre fabriqué ?","bareme":[{"critere":"Mesure d'une tension liée à T, relation établie par étalons ; pont = conditionneur (résistance → tension)","points":3},{"critere":"k = 0,020 V·°C⁻¹ (20 mV·°C⁻¹), U₀ = 0,80 V ; k = sensibilité","points":5},{"critere":"T = (1,85 − 0,80) / 0,020 = 52,5 °C","points":4},{"critere":"q ≈ 4,88 mV, soit ≈ 0,24 °C ≤ 0,5 °C : conforme ; étendue 20-80 °C couverte","points":5},{"critere":"u = 0,5/√3 ≈ 0,29 °C ; l'étalonnage hérite de l'incertitude de la référence","points":3}],"dureeMin":20,"corrige":"1. On ne lit pas directement la température : on mesure une **tension** qui dépend de la température, et la relation entre les deux est établie à l'aide d'**étalons** (eau à des températures connues). C'est une **mesure par étalonnage**. Le pont diviseur est le **conditionneur** : il transforme la variation de **résistance** de la thermistance en **tension** exploitable par le CAN.\n\n2. Entre deux points successifs, ΔU = 0,40 V pour ΔT = 20 °C : la pente est constante, les points sont **alignés** : c'est une droite. k = 0,40 / 20 = **0,020 V·°C⁻¹ = 20 mV·°C⁻¹**. U₀ = U − k × T = 1,20 − 0,020 × 20 = **0,80 V** (vérification : 0,80 + 0,020 × 80 = 2,40 V). k est la **sensibilité** de la chaîne capteur + conditionneur.\n\n3. T = (U − U₀) / k = (1,85 − 0,80) / 0,020 = 1,05 / 0,020 = **52,5 °C**.\n\n4. q = 5 / 1 024 ≈ **4,88 mV**. Plus petite variation détectable : 4,88 / 20 ≈ **0,24 °C**. 0,24 °C < 0,5 °C et la plage 20-80 °C est couverte par l'étalonnage : le cahier des charges est **respecté** sur ces deux points.\n\n5. Tolérance ± 0,5 °C, mesure unique : u = Δ / √3 = 0,5 / 1,732 ≈ **0,29 °C**. Toute la caractéristique de transfert a été construite à partir des indications de ce thermomètre : l'incertitude de la référence se **reporte** sur le thermomètre fabriqué. Même si le CAN distingue 0,24 °C, la température affichée n'est pas plus exacte que la référence utilisée pour l'étalonner (à laquelle s'ajoute l'incertitude de numérisation, de l'ordre du quantum)."}$exo$::jsonb),
  ('30588c6b-33e2-5fbc-8e20-0c35a0e2f713'::uuid, 1, 'application', $exo${"titre":"L'alarme du congélateur","consigne":"Lis le programme et réponds aux questions.","enonce":"**Situation.** Une alarme de congélateur fonctionne avec un capteur de température relié à un microcontrôleur. Voici son programme :\n\n| Ligne | Code |\n|---|---|\n| 1 | lire la tension du capteur sur la broche A0 |\n| 2 | convertir en température |\n| 3 | si température > −12 alors allumer l'alarme |\n| 4 | sinon éteindre l'alarme |\n| 5 | attendre 10 s, puis recommencer |\n\n1. Pourquoi parle-t-on de mesure « en tout ou rien » ? Combien d'états la sortie peut-elle prendre ?\n2. Que se passe-t-il si la température mesurée vaut −15 °C ? −10 °C ?\n3. On veut que l'alarme se déclenche au-dessus de −15 °C, et que la mesure soit faite toutes les 5 s. Réécris les lignes à modifier.\n4. Donne un autre exemple de dispositif d'alerte en tout ou rien.","bareme":[{"critere":"Tout ou rien : dépassement d'un seuil, deux états seulement","points":5},{"critere":"−15 °C : alarme éteinte ; −10 °C : alarme allumée","points":5},{"critere":"Lignes 3 et 5 correctement réécrites (seuil −15, attente 5 s)","points":7},{"critere":"Exemple pertinent de dispositif d'alerte","points":3}],"dureeMin":7,"corrige":"1. On ne cherche pas la valeur précise de la température, seulement à savoir si elle **dépasse un seuil**. La sortie ne prend que **deux états** : alarme allumée ou éteinte (1 ou 0, vrai ou faux).\n\n2. −15 °C n'est pas supérieur à −12 °C : la condition de la ligne 3 est fausse, la ligne 4 s'exécute, l'**alarme est éteinte**. −10 °C > −12 °C : la condition est vraie, l'**alarme s'allume**.\n\n3. Ligne 3 : « si température > −15 alors allumer l'alarme ». Ligne 5 : « attendre 5 s, puis recommencer ». Les autres lignes restent identiques.\n\n4. Exemples : détecteur de niveau d'eau, capteur de CO₂ dans une salle qui signale un air trop chargé, alarme de température d'un aquarium…"}$exo$::jsonb),
  ('30588c6b-33e2-5fbc-8e20-0c35a0e2f713'::uuid, 2, 'application', $exo${"titre":"L'enregistrement de l'incubateur","consigne":"Exploite l'enregistrement. Justifie chaque réponse par une valeur lue ou calculée.","enonce":"**Situation.** Un incubateur doit maintenir des cultures à 37 °C. Sa régulation tout ou rien allume le chauffage sous 36,5 °C et l'éteint au-dessus de 37,5 °C.\n\n**Enregistrement.** Après la montée initiale, la température passe par des maximums de 37,8 °C aux instants t = 12 min, 30 min et 48 min, et par des minimums de 36,3 °C aux instants t = 21 min et 39 min.\n\n1. Quelle est la consigne ? Quelle est l'hystérésis (écart entre les deux seuils) ?\n2. Calcule la période des oscillations.\n3. Calcule l'écart entre la température maximale et la température minimale. Pourquoi est-il plus grand que l'écart entre les seuils ?\n4. Décris ce que fait le chauffage entre t = 12 min et t = 21 min, puis juste après t = 21 min.\n5. Pourquoi n'a-t-on pas réglé les deux seuils à 37,0 °C ?","bareme":[{"critere":"Consigne 37 °C, hystérésis 1,0 °C","points":3},{"critere":"Période 18 min","points":4},{"critere":"Écart 1,5 °C, supérieur à 1,0 °C à cause de l'inertie (dépassements 0,3 et 0,2 °C)","points":6},{"critere":"Chauffage éteint pendant la baisse, rallumé quand T passe sous 36,5 °C","points":4},{"critere":"Seuils identiques : commutations incessantes, usure du relais","points":3}],"dureeMin":11,"corrige":"1. Consigne : **37 °C**. Hystérésis : 37,5 − 36,5 = **1,0 °C**.\n\n2. La période est la durée entre deux maximums successifs : 30 − 12 = 48 − 30 = **18 min** (on vérifie avec les minimums : 39 − 21 = 18 min).\n\n3. Écart : 37,8 − 36,3 = **1,5 °C**, plus grand que 1,0 °C. À cause de l'**inertie** du système : après l'arrêt de la résistance, elle restitue encore de la chaleur et la température dépasse 37,5 °C de 0,3 °C ; après le rallumage, il faut du temps pour que la chaleur arrive, et la température descend encore de 0,2 °C sous 36,5 °C.\n\n4. Juste avant t = 12 min, la température a dépassé 37,5 °C : le chauffage s'est **éteint**. Entre 12 et 21 min, il reste **éteint** et la température baisse. Elle passe sous 36,5 °C juste avant t = 21 min : le chauffage s'**allume** ; la température finit de descendre jusqu'à 36,3 °C puis remonte.\n\n5. Avec deux seuils identiques, le chauffage basculerait **sans cesse** autour de la consigne : des commutations incessantes qui **usent le relais**. Deux seuils donnent des oscillations un peu plus larges mais beaucoup moins de commutations."}$exo$::jsonb),
  ('30588c6b-33e2-5fbc-8e20-0c35a0e2f713'::uuid, 3, 'application', $exo${"titre":"Régler la couveuse du lycée","consigne":"Compare les réglages au cahier des charges, propose une solution et écris le programme correspondant.","enonce":"**Situation.** La section agricole du lycée veut faire éclore des œufs dans une couveuse régulée en tout ou rien.\n\n**Cahier des charges** : la température doit rester **entre 36,0 °C et 38,0 °C** ; le relais du chauffage ne doit pas commuter **plus de 20 fois par heure**.\n\nDeux réglages ont été essayés pendant une heure :\n\n| Réglage | Seuil d'allumage | Seuil d'extinction | Température mesurée | Commutations par heure |\n|---|---|---|---|---|\n| A | 36,9 °C | 37,1 °C | de 36,8 à 37,3 °C | 40 |\n| B | 36,0 °C | 38,0 °C | de 35,8 à 38,3 °C | 6 |\n\n1. Calcule l'hystérésis de chaque réglage.\n2. Vérifie chacun des deux critères du cahier des charges pour les réglages A et B. Conclus.\n3. Explique le lien entre l'hystérésis, l'amplitude des oscillations et le nombre de commutations, à l'aide des deux essais.\n4. Pourquoi la température du réglage B sort-elle de l'intervalle fixé par ses seuils ?\n5. Propose un réglage C, justifie-le, et écris en langage naturel le programme de régulation (lecture du capteur, conversion, comparaisons aux deux seuils, attente).","bareme":[{"critere":"Hystérésis : A = 0,2 °C, B = 2,0 °C","points":2},{"critere":"A : température conforme mais 40 > 20 commutations ; B : commutations conformes mais sort de 36-38 °C","points":6},{"critere":"Petite hystérésis : faible amplitude et commutations fréquentes ; grande : l'inverse","points":4},{"critere":"Dépassements dus à l'inertie du système","points":3},{"critere":"Réglage C intermédiaire justifié et programme à deux seuils correct","points":5}],"dureeMin":20,"corrige":"1. A : 37,1 − 36,9 = **0,2 °C**. B : 38,0 − 36,0 = **2,0 °C**.\n\n2. **Réglage A** : la température reste entre 36,8 et 37,3 °C, donc dans 36,0-38,0 °C : **conforme** ; mais 40 commutations par heure > 20 : **non conforme** (usure du relais). **Réglage B** : 6 commutations par heure ≤ 20 : **conforme** ; mais la température descend à 35,8 °C et monte à 38,3 °C : elle **sort** de l'intervalle : **non conforme**. Aucun des deux réglages ne respecte tout le cahier des charges.\n\n3. Une **faible hystérésis** (A) donne des oscillations de **faible amplitude** mais des commutations **très fréquentes** ; une **grande hystérésis** (B) donne des oscillations **larges** mais des commutations **rares**.\n\n4. Le système a de l'**inertie** : après l'extinction, la résistance restitue encore de la chaleur et la température dépasse 38,0 °C ; après l'allumage, la chaleur met du temps à arriver et la température descend encore sous 36,0 °C.\n\n5. Il faut un réglage **intermédiaire**, avec des seuils placés à l'intérieur de 36,0-38,0 °C en gardant une marge pour les dépassements dus à l'inertie (environ 0,3 °C d'après B), par exemple **allumage sous 36,5 °C, extinction au-dessus de 37,5 °C** (hystérésis 1,0 °C) : les oscillations devraient rester entre environ 36,2 et 37,8 °C, avec bien moins de commutations que A. Il faudra le vérifier par un enregistrement.\nProgramme :\n1. lire la tension du capteur ;\n2. convertir en température ;\n3. si température < 36,5 alors allumer le chauffage ;\n4. si température > 37,5 alors éteindre le chauffage ;\n5. (entre les deux seuils, ne rien changer) ;\n6. attendre quelques secondes, puis recommencer."}$exo$::jsonb),
  ('6912a692-5037-5348-9dcd-38bb57202202'::uuid, 1, 'application', $exo${"titre":"Les étapes d'un projet","consigne":"Réponds en phrases courtes et justifie tes choix.","enonce":"**Situation.** Une équipe de 1re STL prépare un mini-projet. Leur fiche de travail mélange les phases :\n\n- a) rédiger une note concise et présenter à l'oral ;\n- b) mesurer en suivant le protocole et noter dans le cahier de laboratoire ;\n- c) chercher des informations et énoncer une problématique ;\n- d) estimer les incertitudes et confronter les résultats aux objectifs ;\n- e) formuler des hypothèses, choisir un protocole et planifier.\n\n1. Remets les phases dans l'ordre et nomme chacune (s'approprier, analyser, réaliser, valider, communiquer).\n2. L'équipe a pour sujet « L'eau du robinet ». Est-ce une problématique ? Justifie et propose une formulation précise et mesurable.\n3. Donne deux règles de tenue du cahier de laboratoire.","bareme":[{"critere":"Ordre c, e, b, d, a avec les cinq noms de phases","points":8},{"critere":"« L'eau du robinet » est un thème ; problématique précise et mesurable proposée","points":7},{"critere":"Deux règles justes du cahier de laboratoire","points":5}],"dureeMin":7,"corrige":"1. c) **S'approprier** : rechercher des informations, énoncer une problématique.\ne) **Analyser** : hypothèses, protocole, planification.\nb) **Réaliser** : mettre en œuvre le protocole en sécurité, mesurer, tout noter.\nd) **Valider** : analyser avec esprit critique, estimer les incertitudes, confronter aux objectifs.\na) **Communiquer** : note concise, présentation orale, réponses aux questions.\n\n2. « L'eau du robinet » est un **thème**, pas une problématique : ce n'est pas une question, rien n'y est mesurable. Une problématique est une question **précise et mesurable**, par exemple : « La conductivité de l'eau du robinet du lycée varie-t-elle de plus de 10 % entre le matin et le soir ? » (toute question précise, qui porte sur une grandeur mesurable avec un critère, est acceptée).\n\n3. Deux règles parmi : les pages sont **datées** ; on y note les protocoles, les réglages, les incidents et les idées ; les **mesures brutes** sont notées **au moment où on les fait**, jamais recopiées au propre après coup ; on ne supprime pas les mesures gênantes. C'est la mémoire du projet et la preuve de ce qui a été fait."}$exo$::jsonb),
  ('6912a692-5037-5348-9dcd-38bb57202202'::uuid, 2, 'application', $exo${"titre":"Lancer le projet « jus d'orange »","consigne":"Rédige les éléments demandés comme si tu préparais le projet de ton équipe.","enonce":"**Situation.** Trois élèves, Yanis, Clara et Mehdi, veulent vérifier si un jus d'orange du commerce contient autant de vitamine C que l'annonce l'étiquette. Ils disposent de trois séances de deux heures, du matériel habituel du laboratoire du lycée et d'un budget de 20 €. Clara est à l'aise avec les calculs, Mehdi avec les manipulations, Yanis avec la présentation orale.\n\n1. Formule une problématique précise et mesurable.\n2. Formule une hypothèse. À quelle condition une hypothèse est-elle acceptable ?\n3. Rédige le cahier des charges du projet : grandeur à mesurer, exactitude attendue, contraintes.\n4. Propose une planification sur les trois séances et une répartition des rôles, en respectant les règles du travail en équipe.","bareme":[{"critere":"Problématique sous forme de question précise, avec une grandeur et un critère chiffré","points":5},{"critere":"Hypothèse testable par une expérience","points":4},{"critere":"Cahier des charges : grandeur, exactitude, contraintes (temps, matériel, coût, sécurité)","points":6},{"critere":"Planification cohérente sur trois séances, rôles répartis sans exclure personne, points d'étape","points":5}],"dureeMin":12,"corrige":"1. Exemple : « La concentration en vitamine C du jus d'orange X est-elle égale, à 10 % près, à la valeur annoncée sur l'étiquette ? » La question porte sur une **grandeur mesurable** (concentration en vitamine C) et fixe un **critère** (10 %).\n\n2. Exemple : « Le jus contient moins de vitamine C qu'annoncé, car elle se dégrade après l'ouverture de la bouteille. » Une hypothèse doit être **testable par une expérience** (ici : doser un jus fraîchement ouvert et un jus ouvert depuis plusieurs jours).\n\n3. Cahier des charges :\n- **grandeur à mesurer** : concentration en vitamine C du jus (en mg·L⁻¹ par exemple) ;\n- **exactitude attendue** : incertitude suffisante pour conclure à 10 % près ;\n- **contraintes** : trois séances de deux heures, matériel du laboratoire du lycée, budget de 20 €, règles de sécurité, gestion des déchets.\nChaque choix du projet devra se justifier par rapport à ce cahier des charges.\n\n4. Exemple de planification :\n- **séance 1** : recherche d'informations, choix et essai du protocole, liste du matériel ;\n- **séance 2** : mesures répétées, notées brutes dans le cahier de laboratoire ;\n- **séance 3** : calculs, incertitudes, confrontation à l'étiquette, préparation de la note et de l'oral.\nRôles selon les compétences : Mehdi responsable des manipulations, Clara des calculs et des incertitudes, Yanis de la présentation ; **chacun participe à toutes les étapes**, personne n'est laissé de côté ; un **point d'étape** à la fin de chaque séance et un document partagé pour garder la trace."}$exo$::jsonb),
  ('6912a692-5037-5348-9dcd-38bb57202202'::uuid, 3, 'application', $exo${"titre":"Critiquer la fin d'un projet","consigne":"Analyse la démarche de l'équipe avec esprit critique. Chaque critique doit être justifiée et accompagnée d'une amélioration.","enonce":"**Situation.** Une équipe a mené le projet suivant.\n\n**Problématique** : « Un colorimètre fabriqué avec une LED et un microcontrôleur permet-il de doser le colorant bleu d'un sirop avec un écart inférieur à 5 % par rapport au spectrophotomètre du laboratoire ? »\n\n**Extraits du compte rendu**\n\n> « Nous avons fait six mesures avec notre colorimètre. La cinquième nous semblait bizarre, nous l'avons supprimée. Nous avons recopié les mesures au propre dans le cahier à la fin du projet. »\n> « Résultats : colorimètre, c = 2,45 × 10⁻⁵ mol·L⁻¹ ; spectrophotomètre, c = 2,60 × 10⁻⁵ mol·L⁻¹. »\n> « Conclusion : notre colorimètre fonctionne parfaitement. »\n\n**Présentation orale** : cinq diapositives couvertes de texte, lues par un seul élève ; le graphique n'a pas d'unités ; la présentation se termine par « voilà ».\n\n1. Calcule l'écart relatif entre les deux résultats. Le cahier des charges est-il respecté ? La conclusion de l'équipe est-elle acceptable ?\n2. Relève deux erreurs dans la tenue des mesures et du cahier de laboratoire. Explique pourquoi ce sont des erreurs.\n3. Relève trois défauts de la présentation orale et propose pour chacun une amélioration.\n4. Rédige une conclusion honnête et utile pour la note concise, qui répond à la problématique et propose une piste d'amélioration.","bareme":[{"critere":"Écart = 0,15 / 2,60 ≈ 5,8 % > 5 % : cahier des charges non respecté, conclusion à rejeter","points":5},{"critere":"Deux erreurs justifiées : mesure supprimée sans raison, mesures recopiées au propre après coup","points":4},{"critere":"Trois défauts de l'oral et trois améliorations pertinentes","points":6},{"critere":"Conclusion qui répond à la question, admet le résultat décevant et propose une amélioration","points":5}],"dureeMin":18,"corrige":"1. Écart relatif : |2,45 − 2,60| / 2,60 = 0,15 / 2,60 ≈ **0,058, soit 5,8 %**. C'est **supérieur à 5 %** : le cahier des charges **n'est pas respecté**. La conclusion « fonctionne parfaitement » est **inacceptable** : elle ne répond pas à la question posée et cache un résultat décevant. (On pourrait aussi estimer les incertitudes des deux mesures pour juger si l'écart est significatif.)\n\n2. **Mesure supprimée** parce qu'elle « semblait bizarre » : valider, c'est analyser les résultats avec esprit critique, pas supprimer les mesures gênantes ; il fallait la garder, la signaler et chercher une cause (incident noté ou non). **Mesures recopiées au propre à la fin** : les mesures brutes doivent être notées **au moment où on les fait** ; recopier après coup fait perdre la trace fidèle de ce qui a été fait, et le cahier n'est plus une preuve.\n\n3. Défauts et améliorations :\n- **diapositives surchargées de texte** → peu de texte, des mots-clés, des schémas ;\n- **lecture des notes par un seul élève** → parler sans lire, répartir la parole entre tous les membres ;\n- **graphique sans unités** → graphique lisible, avec grandeurs, unités et incertitudes ;\n- **fin sur « voilà »** → conclure en répondant à la problématique ;\n- (accepté aussi : problématique à annoncer dès le début, résultat décevant à montrer et expliquer).\n\n4. Exemple : « Notre colorimètre donne 2,45 × 10⁻⁵ mol·L⁻¹ contre 2,60 × 10⁻⁵ mol·L⁻¹ au spectrophotomètre, soit un écart de 5,8 %. Il ne permet donc pas, dans sa version actuelle, de doser le colorant avec un écart inférieur à 5 %. L'écart pourrait venir de la LED, dont la couleur ne correspond peut-être pas au maximum d'absorption du colorant, ou d'un étalonnage fait avec trop peu d'étalons. Nous proposons de choisir une LED adaptée, de refaire l'étalonnage avec plus d'étalons et de répéter les mesures pour estimer l'incertitude. »"}$exo$::jsonb),
  ('a59242bd-b077-591e-b2c5-3fe816eff8cd'::uuid, 1, 'redaction', $exo${"titre":"Les réglages de la charge d'entraînement","consigne":"Réponds à chaque question par quelques phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Cite les **quatre paramètres** de la charge d'entraînement et dis comment chacun se mesure.\n2. Explique les trois temps de la **surcompensation**.\n3. Énonce le principe de **progressivité** (avec son chiffre) et celui de **spécificité**.","bareme":[{"critere":"Volume, intensité, densité, fréquence avec leur mesure","points":8},{"critere":"Effort, récupération, surcompensation expliqués dans l'ordre","points":7},{"critere":"Progressivité par paliers de 5 à 10 % par semaine et spécificité","points":5}],"dureeMin":7,"corrige":"1. Le **volume** (quantité de travail : durée, distance, nombre de répétitions) ; l'**intensité** (difficulté : pourcentage de VMA ou de charge maximale) ; la **densité** (rapport effort / repos : temps de récupération entre les séries) ; la **fréquence** (nombre de séances par semaine).\n2. **L'effort** fatigue : le niveau descend sous le niveau de départ. **La récupération** répare : le niveau remonte. **La surcompensation** dépasse : l'organisme reconstruit un peu au-dessus du niveau initial, par anticipation. La séance suivante doit tomber à ce moment.\n3. **Progressivité** : augmenter la charge par paliers de **5 à 10 % par semaine**, pas davantage. **Spécificité** : on progresse dans ce que l'on travaille (un nageur ne gagne pas en natation ce qu'il gagne en course à pied)."}$exo$::jsonb),
  ('a59242bd-b077-591e-b2c5-3fe816eff8cd'::uuid, 2, 'redaction', $exo${"titre":"Le programme de course de Maëlle","consigne":"Lis la situation, puis réponds en justifiant chaque réponse avec les principes du cours. Détaille les calculs.","enonce":"**Situation.** Maëlle, en seconde, prépare un 5 km. Elle court actuellement **3 fois par semaine**, **20 km** au total par semaine, avec des fractionnés à 90 % de sa VMA et 1 min 30 de récupération entre les séries.\n\nLa semaine prochaine, elle veut passer à **5 séances**, **30 km** au total, et réduire la récupération à **45 secondes**.\n\n1. Identifie les paramètres de la charge qu'elle veut modifier.\n2. Calcule l'augmentation de son volume hebdomadaire en pourcentage. Respecte-t-elle le principe de progressivité ?\n3. Explique pourquoi modifier plusieurs paramètres en même temps est une erreur.\n4. Propose-lui un plan corrigé pour la semaine prochaine, et justifie.","bareme":[{"critere":"Fréquence, volume et densité identifiés","points":4},{"critere":"Calcul juste (+50 %) et non-respect de la progressivité justifié","points":6},{"critere":"Un seul paramètre à la fois : effet illisible sinon, progrès ou blessure","points":4},{"critere":"Plan corrigé réaliste (un paramètre, +5 à 10 %) et justifié","points":6}],"dureeMin":10,"corrige":"1. Elle modifie la **fréquence** (3 → 5 séances), le **volume** (20 → 30 km) et la **densité** (récupération de 1 min 30 à 45 s). Seule l'intensité (90 % de VMA) reste identique.\n2. Augmentation : (30 − 20) ÷ 20 × 100 = **+50 %**. Le principe de **progressivité** impose des paliers de **5 à 10 % par semaine** : 50 %, c'est cinq fois trop. Elle risque la blessure et le surentraînement.\n3. Il ne faut modifier **qu'un seul paramètre à la fois** : avec deux ou trois changements simultanés, l'effet devient **illisible** — on ne sait plus lequel a produit le progrès, ni lequel a produit la blessure.\n4. Exemple : garder 3 séances et la même récupération, et passer à **21 ou 22 km** (+5 à +10 %) ; changer la fréquence ou la densité plus tard, un paramètre à la fois. Elle laisse ainsi le temps à la **récupération**, qui fait progresser."}$exo$::jsonb),
  ('a59242bd-b077-591e-b2c5-3fe816eff8cd'::uuid, 3, 'redaction', $exo${"titre":"Nathan s'entraîne plus et progresse moins","consigne":"Analyse le document, puis rédige une réponse argumentée qui relie les signes observés aux mécanismes du cours.","enonce":"**Document : carnet d'entraînement de Nathan, 16 ans, joueur de handball.**\n\n| Semaine | Séances | Fréquence cardiaque au repos | Sommeil | Test de sprint (30 m) |\n|---|---|---|---|---|\n| 1 | 3 | 58 battements/min | Bon | 4,60 s |\n| 2 | 4 | 58 | Bon | 4,55 s |\n| 3 | 6 | 63 | Réveils la nuit | 4,62 s |\n| 4 | 7 | 66 | Endormissement long | 4,75 s |\n\nNathan note aussi : « Je suis fatigué dès le matin et j'ai moins envie d'aller à l'entraînement. Je vais rajouter une séance pour rattraper mon retard. »\n\n1. Décris l'évolution de la charge et de la performance de Nathan entre les semaines 1 et 4.\n2. Relève dans le document **quatre** signes du surentraînement. Pourquoi ces signes sont-ils difficiles à repérer à temps ?\n3. À l'aide de la surcompensation, explique pourquoi Nathan progresse entre les semaines 1 et 2 puis régresse ensuite.\n4. Que penses-tu de sa décision de rajouter une séance ? Propose-lui un plan pour les deux semaines suivantes.","bareme":[{"critere":"Évolution de la charge (fréquence x2,3) et de la performance décrite avec les chiffres","points":4},{"critere":"Quatre signes relevés et lus au repos","points":5},{"critere":"Surcompensation mobilisée : séances trop rapprochées, reprise pendant la fatigue","points":6},{"critere":"Décision critiquée et plan centré sur la récupération","points":5}],"dureeMin":20,"corrige":"1. La **fréquence** passe de 3 à 7 séances par semaine (plus du double) en trois semaines. Le sprint s'améliore d'abord (4,60 → 4,55 s), puis se dégrade (4,62 puis **4,75 s**) : la performance **baisse malgré le travail**.\n2. Signes : la **fréquence cardiaque de repos** élevée de plusieurs battements (58 → 66) ; les troubles du **sommeil** (réveils nocturnes, endormissement long) ; la **fatigue** qui persiste dès le matin ; la **performance** qui baisse ; la **perte de motivation**. Ces signes se lisent **au repos, pas à l'effort** : à l'entraînement, Nathan peut encore se sentir capable, ce qui les rend difficiles à repérer à temps.\n3. La surcompensation se déroule en trois temps : l'effort fait baisser le niveau, la récupération le fait remonter, puis il dépasse le niveau de départ. En semaine 2, l'augmentation est modérée et les séances tombent au bon moment : il progresse. Ensuite, les séances sont **trop rapprochées** : il reprend pendant la **phase 1**, encore fatigué, ce qui **épuise sans construire** ; le niveau descend de séance en séance. De plus, passer de 4 à 7 séances ne respecte pas la progressivité (5 à 10 % par semaine).\n4. Rajouter une séance est une erreur : face au surentraînement, la réponse **n'est jamais d'en faire plus**, c'est de **récupérer**. Plan : réduire nettement la charge (revenir à 3 séances, en baissant le volume et l'intensité), dormir davantage, surveiller la fréquence cardiaque de repos ; quand elle revient à 58 et que le sommeil redevient bon, remonter la charge progressivement, **un paramètre à la fois**, par paliers de 5 à 10 %."}$exo$::jsonb),
  ('8a8fd32a-db18-51b5-8151-7ce2f8f54a1a'::uuid, 1, 'redaction', $exo${"titre":"Les trois leviers hors du terrain","consigne":"Réponds à chaque question par quelques phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Donne le rôle des **glucides**, des **protéines** et des **lipides**, avec un aliment pour chacun.\n2. Que faut-il faire 3 h avant l'effort, pendant l'effort, et dans les 2 h qui suivent ?\n3. Combien d'heures de sommeil faut-il à un adolescent ? Que se passe-t-il pendant le sommeil profond ?","bareme":[{"critere":"Rôle et exemple des trois nutriments","points":8},{"critere":"Avant, pendant, après l'effort correctement décrits","points":7},{"critere":"8 à 9 heures, réparation tissulaire et hormone de croissance","points":5}],"dureeMin":7,"corrige":"1. **Glucides** : le **carburant principal** de l'effort (pâtes, riz, pain, fruits). **Protéines** : elles **réparent et construisent le muscle** (viande, poisson, œufs, légumineuses). **Lipides** : une énergie de **longue durée** (huiles, oléagineux, poissons gras).\n2. **3 h avant** : un repas complet et digestible (réserves pleines, digestion finie). **Pendant** : boire régulièrement, par petites quantités, avant d'avoir soif. **Dans les 2 h après** : des glucides et des protéines, la fenêtre où le muscle reconstitue ses réserves et se répare.\n3. **8 à 9 heures**. Pendant le sommeil profond se produisent la **réparation tissulaire** et la sécrétion d'**hormone de croissance** : l'entraînement ne devient du progrès que la nuit."}$exo$::jsonb),
  ('8a8fd32a-db18-51b5-8151-7ce2f8f54a1a'::uuid, 2, 'redaction', $exo${"titre":"La journée de tournoi d'Inès","consigne":"Lis la situation, repère les erreurs et propose des corrections justifiées par le cours.","enonce":"**Situation.** Inès, 15 ans, joue un tournoi de volley qui commence à **14 h**. La veille, elle a regardé des vidéos sur son téléphone jusqu'à 1 h du matin et s'est levée à 7 h. À **13 h 30**, elle mange une grande assiette de frites. Pendant le tournoi, elle ne boit qu'une fois, « quand j'avais vraiment soif ». Entre deux matchs, elle boit une boisson énergisante pour « se réveiller ». Le soir, elle ne dîne pas : « je veux perdre du poids ».\n\n1. Relève **cinq** erreurs dans la journée d'Inès.\n2. Pour chacune, explique la conséquence sur sa performance ou sa récupération.\n3. Propose-lui un programme corrigé pour la veille et le jour du tournoi.","bareme":[{"critere":"Cinq erreurs correctement relevées","points":6},{"critere":"Conséquence expliquée pour chaque erreur, avec les notions du cours","points":8},{"critere":"Programme corrigé complet : sommeil, repas, hydratation, récupération","points":6}],"dureeMin":12,"corrige":"1 et 2. Erreurs et conséquences :\n- **Écrans jusqu'à 1 h, 6 h de sommeil** : les écrans retardent l'endormissement en freinant la **mélatonine** ; il lui manque 2 à 3 h sur les 8 à 9 h nécessaires ; la dette de sommeil se paie en performance et en blessures.\n- **Repas 30 min avant** : il faut manger environ **3 h avant** pour que la digestion soit finie ; un repas gras et lourd (frites) juste avant gêne l'effort.\n- **Boire seulement quand elle a soif** : la soif est déjà un signe de **déshydratation installée** ; dès **−2 %** du poids en eau, la performance chute.\n- **Boisson énergisante** : une fausse solution, qui n'améliore pas durablement la performance ; rien ne remplace la régularité.\n- **Pas de dîner** : elle manque la fenêtre des **2 h après** l'effort (glucides et protéines pour recharger et réparer) ; un régime drastique retire une fonction à l'organisme.\n3. Exemple : la veille, dîner complet et écrans coupés tôt pour dormir **8 à 9 h** ; le jour J, repas complet et digestible (féculents, protéines, légumes) vers **11 h** ; boire régulièrement par petites gorgées avant, pendant et entre les matchs ; eau plutôt que boisson énergisante ; dans les 2 h après le tournoi, un repas avec **glucides et protéines**."}$exo$::jsonb),
  ('8a8fd32a-db18-51b5-8151-7ce2f8f54a1a'::uuid, 3, 'redaction', $exo${"titre":"Le complément miracle","consigne":"Analyse le document, puis rédige une réponse argumentée en plusieurs paragraphes, appuyée sur les connaissances du cours.","enonce":"**Document : publicité vue sur un réseau social.**\n\n> **MUSCLE MAX** — Le secret des champions ! Supprime les glucides, remplace tes repas par nos gélules protéinées et gagne en puissance en 7 jours. Plus besoin de dormir 9 heures : nos gélules récupèrent pour toi ! Idéal avant chaque match.\n\n**Données.** Hugo, 16 ans, pèse **60 kg**. Pendant un match de football par temps chaud, il perd environ **1,5 L** d'eau (on considère que 1 L d'eau pèse 1 kg).\n\n1. Relève **trois** affirmations de la publicité et montre, pour chacune, pourquoi elle est fausse ou dangereuse.\n2. Calcule la perte de poids en eau de Hugo en pourcentage. Que peux-tu en conclure pour sa performance, et que doit-il faire ?\n3. Explique pourquoi le sommeil ne peut être remplacé par aucun produit.\n4. Rédige un conseil à Hugo (8 à 10 lignes) sur ce qui fait vraiment progresser un sportif en dehors du terrain.","bareme":[{"critere":"Trois affirmations réfutées avec le rôle des nutriments et du sommeil","points":6},{"critere":"Calcul de 2,5 % et conclusion sur la chute de performance et l'hydratation","points":4},{"critere":"Sommeil : réparation tissulaire, hormone de croissance, 8 à 9 h","points":4},{"critere":"Conseil argumenté et organisé : assiette, timing, sommeil, refus des fausses solutions et du dopage","points":6}],"dureeMin":20,"corrige":"1. « **Supprime les glucides** » : ce sont le **carburant principal de l'effort** ; un régime qui retire une famille entière retire aussi une fonction. « **Remplace tes repas par des gélules protéinées** » : les protéines réparent et construisent le muscle, mais ne fournissent pas l'énergie de l'effort, et aucun des trois nutriments n'est à supprimer. « **Plus besoin de dormir** » : c'est pendant le sommeil profond que le corps se répare ; aucun produit ne le remplace. On peut aussi relever « en 7 jours » : les **compléments miracles** promettent de remplacer la régularité, que rien ne remplace.\n2. 1,5 kg ÷ 60 kg × 100 = **2,5 %**. Dès **2 %** du poids en eau, la performance chute déjà : Hugo perd en efficacité en fin de match. Il doit **boire avant d'avoir soif**, régulièrement, par petites quantités, avant et pendant le match.\n3. Pendant le **sommeil profond** se produisent la **réparation tissulaire** et la sécrétion d'**hormone de croissance** : l'entraînement ne devient du progrès que la nuit. Un adolescent a besoin de **8 à 9 heures** ; la dette de sommeil se paie en performance et en blessures.\n4. Conseil attendu : la performance se construit autant hors séance que pendant, grâce à trois leviers qu'aucun entraînement ne rattrape. **L'assiette** : glucides, protéines et lipides, aucun à supprimer. **Le timing** : un repas complet 3 h avant, boire pendant, glucides et protéines dans les 2 h après. **Le sommeil** : 8 à 9 h, écrans coupés le soir. Refuser les boissons énergisantes et les compléments miracles, et bien sûr le **dopage**, interdit et dangereux. La régularité fait progresser."}$exo$::jsonb),
  ('0c717a05-a7e7-58a0-8224-5a96565ad8fd'::uuid, 1, 'redaction', $exo${"titre":"Olympisme, dopage et santé","consigne":"Réponds à chaque question par quelques phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Qui a rénové les Jeux olympiques modernes, et en quelle année ? Cite deux valeurs affichées par l'olympisme.\n2. Quel organisme fixe la liste des produits interdits ? Les contrôles antidopage n'ont-ils lieu qu'en compétition ?\n3. Combien de minutes d'activité physique par jour l'OMS recommande-t-elle pour un adolescent ?\n4. Qu'est-ce que l'**activité physique adaptée** ?","bareme":[{"critere":"Coubertin, 1894, deux valeurs (excellence, amitié, respect)","points":6},{"critere":"AMA et contrôles hors compétition","points":6},{"critere":"60 minutes par jour","points":3},{"critere":"Activité physique prescrite par un médecin comme un soin, depuis 2016","points":5}],"dureeMin":6,"corrige":"1. **Pierre de Coubertin**, en **1894**. Valeurs : l'**excellence**, l'**amitié**, le **respect**.\n2. L'**AMA** (Agence mondiale antidopage). Non : les contrôles peuvent avoir lieu **hors compétition**, à l'entraînement comme au domicile.\n3. Au moins **60 minutes** par jour.\n4. Depuis **2016**, une activité physique qui peut être **prescrite par un médecin comme un soin**, pour les maladies chroniques."}$exo$::jsonb),
  ('0c717a05-a7e7-58a0-8224-5a96565ad8fd'::uuid, 2, 'redaction', $exo${"titre":"Les Jeux, une scène politique","consigne":"Appuie-toi sur le document et sur le cours pour rédiger des réponses développées.","enonce":"**Document : repères de l'histoire olympique.**\n\n| Date | Événement |\n|---|---|\n| 1936 | Jeux de Berlin |\n| 1968 | Poing levé de deux athlètes sur le podium de Mexico |\n| 1980 et 1984 | Boycotts des Jeux de Moscou puis de Los Angeles |\n\n> « Le sport n'a rien à voir avec la politique. » (propos entendu dans une émission)\n\n1. Pour chaque événement du document, explique ce qu'il révèle du lien entre sport et politique.\n2. Quel idéal Pierre de Coubertin associait-il aux Jeux en 1894 ?\n3. Rédige un paragraphe argumenté qui discute le propos cité, à l'aide des exemples du document.","bareme":[{"critere":"Trois événements correctement expliqués (vitrine nazie, tribune, guerre froide)","points":9},{"critere":"Idéal de paix par le sport","points":3},{"critere":"Paragraphe argumenté qui réfute le propos avec des exemples précis","points":8}],"dureeMin":12,"corrige":"1. **Berlin 1936** : les Jeux sont une **vitrine offerte au régime nazi**, qui s'en sert pour sa propagande. **Mexico 1968** : le **podium devient une tribune politique** ; des athlètes l'utilisent pour protester devant le monde entier. **1980 et 1984** : les **boycotts croisés** montrent que la **guerre froide** entre jusque dans le stade : chaque bloc refuse de participer aux Jeux organisés chez l'autre.\n2. Un **idéal de paix par le sport**, avec des valeurs d'excellence, d'amitié et de respect.\n3. Paragraphe attendu : le propos est démenti par l'histoire. Les Jeux affichent des valeurs de paix, mais ils sont, **depuis toujours**, une **scène politique** : un régime peut s'en servir comme vitrine (Berlin 1936), des athlètes comme tribune (Mexico 1968), des États comme arme diplomatique (les boycotts de 1980 et 1984). Regarder le sport comme un **fait social**, c'est refuser de croire qu'il est neutre : c'est une institution, une économie et un discours."}$exo$::jsonb),
  ('0c717a05-a7e7-58a0-8224-5a96565ad8fd'::uuid, 3, 'redaction', $exo${"titre":"L'égalité au bout de la piste ?","consigne":"Analyse les documents, puis rédige une réponse organisée (introduction, deux parties, conclusion courte) qui mobilise le cours.","enonce":"**Document 1.** Aux Jeux de **Paris 2024**, pour la première fois, le nombre de places attribuées aux athlètes femmes et hommes est **égal**.\n\n**Document 2 : extrait d'un article.**\n\n> Dans les fédérations sportives françaises, les présidences restent très majoritairement masculines. Les compétitions féminines occupent une petite part du temps d'antenne consacré au sport, et les écarts de salaires entre sportives et sportifs professionnels demeurent considérables.\n\n**Document 3 : un rappel.** Les femmes étaient exclues des premiers Jeux modernes.\n\n**Sujet.** « Depuis Paris 2024, l'égalité entre femmes et hommes est atteinte dans le sport. » Discute cette affirmation.\n\n1. Montre, à l'aide des documents 1 et 3, les progrès accomplis.\n2. Montre, à l'aide du document 2 et du cours, ce qui reste inégal.\n3. Rédige ta réponse organisée au sujet.","bareme":[{"critere":"Progrès décrits : de l'exclusion à la parité des athlètes en 2024","points":5},{"critere":"Inégalités persistantes : médiatisation, salaires, responsabilités","points":6},{"critere":"Distinction égalité des places / égalité des moyens","points":4},{"critere":"Réponse organisée : introduction, deux parties, conclusion","points":5}],"dureeMin":20,"corrige":"1. Les femmes, **exclues des premiers Jeux modernes**, ont conquis les épreuves **une à une**, jusqu'à la **parité des athlètes à Paris en 2024** : autant de places pour les femmes que pour les hommes.\n2. L'égalité des **places** n'est pas celle des **moyens** : la **médiatisation** des compétitions féminines reste faible, les **salaires** sont très inégaux, et l'**accès aux responsabilités** reste fermé — on compte encore très peu de femmes à la tête des fédérations.\n3. Réponse attendue (plan) :\n- **Introduction** : l'affirmation s'appuie sur la parité des athlètes à Paris 2024 ; il faut se demander si l'égalité des places suffit à faire l'égalité.\n- **Partie 1 : un progrès réel.** De l'exclusion des premiers Jeux à la parité de 2024, les femmes ont conquis les épreuves une à une ; c'est une égalité d'accès à la compétition.\n- **Partie 2 : une égalité encore incomplète.** Médiatisation, salaires, responsabilités : l'égalité des places n'est pas celle des moyens ; les instances qui décident restent dominées par les hommes.\n- **Conclusion** : l'affirmation est donc excessive ; Paris 2024 marque une étape, pas l'aboutissement. Le sport, fait social, reflète les inégalités de la société."}$exo$::jsonb),
  ('5bdb8383-2a3e-50b2-aac0-32272b5090b7'::uuid, 1, 'application', $exo${"titre":"Mitose et méiose : deux divisions, deux résultats","consigne":"Réponds à chaque question par des phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Nomme les quatre phases du cycle cellulaire et précise ce qui se passe pendant la phase **S**. Quelles phases forment l'interphase ?\n2. Recopie et complète le tableau :\n\n| | Mitose | Méiose |\n| Nombre de cellules obtenues | … | … |\n| Nombre de chromosomes de chaque cellule obtenue (cellule mère à 2n) | … | … |\n| Cellules génétiquement identiques à la cellule mère ? | … | … |\n\n3. Nomme les deux brassages génétiques de la méiose et indique au cours de quelle division ils se produisent.","bareme":[{"critere":"Les quatre phases G1, S, G2, mitose ; réplication de l'ADN en S (une puis deux chromatides) ; interphase = G1 + S + G2","points":7},{"critere":"Tableau juste : 2 cellules à 2n identiques / 4 cellules à n non identiques","points":7},{"critere":"Brassages interchromosomique et intrachromosomique nommés, situés en méiose I","points":6}],"dureeMin":7,"corrige":"1. Le cycle cellulaire comprend **G1** (croissance de la cellule), **S** (réplication de l'ADN), **G2** (préparation à la division) et la **mitose** (division). Pendant la phase S, l'ADN est **répliqué** : chaque chromosome passe d'**une à deux chromatides**. G1, S et G2 forment l'**interphase**.\n2. Mitose : **2 cellules**, chacune à **2n** chromosomes, **génétiquement identiques** entre elles et à la cellule mère. Méiose : **4 cellules**, chacune à **n** chromosomes (haploïdes), **non identiques** (elles sont diversifiées).\n3. Le **brassage interchromosomique** (répartition aléatoire des chromosomes homologues) et le **brassage intrachromosomique** (crossing-over, échange de segments entre chromatides d'homologues). Les deux ont lieu pendant la **méiose I** (réductionnelle) ; la méiose II ne produit aucun brassage."}$exo$::jsonb),
  ('5bdb8383-2a3e-50b2-aac0-32272b5090b7'::uuid, 2, 'application', $exo${"titre":"Les chromosomes de la drosophile","consigne":"Réponds aux questions en justifiant chaque résultat par le déroulement des divisions vu en cours.","enonce":"**Situation.** Lucie observe au microscope des cellules de drosophile (mouche du vinaigre). Chez cette espèce, une cellule diploïde possède **2n = 8** chromosomes, soit 4 paires d'homologues.\n\n1. Indique le nombre de chromosomes et le nombre de chromatides d'une cellule diploïde : a) en phase G1 ; b) à la fin de la phase S.\n2. Cette cellule réalise une **mitose**. Combien de cellules obtient-on, avec combien de chromosomes chacune ? Justifie en décrivant ce qui se sépare pendant l'anaphase.\n3. Une cellule de la lignée germinale réalise une **méiose**. Combien de cellules obtient-on, avec combien de chromosomes chacune ?\n4. En ne tenant compte que du brassage **interchromosomique**, calcule le nombre de combinaisons de chromosomes différentes possibles dans les cellules produites. Explique pourquoi le nombre réel de combinaisons est encore bien plus grand.","bareme":[{"critere":"G1 : 8 chromosomes, 8 chromatides ; fin de S : 8 chromosomes, 16 chromatides","points":5},{"critere":"Mitose : 2 cellules à 8 chromosomes, séparation des chromatides en anaphase","points":5},{"critere":"Méiose : 4 cellules haploïdes à 4 chromosomes","points":4},{"critere":"2 puissance 4 = 16 combinaisons, et rôle du crossing-over qui en ajoute","points":6}],"dureeMin":10,"corrige":"1. a) En G1 : **8 chromosomes à une chromatide**, soit **8 chromatides**. b) À la fin de S, l'ADN a été répliqué : toujours **8 chromosomes**, mais chacun à **deux chromatides**, soit **16 chromatides**.\n2. La mitose donne **2 cellules** à **8 chromosomes** (2n = 8). En anaphase, les **deux chromatides de chaque chromosome** se séparent et migrent aux pôles : chaque pôle reçoit un exemplaire de chacun des 8 chromosomes, d'où deux cellules identiques à la cellule mère.\n3. La méiose (deux divisions successives) donne **4 cellules haploïdes** à **n = 4 chromosomes** : la méiose I sépare les homologues, la méiose II sépare les chromatides.\n4. En métaphase I, chaque paire d'homologues se place au hasard, indépendamment des autres : 2 possibilités par paire, donc **2 puissance 4 = 2 × 2 × 2 × 2 = 16 combinaisons**. Le nombre réel est bien plus grand car le **brassage intrachromosomique** (crossing-over en méiose I) échange des segments entre chromatides d'homologues et crée de nouvelles combinaisons d'allèles sur un même chromosome."}$exo$::jsonb),
  ('5bdb8383-2a3e-50b2-aac0-32272b5090b7'::uuid, 3, 'application', $exo${"titre":"Quatre cellules sous le microscope","consigne":"Analyse les observations, identifie chaque cellule en justifiant, puis rédige les réponses argumentées demandées.","enonce":"**Document 1 — Quatre cellules d'une même espèce (2n = 4), décrites par Malik.**\n\n| Cellule | Ce que l'on observe |\n| A | 4 chromosomes à deux chromatides, alignés un par un à l'équateur |\n| B | 2 paires de chromosomes homologues, placées par paires de part et d'autre de l'équateur |\n| C | 2 chromosomes à deux chromatides, non homologues, alignés à l'équateur |\n| D | 4 chromosomes à une chromatide migrant vers chaque pôle |\n\n**Document 2.** Dans certaines cellules, un point de contrôle du cycle ne fonctionne plus : la cellule se divise même lorsque son ADN est endommagé.\n\n1. Identifie la division (mitose, méiose I ou méiose II) et la phase représentée par chaque cellule. Justifie chaque réponse.\n2. En t'appuyant sur la cellule B, explique comment la méiose produit de la diversité génétique. Calcule le nombre de combinaisons dues au seul brassage interchromosomique pour cette espèce.\n3. La méiose II « ressemble à une mitose ». Justifie cette phrase à partir des cellules A et C, puis indique la différence essentielle entre elles.\n4. Explique pourquoi la situation du document 2 peut conduire à une cancérisation.","bareme":[{"critere":"Identification justifiée : A métaphase de mitose, B métaphase I, C métaphase II, D anaphase de mitose","points":6},{"critere":"Brassage interchromosomique expliqué par la disposition aléatoire des paires, 2 puissance 2 = 4, crossing-over cité","points":5},{"critere":"Comparaison méiose II / mitose : séparation des chromatides, mais cellule haploïde en méiose II","points":4},{"critere":"Rôle des points de contrôle et lien avec les anomalies et la cancérisation","points":3},{"critere":"Justifications appuyées sur les observations du document","points":2}],"dureeMin":18,"corrige":"1. **A** : 4 chromosomes (2n) à deux chromatides alignés **un par un** à l'équateur, sans appariement des homologues → **métaphase de mitose**. **B** : les homologues sont **appariés par paires** à l'équateur → **métaphase I** de méiose. **C** : seulement 2 chromosomes (n), non homologues, à deux chromatides, à l'équateur → **métaphase II**. **D** : chaque pôle reçoit 4 chromosomes (2n) à une chromatide : les chromatides se sont séparées dans une cellule diploïde → **anaphase de mitose** (en anaphase II, chaque pôle ne recevrait que 2 chromosomes).\n2. En métaphase I, chaque paire d'homologues s'oriente **au hasard**, indépendamment de l'autre ; en anaphase I, les homologues se séparent : c'est le **brassage interchromosomique**. Avec 2 paires : **2 puissance 2 = 4 combinaisons** possibles. S'y ajoute le **brassage intrachromosomique** (crossing-over entre chromatides d'homologues appariés), qui multiplie encore les combinaisons.\n3. Comme en mitose (A), en méiose II (C) les chromosomes s'alignent un par un et ce sont les **chromatides** qui se séparent ensuite : la méiose II est **équationnelle**. Différence : la cellule en méiose II est **haploïde** (n = 2), la cellule en mitose est **diploïde** (2n = 4).\n4. Les **points de contrôle** vérifient l'intégrité de l'ADN et l'attachement des chromosomes. S'ils sont défaillants, une cellule à l'ADN endommagé se divise quand même : les anomalies se transmettent aux cellules filles et s'accumulent. C'est l'un des mécanismes de la **cancérisation**."}$exo$::jsonb),
  ('de8ed94b-796f-5073-b843-116097058972'::uuid, 1, 'application', $exo${"titre":"Copier l'ADN avant de se diviser","consigne":"Réponds à chaque question en une à trois phrases, avec le vocabulaire du cours.","enonce":"1. Que signifie l'expression **réplication semi-conservative** ? Nomme les deux autres hypothèses qui ont été écartées et ce qu'elles prévoyaient.\n2. Nomme les deux enzymes de la réplication et donne le rôle de chacune. Quelle règle d'appariement l'une d'elles respecte-t-elle ?\n3. La réplication est-elle parfaitement fidèle ? Donne l'ordre de grandeur des erreurs qui subsistent et le nom de ces erreurs.","bareme":[{"critere":"Définition semi-conservative (un brin parental, un brin néoformé) et hypothèses conservative et dispersive décrites","points":8},{"critere":"Hélicase (ouvre la double hélice) et ADN polymérase (synthèse, A-T et C-G)","points":7},{"critere":"Environ une erreur par milliard de nucléotides, ce sont des mutations","points":5}],"dureeMin":6,"corrige":"1. Réplication **semi-conservative** : chaque molécule d'ADN fille est formée d'un **brin parental conservé** et d'un **brin néoformé**. Hypothèses écartées par Meselson et Stahl (1958) : la **conservative** (une molécule intacte et une molécule entièrement neuve) et la **dispersive** (des fragments anciens et neufs mêlés dans chaque molécule).\n2. L'**ADN hélicase** ouvre la double hélice et forme un œil de réplication bordé de deux fourches. L'**ADN polymérase** synthétise le brin complémentaire en respectant l'appariement **A-T et C-G**.\n3. Non. La polymérase corrige la plupart de ses erreurs et des systèmes de réparation interviennent, mais il subsiste environ **une erreur par milliard de nucléotides** copiés : ces erreurs sont des **mutations**."}$exo$::jsonb),
  ('de8ed94b-796f-5073-b843-116097058972'::uuid, 2, 'application', $exo${"titre":"Rejouer l'expérience de Meselson et Stahl","consigne":"Lis le protocole, puis raisonne hypothèse par hypothèse pour répondre.","enonce":"**Le principe.** Des bactéries sont cultivées longtemps dans un milieu contenant un azote « lourd » : tout leur ADN est lourd. On les transfère dans un milieu à azote « léger », où tout brin néoformé est léger. Après chaque génération, on sépare les molécules d'ADN selon leur densité : une molécule à deux brins lourds forme une bande **lourde**, une molécule à deux brins légers une bande **légère**, une molécule à un brin lourd et un brin léger une bande **intermédiaire**.\n\n**Les résultats.**\n\n| Génération | Bandes observées |\n| 0 | Une seule bande lourde |\n| 1 | Une seule bande intermédiaire |\n| 2 | Une bande intermédiaire et une bande légère, de même importance |\n\n1. Quelles bandes l'hypothèse **conservative** prévoit-elle à la génération 1 ? Le résultat la confirme-t-il ?\n2. Montre que l'hypothèse **semi-conservative** explique les résultats des générations 1 et 2 (un schéma légendé des brins est accepté).\n3. Selon l'hypothèse semi-conservative, quelle proportion des molécules d'ADN sera intermédiaire à la génération 3 ? Détaille ton calcul à partir d'une seule molécule de départ.","bareme":[{"critere":"Conservative : une bande lourde et une bande légère à la génération 1, hypothèse écartée","points":6},{"critere":"Semi-conservative : génération 1 toute intermédiaire, génération 2 moitié intermédiaire et moitié légère, expliqué brin par brin","points":8},{"critere":"Génération 3 : 2 molécules intermédiaires sur 8, soit 25 %","points":6}],"dureeMin":11,"corrige":"1. Dans l'hypothèse **conservative**, la molécule parentale reste intacte (deux brins lourds) et la molécule fille est entièrement neuve (deux brins légers) : on attendrait à la génération 1 **une bande lourde et une bande légère**. On n'observe qu'une bande intermédiaire : l'hypothèse est **écartée**.\n2. Hypothèse **semi-conservative** : génération 1, chaque molécule fille garde un brin lourd parental et reçoit un brin léger néoformé → toutes les molécules sont **intermédiaires** (une seule bande, conforme). Génération 2 : chaque molécule intermédiaire se réplique ; son brin lourd reçoit un brin léger (molécule intermédiaire) et son brin léger reçoit un brin léger (molécule légère) → **moitié intermédiaire, moitié légère**, conforme aux deux bandes de même importance.\n3. Partons d'une molécule lourde : génération 1 → 2 molécules intermédiaires ; génération 2 → 4 molécules (2 intermédiaires, 2 légères) ; génération 3 → 8 molécules. Les deux brins lourds d'origine sont conservés et se retrouvent dans **2 molécules intermédiaires** seulement. Proportion : 2 / 8 = **1/4, soit 25 %** d'intermédiaires et 75 % de légères."}$exo$::jsonb),
  ('de8ed94b-796f-5073-b843-116097058972'::uuid, 3, 'application', $exo${"titre":"Copier vite, copier juste","consigne":"Exploite les données chiffrées, pose tes calculs, puis rédige une argumentation appuyée sur le cours.","enonce":"**Document 1.** Un chromosome humain contient environ **150 millions** de paires de bases. Chaque fourche de réplication avance d'environ **50 nucléotides par seconde**, et un œil de réplication possède deux fourches qui avancent en sens opposés.\n\n**Document 2.** Sur ce chromosome, on dénombre environ **1 500 origines de réplication** actives en même temps, régulièrement réparties.\n\n**Document 3.** Après une exposition prolongée au soleil, on détecte dans l'ADN des cellules de la peau des bases voisines d'un même brin soudées entre elles.\n\n1. Calcule la durée de réplication de ce chromosome s'il n'avait qu'**une seule** origine, placée au milieu. Exprime-la en jours.\n2. Calcule la durée de réplication avec les 1 500 origines du document 2. Exprime-la en minutes. Conclus sur l'intérêt des origines multiples.\n3. Le génome humain compte environ 3 milliards de paires de bases. Estime le nombre d'erreurs qui subsistent à chaque copie complète du génome.\n4. Identifie l'agent mutagène du document 3 et son effet. Explique pourquoi le cours affirme qu'une fidélité totale « interdirait toute évolution ».","bareme":[{"critere":"Une origine : 150 000 000 / 100 = 1 500 000 s, soit environ 17 jours","points":5},{"critere":"1 500 origines : 100 000 pb par œil, 1 000 s, environ 17 min ; conclusion sur les origines multiples","points":5},{"critere":"Environ 3 erreurs par copie du génome, calcul posé","points":3},{"critere":"UV qui soudent deux bases voisines ; mutations source de diversité et d'évolution","points":5},{"critere":"Unités et conversions correctes","points":2}],"dureeMin":18,"corrige":"1. Avec une origine et deux fourches, le chromosome est copié à 2 × 50 = **100 nucléotides par seconde**. Durée : 150 000 000 / 100 = **1 500 000 s**. En jours : 1 500 000 / 86 400 ≈ **17 jours** (plus de deux semaines).\n2. Avec 1 500 origines, chaque œil copie 150 000 000 / 1 500 = **100 000 paires de bases**, à 100 nucléotides par seconde : 100 000 / 100 = **1 000 s**, soit environ **17 minutes**. Les origines multiples et simultanées permettent de copier un ADN très long en un temps compatible avec le cycle cellulaire ; sans elles, copier ce seul chromosome prendrait des semaines.\n3. Il subsiste environ une erreur par milliard de nucléotides : 3 000 000 000 × 1/1 000 000 000 = **environ 3 erreurs** à chaque copie complète.\n4. L'agent est le **rayonnement ultraviolet** (UV) : il **soude deux bases voisines** d'un même brin, ce qui provoque des erreurs de réplication, donc des mutations. Une fidélité totale ne produirait **aucune mutation** : il n'y aurait ni nouveaux allèles ni diversité génétique, donc rien sur quoi l'évolution puisse agir. Une fidélité médiocre, à l'inverse, rendrait la vie impossible : le vivant fonctionne sur ce **compromis**."}$exo$::jsonb),
  ('21a7ae15-4688-5b42-9128-d3b611f7eca0'::uuid, 1, 'application', $exo${"titre":"Du gène à la protéine, étape par étape","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Nomme les étapes qui permettent de passer d'un gène à une protéine chez un eucaryote. Pour chacune, indique son lieu dans la cellule et la molécule produite.\n2. Donne trois différences entre l'ADN et l'ARN.\n3. Qu'est-ce que l'**épissage** ? Pourquoi l'épissage alternatif permet-il à un gène de produire plusieurs protéines ?\n4. Cite les trois propriétés du code génétique et explique l'une d'elles.","bareme":[{"critere":"Transcription (noyau, pré-ARNm), maturation (noyau, ARNm), traduction (cytoplasme, protéine)","points":6},{"critere":"Trois différences : double/simple brin, désoxyribose/ribose, T/U","points":5},{"critere":"Épissage (introns excisés, exons raboutés) et épissage alternatif expliqué","points":5},{"critere":"Universel, redondant, non ambigu, avec une propriété expliquée","points":4}],"dureeMin":8,"corrige":"1. **Transcription** dans le **noyau** : l'ARN polymérase copie le brin transcrit en **ARN pré-messager**. **Maturation** dans le noyau : le pré-messager devient un **ARN messager**. **Traduction** dans le **cytoplasme** : le ribosome lit l'ARNm et produit une **protéine**.\n2. L'ADN est **double brin**, l'ARN **simple brin** ; l'ADN contient du **désoxyribose**, l'ARN du **ribose** ; l'ADN contient de la **thymine**, remplacée dans l'ARN par l'**uracile**.\n3. L'épissage est l'étape de maturation où les **introns**, non codants, sont **excisés** et les **exons raboutés**. Dans l'**épissage alternatif**, les exons conservés ne sont pas toujours les mêmes : un même pré-messager donne plusieurs ARN messagers différents, donc plusieurs protéines.\n4. Le code est **universel** (le même chez presque tous les vivants), **redondant** (64 codons pour 20 acides aminés : des codons synonymes) et **non ambigu** (un codon ne code qu'un seul acide aminé). Exemple : l'universalité rend possible le génie génétique."}$exo$::jsonb),
  ('21a7ae15-4688-5b42-9128-d3b611f7eca0'::uuid, 2, 'application', $exo${"titre":"Décoder un petit gène","consigne":"Utilise l'extrait du code génétique pour répondre ; détaille chaque étape.","enonce":"**Situation.** Inès étudie le début d'un gène. Voici la séquence de son **brin transcrit** (lu dans le sens de la transcription) :\n\n> 3' TAC CGA ACC TTT ATT 5'\n\n**Extrait du code génétique (codons de l'ARNm)**\n\n| Codon | Acide aminé |\n| AUG | Méthionine (Met) |\n| GCU, GCC | Alanine (Ala) |\n| UGG | Tryptophane (Trp) |\n| AAA, AAG | Lysine (Lys) |\n| UAA | Stop |\n\n1. Écris la séquence de l'**ARN messager** obtenu par transcription. Justifie la règle utilisée.\n2. Découpe cet ARNm en codons et écris la séquence d'acides aminés du peptide. Explique le rôle du ribosome et des ARN de transfert.\n3. Une modification transforme le codon AAA en AAG. Quelle est la conséquence sur le peptide ? Quelle propriété du code génétique l'explique ?","bareme":[{"critere":"ARNm juste : AUG GCU UGG AAA UAA, complémentarité avec U à la place de T","points":6},{"critere":"Peptide Met-Ala-Trp-Lys, arrêt au codon stop","points":6},{"critere":"Rôle du ribosome (lecture par codons) et des ARNt (apport des acides aminés)","points":4},{"critere":"AAG code encore Lys : peptide inchangé, redondance du code","points":4}],"dureeMin":11,"corrige":"1. L'ARNm est **complémentaire du brin transcrit**, avec l'appariement A-U, T-A, C-G, G-C (l'uracile remplace la thymine). On obtient : **5' AUG GCU UGG AAA UAA 3'**.\n2. Codons : AUG / GCU / UGG / AAA / UAA → **Met – Ala – Trp – Lys**, puis **UAA = codon stop** : la traduction s'arrête. Le peptide compte 4 acides aminés. Le **ribosome** lit l'ARNm par groupes de trois nucléotides (codons) ; à chaque codon, un **ARN de transfert** apporte l'acide aminé correspondant, et la chaîne s'allonge jusqu'au codon stop.\n3. AAG code aussi la **lysine** : le peptide est **inchangé** (Met-Ala-Trp-Lys). C'est la **redondance** du code : plusieurs codons synonymes codent le même acide aminé, si bien qu'une modification ponctuelle peut être **silencieuse**."}$exo$::jsonb),
  ('21a7ae15-4688-5b42-9128-d3b611f7eca0'::uuid, 3, 'application', $exo${"titre":"Un gène, plusieurs protéines, un phénotype","consigne":"Exploite les documents et rédige des réponses argumentées qui mobilisent le cours.","enonce":"**Document 1.** On estime que l'humain possède environ 20 000 gènes codant des protéines, mais qu'il fabrique plusieurs dizaines de milliers de protéines différentes.\n\n**Document 2.** Un gène comporte quatre exons (E1, E2, E3, E4) séparés par des introns. Dans le tissu musculaire, on trouve l'ARNm E1-E2-E3-E4 ; dans le tissu nerveux, l'ARNm E1-E3-E4.\n\n**Document 3.** Un gène humain codant l'insuline a été introduit dans des bactéries : elles fabriquent une insuline identique à l'insuline humaine.\n\n**Document 4.** Deux jumeaux ont le même génotype. L'un vit en altitude, l'autre au bord de la mer : après quelques mois, leur quantité de globules rouges n'est plus la même.\n\n1. Explique à l'aide du document 2 comment le document 1 est possible. Si E1 et E4 sont toujours conservés et que E2 et E3 peuvent chacun être gardés ou retirés, combien d'ARNm différents ce gène peut-il donner ? Énumère-les.\n2. Quelle propriété du code génétique le document 3 met-il en évidence ? Justifie.\n3. Explique le document 4 en utilisant les notions de génotype, d'environnement et de phénotype.\n4. En une phrase, résume le trajet de l'information génétique du gène à la protéine, en précisant les lieux.","bareme":[{"critere":"Épissage alternatif expliqué à partir du document 2","points":5},{"critere":"4 ARNm possibles : E1-E2-E3-E4, E1-E2-E4, E1-E3-E4, E1-E4","points":4},{"critere":"Universalité du code justifiée par la bactérie qui traduit le gène humain","points":4},{"critere":"Phénotype = interaction du génotype et de l'environnement, appliqué aux jumeaux","points":4},{"critere":"Trajet transcription (noyau), maturation, traduction (cytoplasme)","points":3}],"dureeMin":17,"corrige":"1. Lors de la maturation, les introns sont excisés et les exons raboutés ; mais les exons conservés peuvent varier : c'est l'**épissage alternatif**. Le document 2 le montre : le même gène donne un ARNm avec E2 dans le muscle et sans E2 dans le tissu nerveux, donc deux protéines différentes. Un gène pouvant donner plusieurs protéines, 20 000 gènes peuvent en produire des dizaines de milliers. Nombre d'ARNm : E2 gardé ou non (2 cas) × E3 gardé ou non (2 cas) = **4 ARNm** : **E1-E2-E3-E4, E1-E2-E4, E1-E3-E4, E1-E4**.\n2. Le code génétique est **universel** : il est le même chez presque tous les vivants. La bactérie lit les codons du gène humain de la même façon qu'une cellule humaine et produit la même protéine ; c'est ce qui rend possible le **génie génétique**.\n3. Le **génotype** des jumeaux est identique, mais le **phénotype** (quantité de globules rouges) diffère : le phénotype résulte de l'**interaction entre le génotype et l'environnement** (ici l'altitude).\n4. Dans le **noyau**, le gène est **transcrit** en ARN pré-messager, qui devient par **maturation** un ARN messager ; dans le **cytoplasme**, les ribosomes le **traduisent** en protéine."}$exo$::jsonb),
  ('18c1bed0-1b68-55d9-8d33-2f96974c1446'::uuid, 1, 'application', $exo${"titre":"Classer les mutations","consigne":"Réponds à chaque question par des phrases complètes, en utilisant le vocabulaire du cours.","enonce":"1. Définis une mutation et nomme les trois types de mutations ponctuelles, en expliquant ce qui change dans chacun.\n2. Explique pourquoi une délétion d'un seul nucléotide est souvent plus grave qu'une substitution.\n3. Recopie et complète :\n\n| Mutation | Ce qu'elle produit | Conséquence sur la protéine |\n| Silencieuse | … | … |\n| Faux-sens | … | … |\n| Non-sens | … | … |\n\n4. Une mutation dans une cellule de la peau sera-t-elle transmise aux enfants ? Justifie avec les mots **somatique** et **germinale**.","bareme":[{"critere":"Définition et trois types (substitution, délétion, insertion) décrits","points":5},{"critere":"Décalage du cadre de lecture expliqué","points":5},{"critere":"Tableau juste (codon synonyme / acide aminé remplacé / codon stop prématuré et leurs effets)","points":6},{"critere":"Mutation somatique non transmise, opposée à la mutation germinale","points":4}],"dureeMin":8,"corrige":"1. Une mutation est une **modification de la séquence des nucléotides**. **Substitution** : un nucléotide est remplacé par un autre. **Délétion** : un ou plusieurs nucléotides sont perdus. **Insertion** : un ou plusieurs nucléotides sont ajoutés.\n2. Une délétion d'un nucléotide (non multiple de trois) provoque un **décalage du cadre de lecture** : tous les codons suivants sont modifiés, donc toute la suite de la protéine. Une substitution ne touche qu'un codon.\n3. **Silencieuse** : codon synonyme → protéine **inchangée**. **Faux-sens** : un acide aminé remplacé → protéine fonctionnelle, moins efficace ou inactive. **Non-sens** : codon stop prématuré → protéine **tronquée**, le plus souvent inactive.\n4. Non. Une cellule de la peau est une cellule du corps : la mutation est **somatique**, elle n'est transmise qu'à ses cellules filles et disparaît avec l'individu. Seule une mutation **germinale**, dans la lignée reproductrice, est transmise à la descendance."}$exo$::jsonb),
  ('18c1bed0-1b68-55d9-8d33-2f96974c1446'::uuid, 2, 'application', $exo${"titre":"Trois mutants sur un même gène","consigne":"Compare chaque séquence mutée à la séquence normale à l'aide de l'extrait du code génétique ; justifie chaque réponse.","enonce":"**Séquence normale de l'ARNm (début du gène) :**\n\n> AUG GCU UGG AAA GGC UAA\n\n**Trois mutants :**\n- mutant 1 : le codon GCU devient **GCC** ;\n- mutant 2 : le codon UGG devient **UAG** ;\n- mutant 3 : le **G** de GCU (4e nucléotide) est perdu.\n\n**Extrait du code génétique**\n\n| Codon | Acide aminé |\n| AUG | Met |\n| GCU, GCC | Ala |\n| UGG | Trp |\n| AAA, AAG | Lys |\n| GGC, GGA | Gly |\n| CUU | Leu |\n| UAA, UAG | Stop |\n\n1. Écris la séquence d'acides aminés de la protéine normale.\n2. Pour les mutants 1 et 2, nomme le type de mutation, écris le peptide obtenu et classe la mutation selon sa conséquence.\n3. Pour le mutant 3, écris la nouvelle séquence de l'ARNm découpée en codons et les premiers acides aminés. Explique pourquoi ce mutant est le plus grave.","bareme":[{"critere":"Protéine normale : Met-Ala-Trp-Lys-Gly","points":3},{"critere":"Mutant 1 : substitution silencieuse, peptide inchangé","points":5},{"critere":"Mutant 2 : substitution non-sens, peptide Met-Ala tronqué","points":5},{"critere":"Mutant 3 : délétion, AUG CUU GGA AAG GCU…, Met-Leu-Gly-Lys-Ala, décalage du cadre de lecture","points":7}],"dureeMin":12,"corrige":"1. AUG / GCU / UGG / AAA / GGC / UAA → **Met – Ala – Trp – Lys – Gly**, puis stop.\n2. **Mutant 1** : un nucléotide remplacé (U → C) : **substitution**. GCC code encore l'alanine : peptide **Met-Ala-Trp-Lys-Gly**, inchangé → mutation **silencieuse** (codon synonyme).\n**Mutant 2** : substitution (G → A). UAG est un **codon stop** : la traduction s'arrête après Met-Ala → peptide **Met-Ala**, tronqué, le plus souvent inactif → mutation **non-sens**.\n3. **Mutant 3** : **délétion** d'un nucléotide. Séquence : AUGCUUGGAAAGGCUAA… découpée en **AUG / CUU / GGA / AAG / GCU / …** → **Met – Leu – Gly – Lys – Ala – …**. Dès le deuxième acide aminé, tous sont susceptibles de changer : la délétion d'un nucléotide (non multiple de trois) **décale le cadre de lecture**, et toute la suite de la protéine est modifiée. C'est le mutant le plus grave : la protéine produite n'a plus rien à voir avec la protéine normale."}$exo$::jsonb),
  ('18c1bed0-1b68-55d9-8d33-2f96974c1446'::uuid, 3, 'application', $exo${"titre":"L'allèle de la drépanocytose","consigne":"Exploite les documents et rédige une réponse argumentée qui mobilise les notions du cours.","enonce":"**Document 1.** L'allèle responsable de la drépanocytose diffère de l'allèle le plus courant du gène de l'hémoglobine par **un seul nucléotide** : dans la protéine, un acide aminé (l'acide glutamique) est remplacé par un autre (la valine).\n\n**Document 2.** Cet allèle est fréquent dans des régions d'Afrique où le paludisme sévit, et rare dans les régions où le paludisme est absent. Les porteurs de l'allèle y sont protégés contre les formes graves du paludisme.\n\n**Document 3.** Sur une petite île isolée, peuplée de quelques centaines d'habitants, la fréquence d'un allèle sans effet connu sur la survie est passée de 10 % à 30 % en quelques générations, alors qu'elle est restée stable sur le continent voisin.\n\n1. Nomme le type de mutation à l'origine de l'allèle de la drépanocytose et sa conséquence sur la protéine (document 1).\n2. Pour que cet allèle existe dans une population, quel type de cellule la mutation a-t-elle dû toucher chez un ancêtre ? Justifie.\n3. Explique la répartition de l'allèle décrite dans le document 2 en nommant la force évolutive en jeu.\n4. Quelle force évolutive explique le document 3 ? Pourquoi agit-elle ici et pas sur le continent ?\n5. Explique la phrase du cours : « une mutation n'est ni bonne ni mauvaise en soi ».","bareme":[{"critere":"Substitution faux-sens : un acide aminé remplacé","points":4},{"critere":"Mutation germinale, seule transmise à la descendance","points":3},{"critere":"Sélection naturelle favorisant l'allèle là où sévit le paludisme","points":5},{"critere":"Dérive génétique, effet du hasard marqué dans les petites populations","points":5},{"critere":"Valeur d'un allèle dépendant de l'environnement, argumentée","points":3}],"dureeMin":18,"corrige":"1. Un seul nucléotide est remplacé par un autre : c'est une **substitution**. Elle remplace un acide aminé par un autre : mutation **faux-sens** ; la protéine est modifiée (moins efficace ou altérée).\n2. La mutation a dû toucher une cellule de la **lignée germinale** (mutation **germinale**) : seule celle-là est transmise à la descendance et peut se répandre dans une population. Une mutation somatique disparaît avec l'individu.\n3. Là où sévit le paludisme, les porteurs de l'allèle survivent mieux et ont plus de descendants : l'allèle est **avantageux** et sa fréquence augmente par **sélection naturelle**. Là où le paludisme est absent, il n'apporte pas d'avantage (et cause une maladie) : il reste rare.\n4. L'allèle n'a pas d'effet sur la survie : sa variation est due au **hasard** de la transmission, c'est la **dérive génétique**. Elle est surtout efficace dans les **petites populations** (quelques centaines d'habitants) ; dans une grande population comme celle du continent, les effets du hasard se compensent et la fréquence reste stable. L'isolement limite aussi les **migrations**, qui auraient fait circuler les allèles.\n5. Le même allèle est **avantageux** dans un environnement (protection contre le paludisme) et **défavorable** dans un autre (maladie sans bénéfice) : c'est **l'environnement qui décide** de la valeur d'un allèle, pas la mutation elle-même."}$exo$::jsonb),
  ('dca1c5d4-bf4e-5ee8-9d44-764e8cd1cb2e'::uuid, 1, 'application', $exo${"titre":"Lire l'histoire dans l'ADN","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Qu'est-ce qu'un **marqueur génétique** ? Que conclut-on si deux populations partagent beaucoup de marqueurs ?\n2. Qu'appelle-t-on **horloge moléculaire** ?\n3. Quelle lignée l'ADN mitochondrial permet-il de suivre ? Et le chromosome Y ? Justifie par leur mode de transmission.\n4. Où et quand *Homo sapiens* est-il apparu ? Quel argument génétique soutient cette origine ?","bareme":[{"critere":"Marqueur = mutation neutre accumulée ; beaucoup de marqueurs partagés = divergence récente","points":5},{"critere":"Horloge moléculaire : taux de mutation utilisé pour dater les séparations","points":4},{"critere":"ADN mitochondrial = lignée maternelle, chromosome Y = lignée paternelle, justifiés","points":6},{"critere":"Afrique, environ 300 000 ans, diversité génétique maximale en Afrique","points":5}],"dureeMin":7,"corrige":"1. Un marqueur génétique est une **mutation neutre** accumulée au fil du temps, que l'on compare entre populations. Si deux populations partagent **beaucoup de marqueurs**, elles ont divergé **récemment** ; très différentes, elles ont divergé tôt.\n2. L'**horloge moléculaire** consiste à utiliser le **taux de mutation** pour **dater** la séparation entre deux lignées : plus il y a de différences, plus la séparation est ancienne.\n3. L'**ADN mitochondrial** se transmet **uniquement par la mère** : il trace la **lignée maternelle**. Le **chromosome Y** se transmet **de père en fils** : il trace la **lignée paternelle**.\n4. *Homo sapiens* apparaît en **Afrique** il y a **environ 300 000 ans**. Argument majeur : la **diversité génétique y est maximale**."}$exo$::jsonb),
  ('dca1c5d4-bf4e-5ee8-9d44-764e8cd1cb2e'::uuid, 2, 'application', $exo${"titre":"Dater des séparations entre populations","consigne":"Exploite le tableau, pose tes calculs et justifie tes conclusions.","enonce":"**Situation.** Une équipe compare une même portion d'ADN mitochondrial chez trois populations actuelles, A, B et C. Le tableau donne le nombre moyen de différences entre deux individus pris dans deux populations.\n\n| Comparaison | Nombre de différences |\n| A et B | 4 |\n| A et C | 12 |\n| B et C | 12 |\n\nOn admet, pour cette portion d'ADN, qu'**une différence correspond à 25 000 ans** de séparation entre deux lignées.\n\n1. Quelles populations ont divergé le plus récemment ? Justifie.\n2. Calcule la date de séparation entre A et B, puis entre C et l'ancêtre commun de A et B.\n3. Propose un arbre (schéma ou phrase) qui résume ces liens de parenté.\n4. L'étude porte sur l'ADN mitochondrial : de quelle lignée retrace-t-elle l'histoire ? Quel autre marqueur faudrait-il étudier pour l'autre lignée ?","bareme":[{"critere":"A et B ont divergé le plus récemment : moins de différences","points":4},{"critere":"A-B : 4 × 25 000 = 100 000 ans ; C : 12 × 25 000 = 300 000 ans","points":7},{"critere":"Arbre cohérent : C se sépare d'abord, puis A et B","points":4},{"critere":"Lignée maternelle ; chromosome Y pour la lignée paternelle","points":5}],"dureeMin":11,"corrige":"1. **A et B** : ils ne présentent que **4 différences**, contre 12 avec C. Des populations qui partagent beaucoup de marqueurs ont divergé **récemment**.\n2. A–B : 4 × 25 000 = **100 000 ans**. C et l'ancêtre commun de A et B : 12 × 25 000 = **300 000 ans** (A et B sont chacune à 12 différences de C, elles s'en sont séparées ensemble).\n3. Il y a 300 000 ans, une population ancestrale se divise : d'un côté la lignée menant à **C**, de l'autre l'ancêtre commun de A et B ; il y a 100 000 ans, ce dernier se divise en **A** et **B**. Schéma : ((A, B), C).\n4. L'ADN mitochondrial se transmet uniquement par la mère : l'étude retrace la **lignée maternelle**. Pour la **lignée paternelle**, il faudrait étudier le **chromosome Y**, transmis de père en fils. C'est le principe de l'**horloge moléculaire**."}$exo$::jsonb),
  ('dca1c5d4-bf4e-5ee8-9d44-764e8cd1cb2e'::uuid, 3, 'application', $exo${"titre":"Un peuplement, des métissages, une seule humanité","consigne":"Exploite chaque document, puis rédige une conclusion argumentée qui mobilise le cours.","enonce":"**Document 1.** La diversité génétique mesurée dans des populations actuelles est la plus élevée dans les populations d'Afrique ; elle est plus faible dans les autres continents.\n\n**Document 2.** Le génome de populations européennes et asiatiques actuelles contient quelques pour cent de séquences très proches de celles d'un fossile de Néandertal ; on ne retrouve pas ces séquences, ou très peu, dans des populations d'Afrique subsaharienne.\n\n**Document 3.** L'allèle permettant de digérer le lait à l'âge adulte (persistance de la lactase) est fréquent dans des populations à longue tradition d'élevage laitier, rare dans des populations sans cette tradition.\n\n**Document 4.** Environ 85 % de la variabilité génétique humaine totale se trouve entre individus d'une même population ; seuls 15 % environ distinguent les populations entre elles.\n\n1. Montre que le document 1 est un argument en faveur d'une origine africaine d'*Homo sapiens*.\n2. Que révèle le document 2 sur l'histoire des populations non africaines ?\n3. Explique le document 3 en nommant le mécanisme en jeu.\n4. À partir du document 4, discute la notion de « race » humaine.","bareme":[{"critere":"Diversité maximale en Afrique : population la plus ancienne, les autres en sont issues","points":5},{"critere":"Métissages avec Néandertal après la sortie d'Afrique","points":4},{"critere":"Sélection naturelle d'un allèle avantageux chez les éleveurs : adaptation récente","points":5},{"critere":"Variabilité intra-population supérieure à l'inter-population : pas de fondement génétique à la notion de race","points":4},{"critere":"Réponses justifiées par les données des documents","points":2}],"dureeMin":18,"corrige":"1. La diversité génétique reflète l'accumulation de mutations au fil du temps : elle est **maximale en Afrique** parce que les populations y vivent depuis le plus longtemps. Les populations des autres continents, moins diverses, descendent de groupes partis d'Afrique. C'est un **argument majeur** en faveur d'une origine africaine d'*Homo sapiens*, il y a environ 300 000 ans.\n2. Les populations non africaines portent quelques pour cent d'ADN de **Néandertal**, absent ou presque en Afrique subsaharienne : après leur sortie d'Afrique, leurs ancêtres se sont **métissés** avec des Néandertaliens.\n3. Chez les éleveurs, pouvoir digérer le lait à l'âge adulte est un **avantage** : les porteurs de l'allèle ont eu plus de descendants, et sa fréquence a augmenté par **sélection naturelle**. C'est une **adaptation récente**, liée au mode de vie.\n4. La variabilité **entre individus d'une même population** (85 %) **dépasse** largement la variabilité moyenne **entre populations** (15 %). Deux individus d'une même population peuvent être plus différents génétiquement que deux individus de populations distinctes : la notion biologique de « race » humaine **n'a aucun fondement génétique**. Conclusion : l'ADN garde la trace d'une origine africaine commune, de métissages et d'adaptations locales, au sein d'une seule humanité."}$exo$::jsonb),
  ('0f5ff5c6-af95-52a5-a98c-bbd2fbb87ce1'::uuid, 1, 'application', $exo${"titre":"L'enzyme, catalyseur spécifique","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Définis une **enzyme**. Pourquoi peut-on dire qu'elle est sous le contrôle d'un gène ?\n2. Une enzyme possède une **double spécificité**. Nomme et explique chacune.\n3. Décris dans l'ordre les quatre étapes de la catalyse, du substrat à l'enzyme libérée.\n4. Cite deux facteurs qui font varier l'activité d'une enzyme et leur effet.","bareme":[{"critere":"Protéine catalytique qui accélère une réaction sans être consommée ; codée par un gène","points":5},{"critere":"Spécificité de substrat (site actif complémentaire) et spécificité d'action","points":6},{"critere":"Fixation au site actif, réaction, libération des produits, enzyme intacte qui recommence","points":5},{"critere":"Deux facteurs justes avec leur effet (température, pH, substrat, inhibiteurs)","points":4}],"dureeMin":7,"corrige":"1. Une enzyme est une **protéine catalytique** : elle **accélère** une réaction chimique **sans être consommée ni modifiée**, et sans changer le bilan de la réaction. Comme toute protéine, elle est **codée par un gène** : un gène muté peut donner une enzyme inefficace.\n2. **Spécificité de substrat** : l'enzyme ne reconnaît qu'un substrat (ou une famille très proche), car son **site actif** est complémentaire du substrat (modèle clé-serrure, affiné en ajustement induit). **Spécificité d'action** : elle ne catalyse qu'un seul type de réaction.\n3. (1) Le substrat se fixe au **site actif** (complexe enzyme-substrat) ; (2) la réaction s'effectue ; (3) les **produits sont libérés** ; (4) l'enzyme, **intacte**, recommence.\n4. Exemples : la **température** (l'activité augmente puis chute quand la protéine se dénature) ; le **pH** (chaque enzyme a son optimum) ; la **concentration en substrat** (l'activité croît jusqu'à un plateau) ; les **inhibiteurs** (ils bloquent le site actif)."}$exo$::jsonb),
  ('0f5ff5c6-af95-52a5-a98c-bbd2fbb87ce1'::uuid, 2, 'application', $exo${"titre":"L'amylase au bain-marie","consigne":"Exploite les résultats expérimentaux et justifie chaque conclusion avec le cours.","enonce":"**Situation.** Hugo mesure l'activité d'une amylase (quantité de produit formée par minute, en unités arbitraires) à différentes températures, à pH 7.\n\n| Température (°C) | 0 | 10 | 20 | 37 | 50 | 60 | 70 |\n| Activité | 2 | 12 | 30 | 55 | 30 | 5 | 0 |\n\nIl fait ensuite deux essais complémentaires :\n- un tube maintenu à 0 °C, puis ramené à 37 °C : activité **55** ;\n- un tube maintenu à 70 °C, puis ramené à 37 °C : activité **0**.\n\n1. Décris l'évolution de l'activité et donne la température optimale.\n2. Interprète les deux essais complémentaires : que devient l'enzyme à 0 °C ? à 70 °C ? Explique.\n3. Hugo refait l'expérience à 37 °C, mais à pH 2. L'activité est presque nulle. Explique ce résultat, sachant que l'amylase salivaire a un optimum de pH neutre. Quelle enzyme digestive citée en cours fonctionnerait bien à ce pH ?","bareme":[{"critere":"Description de la courbe (hausse puis chute) et optimum à 37 °C","points":6},{"critere":"0 °C : enzyme ralentie mais intacte ; 70 °C : dénaturation irréversible de la protéine","points":8},{"critere":"pH 2 éloigné de l'optimum neutre de l'amylase ; la pepsine agit en milieu très acide","points":6}],"dureeMin":11,"corrige":"1. L'activité **augmente** de 0 °C (2) à 37 °C (55), puis **chute brutalement** au-delà : 30 à 50 °C, 5 à 60 °C, 0 à 70 °C. La température optimale est **37 °C** (parmi les valeurs testées).\n2. À **0 °C**, l'activité est très faible mais redevient **55** à 37 °C : le froid **ralentit** l'enzyme sans l'abîmer, l'effet est réversible. À **70 °C**, l'activité reste **nulle** même ramenée à 37 °C : l'enzyme, qui est une protéine, a été **dénaturée** ; sa forme, donc son site actif, est détruite de façon irréversible.\n3. Chaque enzyme a un **pH optimal**. L'amylase salivaire fonctionne à pH **neutre** : à pH 2, très acide, elle est presque inactive. La **pepsine**, enzyme de l'estomac, a au contraire son optimum en **milieu très acide**."}$exo$::jsonb),
  ('0f5ff5c6-af95-52a5-a98c-bbd2fbb87ce1'::uuid, 3, 'application', $exo${"titre":"Saturation, inhibiteur et maladie métabolique","consigne":"Exploite les documents, puis rédige des réponses argumentées qui relient les résultats au fonctionnement de l'enzyme.","enonce":"**Document 1 — Vitesse d'une réaction enzymatique selon la concentration en substrat (quantité d'enzyme constante).**\n\n| Substrat (mmol/L) | 0 | 1 | 2 | 5 | 10 | 20 | 40 |\n| Vitesse sans inhibiteur | 0 | 20 | 35 | 60 | 78 | 80 | 80 |\n| Vitesse avec une molécule X | 0 | 8 | 15 | 35 | 55 | 70 | 78 |\n\nLa molécule X a une forme très proche de celle du substrat.\n\n**Document 2.** La phénylcétonurie est une maladie métabolique : une enzyme qui dégrade un acide aminé, la phénylalanine, est déficiente à cause d'une mutation de son gène. Chez les malades, la phénylalanine s'accumule dans le sang.\n\n1. Décris la courbe sans inhibiteur et explique pourquoi la vitesse atteint un plateau.\n2. Comment la molécule X agit-elle sur l'enzyme ? Appuie-toi sur sa forme et sur les valeurs du tableau. Pourquoi son effet diminue-t-il quand le substrat devient très abondant ?\n3. Explique l'accumulation de phénylalanine du document 2, du gène à la voie métabolique.\n4. Montre, à partir de ces deux documents, que l'activité d'une enzyme dépend à la fois de son environnement et de son gène.","bareme":[{"critere":"Vitesse croissante puis plateau à 80 : tous les sites actifs occupés (saturation)","points":5},{"critere":"X inhibiteur qui occupe le site actif à la place du substrat, valeurs citées","points":5},{"critere":"Substrat abondant qui l'emporte sur X : effet atténué à 40 mmol/L","points":3},{"critere":"Gène muté → enzyme déficiente → dégradation interrompue → accumulation","points":4},{"critere":"Synthèse : facteurs du milieu et contrôle génétique","points":3}],"dureeMin":18,"corrige":"1. Sans inhibiteur, la vitesse **croît** avec la concentration en substrat (20 à 1 mmol/L, 60 à 5 mmol/L), puis se stabilise à **80** dès 20 mmol/L : c'est un **plateau de saturation**. Tous les **sites actifs** sont occupés : ajouter du substrat ne peut plus accélérer la réaction, la quantité d'enzyme étant constante.\n2. X a une forme proche du substrat : elle peut se fixer au **site actif** et l'**occuper à la place du substrat** (inhibiteur). À concentration égale, la vitesse est plus faible avec X (8 au lieu de 20 à 1 mmol/L ; 55 au lieu de 78 à 10 mmol/L). Quand le substrat devient très abondant, il occupe la plupart des sites actifs avant X : la vitesse se rapproche de celle sans inhibiteur (78 contre 80 à 40 mmol/L).\n3. Le **gène** de l'enzyme est muté : l'**enzyme** produite est **déficiente**. La réaction qu'elle catalyse ne se fait plus : la **dégradation** de la phénylalanine est **interrompue** et ce substrat, qui n'est plus transformé, **s'accumule**. Une seule enzyme bloque toute une voie métabolique.\n4. Le document 1 montre que l'activité dépend du **milieu** : concentration en substrat, présence d'un inhibiteur (comme la température et le pH). Le document 2 montre qu'elle dépend du **gène** qui code l'enzyme : c'est le **contrôle génétique du métabolisme**."}$exo$::jsonb),
  ('ece3f0db-2c41-50a7-912c-3cff320071de'::uuid, 1, 'application', $exo${"titre":"Continents et océans, deux croûtes","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Que montre la **courbe hypsométrique** du globe ? Donne les altitudes des deux maxima et ce à quoi ils correspondent.\n2. Recopie et complète :\n\n| Caractère | Croûte continentale | Croûte océanique |\n| Roches | … | … |\n| Densité | … | … |\n| Épaisseur | … | … |\n| Âge maximal | … | … |\n\n3. Qu'est-ce que l'**isostasie** ? Explique pourquoi les continents « flottent » plus haut que les fonds océaniques.","bareme":[{"critere":"Deux maxima : 0 à 1 000 m (continents) et −4 000 à −5 000 m (océans)","points":5},{"critere":"Tableau juste : granitique/basalte-gabbro, 2,7/2,9, 30 km/7 km, plus de 4 Ga/moins de 200 Ma","points":9},{"critere":"Isostasie définie et appliquée (léger et épais haut, dense et mince bas)","points":6}],"dureeMin":7,"corrige":"1. La courbe hypsométrique présente **deux maxima** : l'un entre **0 et 1 000 m** (les **continents**), l'autre entre **−4 000 et −5 000 m** (les **fonds océaniques**). Cette bimodalité indique deux croûtes de nature différente.\n2. Continentale : roches de type **granitique**, densité **environ 2,7**, épaisseur **30 km** (jusqu'à 70 km sous les chaînes), âge maximal **plus de 4 milliards d'années**. Océanique : **basaltes et gabbros**, densité **environ 2,9**, épaisseur **7 km**, âge maximal **moins de 200 millions d'années**.\n3. L'**isostasie** est l'équilibre des blocs crustaux qui **flottent sur le manteau ductile**, comme des icebergs sur l'eau. La croûte continentale, **légère et épaisse**, flotte **haut** ; la croûte océanique, **dense et mince**, flotte **bas** : d'où les deux niveaux d'altitude."}$exo$::jsonb),
  ('ece3f0db-2c41-50a7-912c-3cff320071de'::uuid, 2, 'application', $exo${"titre":"Trois échantillons et un pays qui remonte","consigne":"Exploite les données, justifie chaque identification et pose tes calculs.","enonce":"**Situation.** Nora a reçu trois échantillons avec leur fiche.\n\n| Échantillon | Lieu de prélèvement | Densité | Âge |\n| R1 | Forage dans un fond océanique | 2,9 | 80 millions d'années |\n| R2 | Affleurement au cœur d'un vieux continent | 2,7 | 2,5 milliards d'années |\n| R3 | Forage dans un fond océanique, sous R1 | 2,9 | 80 millions d'années |\n\nR1 est une roche volcanique, R2 une roche de type granitique, R3 une roche à gros cristaux riche en fer et magnésium.\n\n1. Rattache chaque échantillon à une croûte et nomme R1 et R3. Justifie avec au moins deux critères.\n2. Aucune roche de fond océanique n'a plus de 200 millions d'années, alors que R2 a 2,5 milliards d'années. Quelle conclusion le cours tire-t-il de ce contraste ?\n3. La Scandinavie s'élève encore de près de 1 cm par an. Calcule sa remontée en 5 000 ans, en mètres. Explique la cause de ce mouvement.","bareme":[{"critere":"R1 basalte et R3 gabbro (croûte océanique), R2 croûte continentale, avec deux critères","points":7},{"critere":"Croûte océanique renouvelée en permanence, croûte continentale conservée","points":5},{"critere":"5 000 cm = 50 m ; remontée isostatique après la fonte de la calotte","points":8}],"dureeMin":11,"corrige":"1. **R1** et **R3** viennent d'un fond océanique, ont une **densité de 2,9** et un âge de **80 millions d'années** (moins de 200 Ma) : ils appartiennent à la **croûte océanique**. R1, volcanique, est un **basalte** ; R3, sous R1, riche en fer et magnésium, est un **gabbro**. **R2** prélevé sur un continent, **granitique**, de densité **2,7**, âgé de **2,5 milliards d'années** : il appartient à la **croûte continentale**.\n2. Le contraste d'âge est décisif : la croûte océanique est **renouvelée en permanence** (elle ne dépasse pas 200 millions d'années), tandis que la croûte continentale est **conservée** (plus de 4 milliards d'années pour les plus vieilles roches).\n3. 1 cm/an × 5 000 ans = **5 000 cm = 50 m**. Pendant la dernière glaciation, une calotte glaciaire pesait sur la Scandinavie. Après sa fonte, le continent **allégé remonte** pour retrouver son **équilibre isostatique** sur le manteau ductile."}$exo$::jsonb),
  ('ece3f0db-2c41-50a7-912c-3cff320071de'::uuid, 3, 'application', $exo${"titre":"Pourquoi les montagnes tiennent debout","consigne":"Exploite les documents et construis une réponse argumentée qui mobilise l'ensemble du cours.","enonce":"**Document 1 — Épaisseur de la croûte mesurée par sondages sismiques.**\n\n| Lieu | Altitude moyenne | Épaisseur de la croûte |\n| Plaine continentale | 200 m | 30 km |\n| Chaîne de montagnes | 3 000 m | 55 km |\n| Plaine abyssale | −4 500 m | 7 km |\n\n**Document 2.** Des mesures de gravimétrie montrent que, sous la chaîne, les roches situées entre 30 et 55 km de profondeur sont moins denses que celles situées à la même profondeur sous la plaine.\n\n1. Compare l'épaisseur de la croûte sous la chaîne et sous la plaine continentale. Comment s'appelle la partie de croûte qui s'enfonce sous la chaîne ? Calcule son épaisseur supplémentaire.\n2. Explique, avec le modèle de l'isostasie, pourquoi la chaîne est à la fois haute et soutenue en profondeur. Utilise le document 2.\n3. Explique pourquoi la plaine abyssale est à −4 500 m, en citant deux caractères de la croûte océanique.\n4. Imagine que l'érosion enlève une partie du relief de la chaîne. Que deviendra la racine d'après le modèle isostatique ?\n5. Quelles méthodes de terrain permettent d'obtenir ces données ?","bareme":[{"critere":"55 − 30 = 25 km de racine crustale sous la chaîne","points":4},{"critere":"Racine de croûte légère qui flotte sur le manteau et soutient le relief, document 2 exploité","points":5},{"critere":"Croûte océanique mince (7 km) et dense (2,9) qui flotte bas","points":4},{"critere":"Allègement par érosion : le bloc remonte, la racine s'amincit","points":4},{"critere":"Forages, sondages sismiques, gravimétrie cités","points":3}],"dureeMin":18,"corrige":"1. La croûte est plus épaisse sous la chaîne (**55 km**) que sous la plaine (**30 km**) : elle s'enfonce de **55 − 30 = 25 km** supplémentaires. Cette partie est la **racine crustale**.\n2. Les blocs crustaux **flottent sur le manteau ductile**, comme des icebergs : un bloc plus épais émerge plus haut **et** plonge plus profond. La chaîne possède une racine de croûte **légère** (document 2 : roches moins denses que le manteau présent à la même profondeur sous la plaine) qui s'enfonce dans le manteau et **soutient le relief** par isostasie : c'est la racine qui explique l'altitude.\n3. La croûte océanique est **mince** (7 km) et **dense** (environ 2,9, contre 2,7 pour la croûte continentale) : ce bloc dense et mince **flotte bas**, d'où une altitude de −4 500 m.\n4. L'érosion **allège** le sommet : pour retrouver l'équilibre isostatique, le bloc **remonte** et la racine **s'amincit** progressivement, comme la Scandinavie remonte après la fonte de sa calotte.\n5. Les **forages** (roches, âges), les **sondages sismiques** (épaisseurs) et la **gravimétrie** (densités). C'est la convergence de ces mesures qui fonde le modèle."}$exo$::jsonb),
  ('7e85f55e-fcca-5ea8-a5da-b86d96f85d96'::uuid, 1, 'application', $exo${"titre":"Ondes P, ondes S et discontinuités","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Compare les ondes **P** et **S** : nature, vitesse, milieux traversés.\n2. De quoi dépend la vitesse d'une onde sismique ? Que signale une variation brutale de cette vitesse ?\n3. Recopie et complète :\n\n| Discontinuité | Profondeur | Ce qu'elle sépare |\n| Moho | … | … |\n| Gutenberg | … | … |\n| Lehmann | … | … |\n\n4. Quelle observation sismique montre que le noyau externe est liquide ?","bareme":[{"critere":"P : compression, la plus rapide, solides et liquides ; S : cisaillement, plus lente, solides seulement","points":6},{"critere":"Vitesse liée à la rigidité et à la densité ; variation brutale = discontinuité","points":4},{"critere":"Tableau juste (30 km/7 km croûte-manteau ; 2 900 km manteau-noyau externe ; 5 100 km noyau externe-graine)","points":6},{"critere":"Disparition des ondes S à 2 900 km","points":4}],"dureeMin":7,"corrige":"1. Les ondes **P** (primaires) sont des ondes de **compression**, les **plus rapides**, et traversent **solides et liquides**. Les ondes **S** (secondaires) sont des ondes de **cisaillement**, **plus lentes**, et ne traversent que les **solides**.\n2. La vitesse dépend de la **rigidité** et de la **densité** du milieu. Une variation brutale signale une **discontinuité** (changement de milieu).\n3. **Moho** : 30 km sous les continents, 7 km sous les océans, sépare la **croûte** et le **manteau**. **Gutenberg** : environ **2 900 km**, sépare le **manteau** et le **noyau externe**. **Lehmann** : environ **5 100 km**, sépare le **noyau externe** et la **graine**.\n4. À la discontinuité de Gutenberg, les **ondes S disparaissent** : or elles ne traversent pas les liquides, donc le noyau externe est **liquide**."}$exo$::jsonb),
  ('7e85f55e-fcca-5ea8-a5da-b86d96f85d96'::uuid, 2, 'application', $exo${"titre":"Deux sismogrammes, deux croûtes","consigne":"Exploite les données chiffrées, pose tes calculs et justifie tes conclusions.","enonce":"**Situation.** Après un séisme, Yanis reçoit les enregistrements d'une station située à **240 km** de l'épicentre. On admet que, dans la croûte, les ondes P vont à **6 km/s** et les ondes S à **4 km/s**, en trajet direct.\n\n1. Calcule la durée de trajet des ondes P, puis celle des ondes S. Quel est l'écart entre leurs arrivées ?\n2. Des sondages mesurent la vitesse des ondes P selon la profondeur en deux lieux :\n\n| Profondeur | Lieu X | Lieu Y |\n| 0 à 7 km | 6 km/s | 6 km/s |\n| 7 à 30 km | 8 km/s | 6 km/s |\n| Au-delà de 30 km | 8 km/s | 8 km/s |\n\nRepère la profondeur de la discontinuité en X et en Y. Nomme-la et indique ce qu'elle sépare.\n3. Déduis-en lequel des deux lieux est un océan et lequel est un continent. Justifie.","bareme":[{"critere":"P : 240 / 6 = 40 s ; S : 240 / 4 = 60 s ; écart 20 s","points":7},{"critere":"Discontinuité à 7 km en X et 30 km en Y, accélération des ondes, Moho entre croûte et manteau","points":7},{"critere":"X océan (croûte de 7 km), Y continent (croûte de 30 km), justifiés","points":6}],"dureeMin":11,"corrige":"1. Durée = distance / vitesse. Ondes P : 240 / 6 = **40 s**. Ondes S : 240 / 4 = **60 s**. Écart : 60 − 40 = **20 s** : les ondes P, plus rapides, arrivent en premier.\n2. En X, la vitesse passe brutalement de 6 à 8 km/s à **7 km** ; en Y, à **30 km**. Une accélération nette des ondes signale le **Moho**, discontinuité qui sépare la **croûte** et le **manteau**.\n3. En X, la croûte ne fait que 7 km d'épaisseur : c'est une croûte **océanique** (Moho à 7 km sous les océans). En Y, elle fait 30 km : c'est une croûte **continentale** (Moho à 30 km sous les continents)."}$exo$::jsonb),
  ('7e85f55e-fcca-5ea8-a5da-b86d96f85d96'::uuid, 3, 'application', $exo${"titre":"Le profil de vitesse du globe","consigne":"Exploite le profil de vitesse et rédige une interprétation argumentée qui mobilise tout le cours.","enonce":"**Document 1 — Vitesses moyennes des ondes selon la profondeur (sous un continent).**\n\n| Profondeur (km) | Onde P (km/s) | Onde S (km/s) |\n| 0 à 30 | 6,0 | 3,5 |\n| 30 à 100 | 8,1 | 4,6 |\n| 100 à 250 | 7,8 | 4,3 |\n| 250 à 2 900 | de 8,5 à 13,7 | de 4,7 à 7,3 |\n| 2 900 à 5 100 | de 8,0 à 10,3 | aucune |\n| 5 100 à 6 371 | 11,1 | 3,6 |\n\n**Document 2.** Au-delà d'environ 103° de l'épicentre, et jusqu'à environ 143°, les stations ne reçoivent pas d'ondes P directes.\n\n1. Repère sur le document 1 les trois discontinuités majeures. Nomme-les et justifie chaque repérage par la variation de vitesse observée.\n2. Quelle zone présente un **ralentissement** des ondes ? Nomme-la et explique ce qu'elle révèle sur l'état des roches.\n3. Explique le document 2 et pourquoi il a permis de découvrir le noyau liquide.\n4. Distingue le découpage **chimique** et le découpage **mécanique** du globe. Situe la limite lithosphère / asthénosphère sur le document 1, et explique quel découpage compte pour la tectonique.","bareme":[{"critere":"Moho à 30 km (accélération), Gutenberg à 2 900 km (S disparaissent), Lehmann à 5 100 km (S réapparaissent, graine solide)","points":6},{"critere":"LVZ entre 100 et 250 km : asthénosphère ductile, partiellement fondue","points":4},{"critere":"Zone d'ombre : réfraction des P à l'entrée du noyau et extinction des S","points":4},{"critere":"Chimique (composition) / mécanique (comportement), limite vers 100 km, plaques lithosphériques","points":4},{"critere":"Valeurs du document citées à l'appui","points":2}],"dureeMin":19,"corrige":"1. **Moho** vers **30 km** : les ondes **accélèrent** nettement (P de 6,0 à 8,1 km/s) : passage de la croûte au **manteau**. **Gutenberg** vers **2 900 km** : les ondes **S disparaissent** et les P ralentissent (de 13,7 à 8,0 km/s) : passage au **noyau externe liquide**. **Lehmann** vers **5 100 km** : les P accélèrent et des ondes S existent à nouveau (3,6 km/s) : la **graine** est **solide**.\n2. Entre **100 et 250 km**, les vitesses **diminuent** (P de 8,1 à 7,8, S de 4,6 à 4,3 km/s) : c'est la **LVZ** (*low velocity zone*). Elle correspond à l'**asthénosphère**, **ductile**, partiellement fondue.\n3. Entre 103° et 143°, c'est la **zone d'ombre** : les ondes P sont **réfractées** (déviées) à l'entrée du noyau et les ondes S s'y **éteignent**. Cette zone ne s'explique que par un noyau dont les propriétés changent brutalement et qui arrête les ondes S : c'est elle qui a révélé le **noyau liquide**.\n4. Le découpage **chimique** (croûte / manteau / noyau) repose sur la **composition**. Le découpage **mécanique** repose sur le **comportement** : **lithosphère** rigide (croûte + sommet du manteau) sur **asthénosphère** ductile. Sur le document, la limite se place vers **100 km**, au début du ralentissement. C'est le découpage **mécanique** qui compte pour la tectonique : ce sont des **plaques lithosphériques** qui se déplacent sur l'asthénosphère."}$exo$::jsonb),
  ('f7e71d0d-eaf2-52c3-992e-f14727b42c4c'::uuid, 1, 'application', $exo${"titre":"La chaleur de la Terre","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Quelles sont les deux sources de la chaleur interne de la Terre ? Laquelle domine ? Cite deux éléments radioactifs concernés.\n2. Compare la **conduction** et la **convection** : principe, lieu où chacune domine, efficacité.\n3. Le manteau est solide : comment peut-il être animé de mouvements de convection ?\n4. Définis le **flux géothermique** et indique où il est le plus élevé.","bareme":[{"critere":"Radioactivité (environ 80 %, uranium, thorium, potassium 40) et chaleur résiduelle","points":5},{"critere":"Conduction (sans déplacement de matière, lithosphère, faible) / convection (avec déplacement de matière, manteau, élevée)","points":7},{"critere":"Manteau solide ductile qui flue lentement","points":4},{"critere":"Puissance évacuée par unité de surface, maximale aux dorsales","points":4}],"dureeMin":7,"corrige":"1. La **radioactivité naturelle** des roches (**uranium, thorium, potassium 40**) fournit environ **80 %** de la chaleur ; le reste est la **chaleur résiduelle** de l'accrétion et de la différenciation du noyau.\n2. **Conduction** : la chaleur se transmet **de proche en proche, sans déplacement de matière** ; elle domine dans la **lithosphère** rigide ; elle est **peu efficace** (la roche conduit mal la chaleur). **Convection** : la chaleur est transportée **par déplacement de matière** (le chaud monte, le froid redescend) ; elle domine dans le **manteau ductile** et évacue **l'essentiel** de la chaleur.\n3. Le manteau est **solide** mais **ductile** : à ces températures et sur des millions d'années, il **flue** et se déforme lentement, à quelques centimètres par an.\n4. Le flux géothermique est la **puissance thermique évacuée par unité de surface**. Il est le plus élevé au niveau des **dorsales océaniques**, où du matériel chaud remonte."}$exo$::jsonb),
  ('f7e71d0d-eaf2-52c3-992e-f14727b42c4c'::uuid, 2, 'application', $exo${"titre":"Une carte de flux géothermique","consigne":"Exploite les données, pose tes calculs et explique chaque différence avec le cours.","enonce":"**Situation.** Élise relève sur une carte trois valeurs de flux géothermique.\n\n| Lieu | Flux géothermique (mW/m²) |\n| Axe d'une dorsale océanique | 250 |\n| Plancher océanique âgé de 150 millions d'années | 50 |\n| Vieux bouclier continental | 40 |\n\n1. Calcule, pour une surface de 1 km² (1 000 000 m²), la puissance thermique évacuée à l'axe de la dorsale puis sur le bouclier. Exprime-les en kilowatts (1 mW = 0,001 W ; 1 kW = 1 000 W).\n2. Combien de fois le flux de la dorsale est-il plus élevé que celui du bouclier ?\n3. Explique pourquoi le flux est élevé à la dorsale et faible sur le plancher âgé et sur le bouclier.\n4. Le cours affirme que la carte du flux « dessine à elle seule les frontières de plaques ». Explique pourquoi.","bareme":[{"critere":"Dorsale : 0,25 W/m² × 1 000 000 = 250 000 W = 250 kW ; bouclier : 40 kW","points":6},{"critere":"Rapport 250 / 40 = 6,25","points":3},{"critere":"Remontée de matériel chaud à la dorsale ; lithosphère refroidie et épaissie ailleurs","points":7},{"critere":"Flux élevé aux frontières divergentes, donc lien avec les limites de plaques","points":4}],"dureeMin":11,"corrige":"1. Dorsale : 250 mW/m² = **0,25 W/m²** ; 0,25 × 1 000 000 = **250 000 W = 250 kW**. Bouclier : 40 mW/m² = 0,04 W/m² ; 0,04 × 1 000 000 = **40 000 W = 40 kW**.\n2. 250 / 40 = **6,25** : le flux de la dorsale est environ **6 fois** plus élevé.\n3. À la **dorsale**, du **matériel chaud remonte** du manteau (branche montante de la convection) : la chaleur est évacuée en abondance. Le **plancher océanique âgé** et le **vieux bouclier** correspondent à une lithosphère **refroidie et épaissie** : la chaleur n'y traverse que par **conduction**, peu efficace, d'où un flux faible.\n4. Les zones de flux élevé soulignent les **dorsales**, c'est-à-dire des **frontières de plaques** où la matière chaude remonte ; les intérieurs de plaques anciens ont un flux faible. La répartition du flux suit donc le découpage en plaques."}$exo$::jsonb),
  ('f7e71d0d-eaf2-52c3-992e-f14727b42c4c'::uuid, 3, 'application', $exo${"titre":"Quand la lithosphère devient assez lourde pour plonger","consigne":"Exploite les documents et rédige une explication argumentée qui relie transferts thermiques et tectonique.","enonce":"**Document 1 — Lithosphère océanique selon son âge.**\n\n| Âge (millions d'années) | 10 | 30 | 60 | 100 |\n| Épaisseur (km) | 30 | 55 | 75 | 95 |\n| Densité moyenne | 3,22 | 3,24 | 3,26 | 3,28 |\n\nDensité de l'asthénosphère sous-jacente : **3,25**.\n\n**Document 2.** Dans le manteau, la matière chaude remonte sous les dorsales et la matière plus froide redescend, à quelques centimètres par an. Au niveau des fosses, la lithosphère plonge et tire sur le reste de la plaque.\n\n1. Décris l'évolution de la lithosphère océanique avec l'âge et explique-la par un mode de transfert thermique.\n2. À partir de quel âge la lithosphère devient-elle plus dense que l'asthénosphère ? Qu'est-ce que cela rend possible ?\n3. Identifie dans le document 2 les deux moteurs du déplacement des plaques.\n4. Rédige un court paragraphe reliant l'origine de la chaleur interne, les deux modes de transfert et le mouvement des plaques.","bareme":[{"critere":"Lithosphère qui s'épaissit et se densifie en vieillissant, par refroidissement (conduction)","points":5},{"critere":"Densité supérieure à 3,25 entre 30 et 60 Ma : plongée (subduction) possible","points":5},{"critere":"Convection mantellique et traction de la plaque plongeante","points":4},{"critere":"Paragraphe : radioactivité, conduction dans la lithosphère, convection dans le manteau, plaques","points":4},{"critere":"Valeurs du document citées","points":2}],"dureeMin":18,"corrige":"1. En vieillissant, la lithosphère océanique s'**épaissit** (de 30 km à 10 Ma à 95 km à 100 Ma) et devient **plus dense** (de 3,22 à 3,28). En s'éloignant de la dorsale, elle perd sa chaleur vers la surface par **conduction** : elle **se refroidit**, s'épaissit et gagne en densité.\n2. Sa densité (3,24 à 30 Ma, 3,26 à 60 Ma) **dépasse celle de l'asthénosphère (3,25)** entre **30 et 60 millions d'années**. Plus dense que le milieu sur lequel elle repose, elle devient instable : sa **plongée** (subduction) devient possible.\n3. Premier moteur : la **convection mantellique** (le chaud monte sous les dorsales, le froid redescend). Second moteur : la **traction de la plaque plongeante** au niveau des fosses (subduction), dont la contribution est aujourd'hui estimée importante.\n4. La Terre produit de la chaleur surtout par la **radioactivité naturelle** de ses roches (environ 80 %). Cette chaleur est évacuée par **convection** dans le manteau ductile, qui flue lentement, et par **conduction** dans la lithosphère rigide. La convection entraîne les plaques et fait remonter du matériel chaud aux dorsales ; en refroidissant, la lithosphère océanique devient assez dense pour plonger, et sa plongée tire à son tour la plaque."}$exo$::jsonb),
  ('00b37453-9a08-5b3d-885f-d374602e0c79'::uuid, 1, 'application', $exo${"titre":"De la dérive des continents aux plaques","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Cite les quatre séries d'arguments avancées par Wegener en 1912.\n2. Pourquoi son hypothèse a-t-elle été rejetée ?\n3. Associe chaque preuve à ce qu'elle établit : expansion des fonds océaniques (Hess, 1962), anomalies magnétiques (Vine et Matthews, 1963), forages océaniques.\n4. Comment mesure-t-on aujourd'hui directement le déplacement des plaques ? Quel ordre de grandeur obtient-on ?","bareme":[{"critere":"Tracé des côtes, structures géologiques, fossiles, glaciation du Carbonifère","points":6},{"critere":"Rejet faute de mécanisme","points":3},{"critere":"Trois preuves associées à ce qu'elles établissent","points":7},{"critere":"GPS, quelques centimètres par an","points":4}],"dureeMin":7,"corrige":"1. Le **tracé des côtes** (elles s'emboîtent de part et d'autre de l'Atlantique), les **structures géologiques** qui se prolongent d'un continent à l'autre, les **fossiles** (*Mesosaurus*, *Glossopteris*) sur des continents séparés, les traces communes de la **glaciation du Carbonifère**.\n2. Elle a été rejetée **faute de mécanisme** : on ne voyait pas comment un continent pourrait labourer un plancher océanique rigide.\n3. **Hess (1962)** : la croûte océanique se **crée à la dorsale** et disparaît dans les fosses. **Vine et Matthews (1963)** : des bandes d'anomalies magnétiques **symétriques** de part et d'autre de la dorsale enregistrent les inversions du champ magnétique. **Forages** : l'**âge des sédiments basaux croît avec la distance à la dorsale**.\n4. Par **GPS**, depuis les années 1990 : les plaques se déplacent de **quelques centimètres par an**, en accord avec les vitesses déduites des anomalies magnétiques."}$exo$::jsonb),
  ('00b37453-9a08-5b3d-885f-d374602e0c79'::uuid, 2, 'application', $exo${"titre":"Mesurer la vitesse d'une plaque de trois façons","consigne":"Pose chaque calcul avec ses unités (1 km = 100 000 cm) et conclus.","enonce":"**Situation.** Paul compare trois méthodes pour mesurer la vitesse d'une même plaque.\n\n**Méthode 1 — Anomalies magnétiques.** Une bande d'anomalie magnétique âgée de **5 millions d'années** se trouve à **250 km** de l'axe de la dorsale.\n\n**Méthode 2 — Point chaud.** Une île volcanique formée au-dessus d'un point chaud fixe se trouve aujourd'hui à **480 km** du point chaud ; son volcan date de **6 millions d'années**.\n\n**Méthode 3 — GPS.** Une station GPS posée sur la plaque s'est déplacée de **48 cm en 6 ans**.\n\n1. Calcule la vitesse de la plaque en cm/an pour chacune des trois méthodes.\n2. Les trois résultats sont-ils du même ordre de grandeur ? Qu'en conclut-on sur la fiabilité du modèle ?\n3. De l'autre côté de la dorsale, on retrouve la même bande d'anomalie à 250 km de l'axe. Quelle propriété des anomalies est ainsi vérifiée, et que montre-t-elle ?","bareme":[{"critere":"Méthode 1 : 25 000 000 cm / 5 000 000 ans = 5 cm/an","points":5},{"critere":"Méthode 2 : 48 000 000 cm / 6 000 000 ans = 8 cm/an","points":5},{"critere":"Méthode 3 : 48 / 6 = 8 cm/an","points":3},{"critere":"Même ordre de grandeur (quelques cm/an), méthodes cohérentes","points":3},{"critere":"Symétrie par rapport à la dorsale : croûte créée à l'axe puis écartée des deux côtés","points":4}],"dureeMin":12,"corrige":"1. **Méthode 1** : 250 km = 25 000 000 cm ; 25 000 000 / 5 000 000 = **5 cm/an**. **Méthode 2** : 480 km = 48 000 000 cm ; 48 000 000 / 6 000 000 = **8 cm/an** (le point chaud est fixe : c'est la plaque qui a emporté l'île). **Méthode 3** : 48 / 6 = **8 cm/an**.\n2. Les trois vitesses sont du **même ordre de grandeur : quelques centimètres par an**. Des méthodes indépendantes (paléomagnétisme, volcans de point chaud, mesure directe) donnent des résultats cohérents : le déplacement des plaques est établi, la discussion est close.\n3. Les bandes d'anomalies sont **symétriques** de part et d'autre de la dorsale. La croûte se **forme à l'axe** de la dorsale, enregistre le champ magnétique de son époque, puis est **écartée** des deux côtés : c'est l'**expansion des fonds océaniques**."}$exo$::jsonb),
  ('00b37453-9a08-5b3d-885f-d374602e0c79'::uuid, 3, 'application', $exo${"titre":"Un demi-siècle pour convaincre","consigne":"Exploite les documents et rédige une argumentation structurée, en t'appuyant sur des données chiffrées.","enonce":"**Document 1 — L'objection faite à Wegener.**\n> « Aucune force connue ne peut pousser un continent à travers un plancher océanique solide. »\n\n**Document 2 — Forages dans un océan, âge des sédiments les plus profonds.**\n\n| Distance à l'axe de la dorsale (km) | 200 | 600 | 1 200 |\n| Âge des sédiments basaux (millions d'années) | 10 | 30 | 60 |\n\nLes forages réalisés de l'autre côté de l'axe donnent les mêmes âges aux mêmes distances.\n\n**Document 3.** Les séismes et les volcans du globe se répartissent surtout le long d'étroites bandes qui ne suivent pas les côtes des continents.\n\n1. Montre que l'objection du document 1 porte sur l'absence de mécanisme, et non sur les observations de Wegener.\n2. Exploite le document 2 : décris la relation entre la distance et l'âge, calcule la vitesse d'écartement d'un côté de la dorsale en cm/an, puis explique comment ces résultats répondent à l'objection.\n3. Que montre le document 3 sur ce qu'est une plaque ?\n4. Conclus : pourquoi parle-t-on aujourd'hui de tectonique des plaques **lithosphériques** et non plus de dérive des continents ?","bareme":[{"critere":"Objection sur le mécanisme, alors que les arguments de Wegener (côtes, fossiles…) restaient valables","points":4},{"critere":"Âge proportionnel à la distance, 1 200 km / 60 Ma = 2 cm/an, symétrie","points":6},{"critere":"Plancher créé à la dorsale et entraîné avec le continent : le continent ne laboure pas l'océan","points":4},{"critere":"Plaques délimitées par la sismicité et le volcanisme, pas par les côtes","points":3},{"critere":"Conclusion : c'est la lithosphère, océan et continent ensemble, qui se déplace","points":3}],"dureeMin":18,"corrige":"1. Le document 1 ne conteste pas les **observations** de Wegener (côtes qui s'emboîtent, structures géologiques prolongées, fossiles et traces de glaciation communes) : il dit seulement qu'aucune **force** ne permettrait le déplacement. L'hypothèse est rejetée **faute de mécanisme**.\n2. L'âge des sédiments basaux **augmente proportionnellement** à la distance à l'axe (10 Ma à 200 km, 30 Ma à 600 km, 60 Ma à 1 200 km), et de façon **symétrique** des deux côtés. Vitesse : 1 200 km = 120 000 000 cm ; 120 000 000 / 60 000 000 = **2 cm/an** (même résultat avec 200 km / 10 Ma et 600 km / 30 Ma). Le plancher océanique est donc **créé à la dorsale** puis s'en éloigne : c'est l'**expansion des fonds océaniques** (Hess). Le continent ne laboure pas le plancher : il est **entraîné avec lui**, ce qui lève l'objection.\n3. Séismes et volcans soulignent les **frontières de plaques**, qui ne coïncident pas avec les côtes : une plaque peut porter à la fois un continent et un océan. La carte de la **sismicité** et du **volcanisme** dessine les plaques bien mieux que celle des continents.\n4. Ce ne sont pas les continents seuls qui dérivent, mais des **plaques lithosphériques** rigides (croûte océanique ou continentale + sommet du manteau), qui se créent aux dorsales, se déplacent de quelques centimètres par an (mesure confirmée par GPS) et dont les limites sont actives. La tectonique des plaques fournit le mécanisme qui manquait à Wegener."}$exo$::jsonb),
  ('1feef3e8-659c-578f-b480-22aa8b09f42c'::uuid, 1, 'application', $exo${"titre":"Ce qui se passe sous une dorsale","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Explique comment se forme le magma sous une dorsale. Quelle roche du manteau fond ? Faut-il un apport de chaleur ?\n2. Le même magma donne deux roches. Nomme-les et compare leur lieu de formation, leur refroidissement et leur structure.\n3. Cite trois indices de surface qui caractérisent une dorsale.","bareme":[{"critere":"Fusion partielle de la péridotite par décompression, sans apport de chaleur","points":7},{"critere":"Gabbro (profondeur, lent, grenu) et basalte (surface, brutal, microlitique, pillow lavas)","points":8},{"critere":"Trois indices justes (sismicité superficielle, failles normales, flux élevé, fumeurs noirs)","points":5}],"dureeMin":7,"corrige":"1. L'écartement des plaques fait **remonter** le manteau, qui subit une **décompression**. Cette seule **baisse de pression**, **sans apport de chaleur**, suffit à faire fondre **partiellement** la **péridotite** : c'est la **fusion partielle par décompression adiabatique**.\n2. Le **gabbro** se forme **en profondeur**, par un refroidissement **lent** : la cristallisation est entière, la structure est **grenue**. Le **basalte** se forme **en surface**, par un refroidissement **brutal** au contact de l'eau de mer : structure **microlitique**, en coussins (*pillow lavas*). C'est la **vitesse de refroidissement** qui fait la différence.\n3. Une **sismicité superficielle** et de faible magnitude ; des **failles normales** (extension) ; un **flux géothermique** très élevé ; des **sources hydrothermales** (fumeurs noirs)."}$exo$::jsonb),
  ('1feef3e8-659c-578f-b480-22aa8b09f42c'::uuid, 2, 'application', $exo${"titre":"Deux dorsales, deux rythmes","consigne":"Identifie, calcule et justifie chaque réponse avec le cours.","enonce":"**Situation.** Un navire océanographique étudie deux dorsales.\n\n| | Dorsale A | Dorsale B |\n| Vitesse d'écartement (total des deux plaques) | 12 cm/an | 2,5 cm/an |\n| Profil de l'axe | Bombé, sans vallée marquée | Vallée axiale profonde, reliefs escarpés |\n\nSur la dorsale B, un forage remonte deux roches : la roche R1, à structure microlitique, en forme de coussins, prélevée en surface ; la roche R2, entièrement cristallisée en gros cristaux, prélevée plus bas.\n\n1. Laquelle des deux dorsales est rapide, laquelle est lente ? Comment s'appelle la vallée axiale de la dorsale B ?\n2. Nomme R1 et R2 et explique pourquoi elles diffèrent alors qu'elles viennent du même magma.\n3. Calcule le temps nécessaire pour créer **100 km** d'océan à chacune des deux dorsales (1 km = 100 000 cm). Exprime les résultats en années.","bareme":[{"critere":"A rapide, B lente, rift axial","points":5},{"critere":"R1 basalte, R2 gabbro, différence expliquée par la vitesse de refroidissement","points":7},{"critere":"B : 10 000 000 / 2,5 = 4 000 000 ans ; A : 10 000 000 / 12 ≈ 833 000 ans","points":8}],"dureeMin":12,"corrige":"1. La dorsale **A** (12 cm/an, profil bombé, sans rift marqué) est **rapide**, comme la dorsale du Pacifique est. La dorsale **B** (2,5 cm/an, vallée profonde, reliefs escarpés) est **lente**, comme la dorsale atlantique. Sa vallée axiale est un **rift**.\n2. **R1** est un **basalte** : refroidi **brutalement** en surface au contact de l'eau de mer, structure **microlitique**, en coussins (*pillow lavas*). **R2** est un **gabbro** : refroidi **lentement** en profondeur, cristallisation entière, structure **grenue**. Les deux proviennent du même **magma basaltique** : seule la **vitesse de refroidissement** diffère.\n3. 100 km = 10 000 000 cm. Dorsale **B** : 10 000 000 / 2,5 = **4 000 000 ans** (4 millions d'années). Dorsale **A** : 10 000 000 / 12 ≈ **833 000 ans**. La dorsale rapide crée la même largeur d'océan environ cinq fois plus vite."}$exo$::jsonb),
  ('1feef3e8-659c-578f-b480-22aa8b09f42c'::uuid, 3, 'application', $exo${"titre":"Prouver qu'une dorsale est une zone de divergence","consigne":"Exploite les documents, puis rédige une argumentation structurée qui mobilise l'ensemble du cours.","enonce":"**Document 1.** Au niveau de l'axe d'une dorsale, les séismes se produisent à moins de 10 km de profondeur et sont de faible magnitude. Les failles observées sont des failles normales.\n\n**Document 2.** Le flux géothermique y dépasse 200 mW/m², contre environ 50 mW/m² sur un plancher océanique ancien.\n\n**Document 3.** Des plongées révèlent des cheminées d'où jaillit une eau noire à plus de 300 °C, chargée de métaux, entourée d'animaux (vers, crevettes) vivant dans l'obscurité totale.\n\n**Document 4.** Sous l'axe, le manteau remonte ; la température n'y est pas plus élevée qu'à la même profondeur ailleurs, mais la péridotite y fond partiellement.\n\n1. Montre que les documents 1 et 2 indiquent une zone d'extension où du matériel chaud remonte.\n2. Explique l'origine de l'eau décrite dans le document 3 et la particularité de l'écosystème qui l'entoure.\n3. Le document 4 semble paradoxal : le manteau fond sans être plus chaud. Résous ce paradoxe.\n4. Explique ce que devient la lithosphère océanique formée à l'axe à mesure qu'elle s'en éloigne, et pourquoi c'est important pour la suite de son histoire.","bareme":[{"critere":"Failles normales et sismicité superficielle = extension ; flux élevé = remontée de matériel chaud","points":5},{"critere":"Circulation hydrothermale : eau de mer dans la croûte fissurée, enrichie en métaux ; écosystème indépendant de la lumière","points":4},{"critere":"Fusion partielle par décompression adiabatique de la péridotite","points":5},{"critere":"Refroidissement, épaississement par la base, densité croissante : devient subductible","points":4},{"critere":"Argumentation appuyée sur les données des documents","points":2}],"dureeMin":18,"corrige":"1. Les **failles normales** sont la signature d'une **extension** : les deux plaques **s'écartent**. La **sismicité superficielle** (moins de 10 km) et de **faible magnitude** caractérise les dorsales. Le **flux géothermique** très élevé (plus de 200 mW/m², quatre fois celui d'un plancher ancien) montre que du **matériel chaud remonte** sous l'axe. La dorsale est donc une **zone de divergence**.\n2. L'**eau de mer** s'infiltre dans la croûte **fissurée**, circule près du magma, s'**enrichit en métaux** et ressort à plus de 300 °C : ce sont des **sources hydrothermales**, les **fumeurs noirs**. Les animaux qui les entourent forment un écosystème **indépendant de la lumière**.\n3. Le manteau qui remonte subit une **baisse de pression** (décompression) : sans apport de chaleur, cette seule baisse de pression suffit à faire fondre **partiellement la péridotite**. C'est la **fusion partielle par décompression adiabatique** ; elle produit le magma basaltique qui donnera basaltes et gabbros.\n4. En s'éloignant de l'axe, la lithosphère océanique **se refroidit**, **s'épaissit** par accrétion du manteau à sa base et **gagne en densité**. À terme, elle devient **subductible** : la croûte née à la dorsale disparaîtra un jour dans une zone de subduction."}$exo$::jsonb),
  ('a0bd4fbd-b592-586c-a3c3-036e8d0d2db5'::uuid, 1, 'application', $exo${"titre":"Quand une plaque plonge","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Pourquoi une lithosphère océanique âgée finit-elle par plonger ? Pourquoi la lithosphère continentale ne subduit-elle pas ?\n2. Cite trois marqueurs de surface d'une zone de subduction et décris-les.\n3. Qu'est-ce que le **plan de Wadati-Benioff** et que prouve-t-il ?\n4. Le magma des zones de subduction provient-il de la fusion de la plaque plongeante ? Explique d'où il vient en quelques phrases.","bareme":[{"critere":"Lithosphère refroidie et épaissie plus dense que l'asthénosphère ; continent trop peu dense","points":5},{"critere":"Trois marqueurs décrits (fosse, prisme d'accrétion, anomalie thermique négative, arc volcanique)","points":5},{"critere":"Plan incliné des foyers sismiques jusqu'à 700 km : preuve de la plongée","points":4},{"critere":"Non : eau libérée par la plaque qui abaisse la température de fusion du manteau sus-jacent","points":6}],"dureeMin":8,"corrige":"1. En vieillissant, la lithosphère océanique **se refroidit et s'épaissit** : sa densité moyenne finit par **dépasser celle de l'asthénosphère**. Instable, elle plonge. La lithosphère continentale, **trop peu dense**, ne subduit pas : les continents sont conservés.\n2. Exemples : la **fosse océanique** (celle des Mariannes approche 11 000 m) ; le **prisme d'accrétion** (sédiments raclés sur la plaque plongeante) ; l'**anomalie thermique négative** (la plaque plongeante est froide) ; l'**arc volcanique**, insulaire ou continental.\n3. C'est le **plan incliné** sur lequel se répartissent les **foyers sismiques**, de la surface jusqu'à environ **700 km**. Il matérialise la plaque plongeante : c'est la **preuve directe** de la plongée.\n4. **Non**. La croûte océanique hydratée s'enfonce ; des **transformations métamorphiques** libèrent son **eau** ; cette eau monte dans le **manteau sus-jacent** et **abaisse sa température de fusion** : c'est la **fusion partielle par hydratation** du manteau."}$exo$::jsonb),
  ('a0bd4fbd-b592-586c-a3c3-036e8d0d2db5'::uuid, 2, 'application', $exo${"titre":"Le plan des séismes sous un arc","consigne":"Exploite le tableau, pose tes calculs et justifie avec le cours.","enonce":"**Situation.** Sous une marge active, Clara relève la profondeur moyenne des foyers sismiques en fonction de la distance à la fosse, mesurée vers l'intérieur des terres.\n\n| Distance à la fosse (km) | 0 | 50 | 100 | 150 | 200 | 300 | 400 |\n| Profondeur des foyers (km) | 10 | 40 | 70 | 100 | 130 | 190 | 250 |\n\n1. Décris la répartition des foyers. Comment s'appelle ce plan et que matérialise-t-il ?\n2. On constate que la profondeur augmente toujours de la même quantité quand on s'éloigne de 50 km. De combien ? Déduis-en à quelle distance de la fosse le plan atteint 150 km de profondeur.\n3. Les volcans de l'arc se situent au-dessus du plan lorsqu'il est à une profondeur de 100 à 150 km. Entre quelles distances de la fosse se trouvent-ils ?\n4. Ces volcans émettent des andésites, et l'on trouve des granodiorites en profondeur. Explique la différence entre ces deux roches et pourquoi les éruptions y sont explosives.","bareme":[{"critere":"Foyers de plus en plus profonds en s'éloignant de la fosse : plan de Wadati-Benioff, plaque plongeante","points":5},{"critere":"30 km de profondeur en plus par 50 km ; 150 km atteints à environ 233 km de la fosse","points":5},{"critere":"Arc volcanique entre 150 et environ 233 km de la fosse","points":4},{"critere":"Andésite en surface, granodiorite en profondeur ; magma visqueux riche en gaz d'où l'explosivité","points":6}],"dureeMin":12,"corrige":"1. Les foyers sont de plus en plus **profonds** quand on s'éloigne de la fosse (10 km à la fosse, 250 km à 400 km de distance) : ils se répartissent sur un **plan incliné**, le **plan de Wadati-Benioff**, qui matérialise la **plaque plongeante**.\n2. Tous les 50 km, la profondeur augmente de **30 km** (10 → 40 → 70 → 100 → 130), soit 0,6 km de profondeur par km de distance. Pour passer de 100 km (à 150 km de la fosse) à 150 km de profondeur, il faut 50 km de profondeur en plus : 50 / 0,6 ≈ 83 km de distance. Le plan atteint 150 km de profondeur à environ 150 + 83 = **233 km** de la fosse.\n3. Le plan est à 100 km de profondeur à **150 km** de la fosse et à 150 km de profondeur vers **233 km** : l'arc volcanique se trouve **entre 150 et environ 233 km** de la fosse.\n4. Les deux roches viennent du même type de magma : l'**andésite** a refroidi **en surface**, la **granodiorite** **en profondeur**. Ce magma, riche en **silice** et en **eau**, est **visqueux** : il piège les gaz, qui sont libérés brutalement → volcanisme **explosif** (nuées ardentes, dômes, panaches)."}$exo$::jsonb),
  ('a0bd4fbd-b592-586c-a3c3-036e8d0d2db5'::uuid, 3, 'application', $exo${"titre":"L'eau, clé du magmatisme de subduction","consigne":"Exploite les documents et construis une explication argumentée, étape par étape.","enonce":"**Document 1.** Des roches de la croûte océanique prélevées à différentes profondeurs de la plaque plongeante montrent que leurs minéraux contenant de l'eau deviennent de plus en plus rares avec la profondeur : leur eau a été libérée.\n\n**Document 2 — Conditions vers 100 km de profondeur (valeurs simplifiées).**\n\n| Roche | Température réelle | Température à laquelle elle commence à fondre |\n| Péridotite du manteau sus-jacent, sans eau | 1 200 °C | 1 500 °C |\n| Péridotite du manteau sus-jacent, hydratée | 1 200 °C | 1 000 °C |\n| Croûte de la plaque plongeante | 600 °C | 700 °C |\n\n**Document 3.** Le flux géothermique mesuré au niveau de la fosse est plus faible que la moyenne.\n\n1. D'après le document 2, laquelle des trois roches peut fondre ? Justifie pour chacune.\n2. Relie les documents 1 et 2 pour expliquer, en quatre étapes, l'origine du magma de subduction.\n3. Explique le document 3 et montre qu'il confirme que la plaque plongeante ne peut pas fondre.\n4. Le cours affirme que la subduction est le principal lieu de production de croûte continentale. Justifie à partir de la nature des roches formées.","bareme":[{"critere":"Seule la péridotite hydratée fond (1 200 > 1 000 °C) ; péridotite sèche et plaque restent solides","points":5},{"critere":"Quatre étapes : plaque hydratée, métamorphisme qui libère l'eau, eau dans le manteau, fusion partielle par hydratation","points":6},{"critere":"Anomalie thermique négative : plaque froide","points":3},{"critere":"Granodiorites, andésites, rhyolites, riches en silice : matériau continental","points":4},{"critere":"Valeurs du document utilisées","points":2}],"dureeMin":18,"corrige":"1. **Péridotite sèche** : 1 200 °C < 1 500 °C → elle **ne fond pas**. **Péridotite hydratée** : 1 200 °C > 1 000 °C → elle **fond partiellement**. **Croûte de la plaque** : 600 °C < 700 °C → elle **ne fond pas**. Seule la péridotite hydratée du manteau sus-jacent peut fondre.\n2. (1) La **croûte océanique hydratée** s'enfonce avec la plaque. (2) Des **transformations métamorphiques** libèrent son **eau** (document 1 : les minéraux hydratés disparaissent avec la profondeur). (3) Cette eau **monte dans le manteau sus-jacent**. (4) Elle **abaisse sa température de fusion** (de 1 500 à 1 000 °C) : la péridotite fond partiellement, c'est la **fusion partielle par hydratation**. Le magma ne vient donc **pas** de la fusion de la plaque plongeante.\n3. Le flux faible traduit une **anomalie thermique négative** : la plaque plongeante est **froide**. Cela confirme le document 2 : à 600 °C, elle reste en dessous de sa température de fusion.\n4. Le magma formé, riche en **silice** et en eau, donne des **granodiorites** en profondeur et des **andésites** et **rhyolites** en surface. Ces roches riches en silice constituent du **matériau continental neuf** : la subduction est le principal mécanisme de **production de croûte continentale**."}$exo$::jsonb),
  ('d62a9762-feb6-5e49-b763-d9bb543c8f93'::uuid, 1, 'application', $exo${"titre":"Les marques d'une collision","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Pourquoi deux continents qui se rencontrent entrent-ils en collision au lieu que l'un plonge sous l'autre ?\n2. Cite trois marqueurs tectoniques d'une collision et ce que chacun montre.\n3. Que sont les **ophiolites** et que prouvent-elles ?\n4. Remets dans l'ordre les cinq étapes du cycle de Wilson : collision, érosion, ouverture d'un rift, subduction, océanisation.","bareme":[{"critere":"Croûte continentale trop peu dense pour plonger : elle s'épaissit","points":4},{"critere":"Trois marqueurs justes (plis, failles inverses et chevauchements, nappes de charriage, racine crustale)","points":6},{"critere":"Ophiolites : fragments de lithosphère océanique charriés, preuve d'un océan disparu","points":5},{"critere":"Ordre : rift, océanisation, subduction, collision, érosion","points":5}],"dureeMin":7,"corrige":"1. Quand la lithosphère océanique qui les séparait a été entièrement subduite, les deux continents se rencontrent. La lithosphère continentale est **trop peu dense** pour plonger : **aucun ne peut subduire**, et la croûte **s'épaissit**.\n2. Les **plis** montrent un **raccourcissement** ; les **failles inverses** et **chevauchements** montrent l'**empilement** des unités ; les **nappes de charriage** sont des terrains **déplacés sur des dizaines de kilomètres** ; la **racine crustale** (jusqu'à 70 km) soutient le relief par isostasie.\n3. Les ophiolites sont des fragments de **lithosphère océanique** — péridotites, gabbros, basaltes — **charriés en altitude** dans la chaîne. Elles prouvent qu'**un océan existait là** avant la collision.\n4. **Ouverture d'un rift → océanisation → subduction → collision → érosion**."}$exo$::jsonb),
  ('d62a9762-feb6-5e49-b763-d9bb543c8f93'::uuid, 2, 'application', $exo${"titre":"Carnet de terrain dans une chaîne de montagnes","consigne":"Classe les observations, pose ton calcul et justifie chaque réponse avec le cours.","enonce":"**Situation.** Pendant un stage de terrain, Mathis note cinq observations dans une chaîne de montagnes.\n\n- (a) Des couches de calcaire plissées, du pli d'un mètre au pli de plusieurs kilomètres.\n- (b) Un ensemble de péridotites, gabbros et basaltes en coussins affleurant à 3 000 m d'altitude.\n- (c) Des terrains anciens posés sur des terrains plus récents le long d'une surface peu inclinée, déplacés d'environ 40 km.\n- (d) Des blocs basculés limités par des failles normales, fossilisés sous des sédiments marins.\n- (e) Des failles inverses.\n\n1. Classe ces observations en deux groupes : les marqueurs du **raccourcissement** et les **témoins d'un océan disparu**. Nomme chaque structure.\n2. Une couche qui s'étendait sur **150 km** avant la collision ne couvre plus que **90 km** aujourd'hui. Calcule le raccourcissement en km puis en pourcentage de la longueur initiale.\n3. Explique ce que l'observation (d) révèle sur l'histoire de la région.","bareme":[{"critere":"Raccourcissement : (a) plis, (c) nappe de charriage, (e) failles inverses","points":6},{"critere":"Océan disparu : (b) ophiolites, (d) marge passive fossilisée","points":5},{"critere":"150 − 90 = 60 km, soit 60 / 150 = 40 %","points":5},{"critere":"(d) : ouverture initiale de l'océan (extension), avant la fermeture","points":4}],"dureeMin":12,"corrige":"1. **Marqueurs du raccourcissement** : (a) des **plis** ; (c) une **nappe de charriage** (terrains déplacés sur des dizaines de kilomètres, sur un chevauchement) ; (e) des **failles inverses**. **Témoins d'un océan disparu** : (b) des **ophiolites** (lithosphère océanique charriée en altitude) ; (d) une **marge passive fossilisée** (blocs basculés, failles normales).\n2. Raccourcissement : 150 − 90 = **60 km**. En pourcentage : 60 / 150 × 100 = **40 %** de la longueur initiale.\n3. Les failles normales et les blocs basculés sont la signature d'une **extension**. L'observation (d) témoigne de l'**ouverture initiale** de l'océan (rift puis océanisation), avant sa fermeture par subduction puis la collision : la chaîne garde la mémoire de tout le **cycle de Wilson**."}$exo$::jsonb),
  ('d62a9762-feb6-5e49-b763-d9bb543c8f93'::uuid, 3, 'application', $exo${"titre":"Une roche remontée de 30 km","consigne":"Exploite les documents et construis un récit argumenté de l'histoire de la roche et de la chaîne.","enonce":"**Document 1.** Au sommet d'une chaîne ancienne, Aya trouve une roche qui contient du **glaucophane** et du **grenat**. Elle n'a jamais fondu, mais ses minéraux ne sont pas ceux de la roche de départ, un basalte.\n\n**Document 2 — Domaines de stabilité (simplifiés).**\n\n| Minéral | Conditions dans lesquelles il se forme |\n| Glaucophane | Forte pression, température modérée (plongée rapide d'une roche froide) |\n| Grenat | Forte pression et température élevée |\n| Sillimanite | Température élevée, pression moyenne |\n\n**Document 3.** La chaîne d'Aya a aujourd'hui des reliefs usés et de faible altitude ; une chaîne jeune voisine culmine au-dessus de 4 000 m.\n\n1. Comment s'appelle la transformation subie par la roche du document 1 ? Définis-la.\n2. D'après les documents 1 et 2, dans quelles conditions la roche est-elle passée ? Déduis-en ce qui lui est arrivé.\n3. Cette roche affleure aujourd'hui en surface. Explique par quels processus une roche formée à 30 km de profondeur peut revenir à la surface.\n4. Explique le contraste du document 3 à l'aide du devenir d'une chaîne de montagnes.","bareme":[{"critere":"Métamorphisme : transformation minéralogique à l'état solide sous l'effet de P et T","points":4},{"critere":"Glaucophane et grenat : forte pression, donc enfouissement profond ; minéraux marqueurs du trajet P-T","points":5},{"critere":"Érosion du relief et rééquilibrage isostatique qui fait remonter la racine","points":5},{"critere":"Chaîne ancienne usée par l'érosion, chaîne jeune encore haute","points":4},{"critere":"Récit cohérent et appuyé sur les documents","points":2}],"dureeMin":18,"corrige":"1. C'est le **métamorphisme** : une **transformation minéralogique à l'état solide**, **sans fusion**, sous l'effet de nouvelles conditions de **pression** et de **température** liées à l'enfouissement.\n2. Le **glaucophane** indique une **forte pression** à température modérée : le basalte a été **enfoui profondément et rapidement** (plongée d'une roche froide, comme la croûte océanique en subduction). Le **grenat** indique forte pression et température plus élevée. Ces minéraux sont des **marqueurs** : ils permettent de reconstituer le **trajet pression-température** subi par la roche, donc l'histoire de la chaîne. Un basalte, roche de croûte océanique, enfoui ainsi puis intégré à la chaîne rappelle qu'un océan a disparu.\n3. Deux processus : l'**érosion** rabote le relief et exporte les sédiments vers les bassins ; le **rééquilibrage isostatique** fait **remonter la racine** à mesure que le sommet s'allège. C'est ce second processus qui amène en surface les roches métamorphiques formées à 30 km de profondeur.\n4. La chaîne d'Aya est **ancienne** : l'érosion et le rééquilibrage isostatique ont usé son relief (comme le Massif central ou les Appalaches). La chaîne voisine est **jeune** et s'élève encore (comme les Alpes ou l'Himalaya). L'**érosion** est la dernière étape du **cycle de Wilson**."}$exo$::jsonb),
  ('db568ee0-3901-5d3e-9e5b-e2116895f4e4'::uuid, 1, 'application', $exo${"titre":"Ce qu'est un écosystème","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Définis **biocénose**, **biotope** et **écosystème**.\n2. Nomme le type d'interaction dans chacune des situations suivantes :\n   - a) un champignon associé aux racines d'un arbre, au bénéfice des deux ;\n   - b) une tique qui se nourrit du sang d'un chevreuil ;\n   - c) deux plantes voisines qui poussent vers la même lumière ;\n   - d) un renard qui mange un lapin ;\n   - e) une plante épiphyte installée sur une branche, sans effet sur l'arbre.\n3. Pourquoi dit-on qu'un écosystème est **ouvert** pour l'énergie mais largement **fermé** pour la matière ?","bareme":[{"critere":"Trois définitions justes","points":6},{"critere":"a mutualisme, b parasitisme, c compétition, d prédation, e commensalisme","points":8},{"critere":"Énergie qui entre par la photosynthèse et se dissipe ; matière recyclée par les décomposeurs","points":6}],"dureeMin":7,"corrige":"1. **Biocénose** : les êtres vivants d'un milieu. **Biotope** : le milieu physico-chimique. **Écosystème** : la biocénose, le biotope et **toutes leurs interactions**.\n2. a) **mutualisme** (mycorhizes) ; b) **parasitisme** ; c) **compétition** ; d) **prédation** ; e) **commensalisme**.\n3. L'**énergie** entre par la **photosynthèse** des producteurs primaires, circule le long des réseaux trophiques et se **dégrade** à chaque niveau (chaleur, respiration) : elle doit sans cesse être renouvelée, l'écosystème est **ouvert**. La **matière** circule **en boucle** : les **décomposeurs** minéralisent la matière organique morte et rendent au milieu l'azote, le phosphore et le carbone que les producteurs réutilisent : l'écosystème est largement **fermé**."}$exo$::jsonb),
  ('db568ee0-3901-5d3e-9e5b-e2116895f4e4'::uuid, 2, 'application', $exo${"titre":"L'énergie d'une prairie","consigne":"Pose tes calculs et justifie chaque réponse avec le cours.","enonce":"**Situation.** Dans une prairie, les plantes fixent chaque année **200 000 kJ** d'énergie par photosynthèse sur la parcelle étudiée. On étudie la chaîne alimentaire : herbe → criquet → musaraigne → chouette. On admet qu'environ **10 %** de l'énergie passe d'un niveau trophique au suivant.\n\n1. Calcule l'énergie disponible pour les criquets, les musaraignes puis les chouettes.\n2. Que devient l'énergie qui ne passe pas au niveau suivant ?\n3. Explique, avec tes résultats, pourquoi les chaînes alimentaires comptent rarement plus de quatre ou cinq maillons et pourquoi les chouettes sont peu nombreuses.\n4. Les feuilles mortes et les cadavres de la prairie ne s'accumulent pas. Qui intervient, et que deviennent les éléments qu'ils contiennent ?","bareme":[{"critere":"Criquets 20 000 kJ, musaraignes 2 000 kJ, chouettes 200 kJ","points":6},{"critere":"Énergie dissipée en chaleur et consommée par la respiration","points":4},{"critere":"Énergie trop faible au sommet : peu de maillons et peu de grands prédateurs","points":5},{"critere":"Décomposeurs qui minéralisent la matière organique, éléments réutilisés par les producteurs","points":5}],"dureeMin":10,"corrige":"1. Criquets : 200 000 × 10 / 100 = **20 000 kJ**. Musaraignes : 20 000 × 0,1 = **2 000 kJ**. Chouettes : 2 000 × 0,1 = **200 kJ**, soit 1/1 000 de l'énergie fixée par les plantes.\n2. Environ 90 % de l'énergie de chaque niveau ne passe pas au suivant : elle est **dissipée en chaleur** et **consommée par la respiration** des êtres vivants. L'énergie se **dégrade** à chaque niveau.\n3. À chaque maillon, il ne reste qu'environ 10 % de l'énergie : au quatrième niveau, il ne reste que 200 kJ sur 200 000. Un cinquième ou sixième maillon ne disposerait plus que de 20 puis 2 kJ, trop peu pour faire vivre une population. Les **grands prédateurs**, au sommet de la chaîne, disposent de peu d'énergie : ils sont **peu nombreux**.\n4. Les **décomposeurs** (bactéries, champignons, faune du sol) **minéralisent** la matière organique morte. Ils rendent au milieu l'**azote**, le **phosphore** et le **carbone**, que les **producteurs** réutilisent : la matière circule **en boucle**."}$exo$::jsonb),
  ('db568ee0-3901-5d3e-9e5b-e2116895f4e4'::uuid, 3, 'application', $exo${"titre":"Une forêt après l'incendie","consigne":"Exploite les documents et rédige une analyse argumentée qui mobilise les notions du cours.","enonce":"**Document 1 — Une parcelle de pinède après un incendie (observations successives).**\n\n| Temps après l'incendie | Ce que l'on observe |\n| 1 an | Sol nu, quelques herbes et mousses |\n| 5 ans | Buissons, arbustes, premiers jeunes pins |\n| 30 ans | Pinède proche de celle d'avant l'incendie |\n\n**Document 2.** Les jeunes pins qui poussent le mieux portent sur leurs racines des champignons (mycorhizes) : le champignon aide l'arbre à puiser l'eau et les sels minéraux, l'arbre fournit au champignon des sucres issus de sa photosynthèse.\n\n**Document 3.** Sur une parcelle voisine, les incendies se sont répétés tous les deux ans pendant vingt ans : la pinède n'est jamais revenue, remplacée durablement par une lande de buissons.\n\n1. Nomme le phénomène décrit par le document 1 et ses stades.\n2. Nomme et explique l'interaction du document 2. En quoi aide-t-elle le retour de la forêt ?\n3. Définis la **résilience** d'un écosystème et appuie-toi sur les documents 1 et 3 pour montrer qu'elle n'est pas illimitée.\n4. Juste après l'incendie, les cendres et le bois mort restent sur le sol. Explique en quoi l'action des décomposeurs prépare le retour des plantes.","bareme":[{"critere":"Succession écologique, du stade pionnier au stade mature","points":4},{"critere":"Mutualisme (mycorhize) expliqué, avantage pour la croissance des pins","points":4},{"critere":"Résilience définie ; parcelle 1 résiliente, parcelle 2 basculée au-delà d'un seuil","points":6},{"critere":"Décomposeurs qui minéralisent et rendent les éléments aux producteurs","points":4},{"critere":"Appui précis sur les documents","points":2}],"dureeMin":18,"corrige":"1. Après la **perturbation** (incendie), l'écosystème se reconstruit par **succession écologique** : un **stade pionnier** (herbes, mousses sur sol nu), des stades intermédiaires (buissons, arbustes), puis le **stade mature** (pinède).\n2. C'est une relation de **mutualisme** : les deux partenaires y gagnent — le champignon aide l'arbre à puiser eau et sels minéraux, l'arbre fournit des sucres au champignon. Les pins mycorhizés poussent mieux : l'interaction accélère le retour de la forêt.\n3. La **résilience** est la capacité d'un écosystème à **retrouver un fonctionnement comparable** après une perturbation. Document 1 : après un incendie unique, la pinède revient en 30 ans : l'écosystème est **résilient**. Document 3 : avec des incendies répétés, la pinède ne revient pas et l'écosystème **bascule vers un autre état** (une lande) : **au-delà d'un seuil**, la résilience est dépassée.\n4. Les **décomposeurs** (bactéries, champignons, faune du sol) **minéralisent** la matière organique morte : ils rendent au sol l'**azote**, le **phosphore** et le **carbone** sous forme minérale, que les **producteurs** pionniers puis les pins réutilisent. La matière circule **en boucle**, alors que l'énergie devra de nouveau entrer par la photosynthèse."}$exo$::jsonb),
  ('7ee89269-3a85-5e93-a2fb-24887dde127b'::uuid, 1, 'application', $exo${"titre":"Ce que les écosystèmes nous rendent","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Définis un **service écosystémique**.\n2. Classe chaque service dans l'une des trois catégories (approvisionnement, régulation, culturel) : pollinisation des vergers ; bois de construction ; randonnée en forêt ; épuration de l'eau par une zone humide ; poissons pêchés ; stockage du carbone par une tourbière.\n3. Cite trois pressions humaines sur les écosystèmes. Laquelle est la première cause d'érosion de la biodiversité ?","bareme":[{"critere":"Définition : bénéfices tirés par les sociétés du fonctionnement des écosystèmes","points":4},{"critere":"Six services correctement classés","points":10},{"critere":"Trois pressions citées, destruction et fragmentation des habitats en premier","points":6}],"dureeMin":6,"corrige":"1. Un service écosystémique est un **bénéfice que les sociétés humaines tirent du fonctionnement des écosystèmes**.\n2. **Approvisionnement** : bois de construction, poissons pêchés. **Régulation** : pollinisation des vergers, épuration de l'eau par une zone humide, stockage du carbone par une tourbière. **Culturel** : randonnée en forêt (loisirs).\n3. Exemples : la **destruction et fragmentation des habitats**, la **surexploitation** (pêche, chasse, bois), les **pollutions** (nitrates, pesticides, plastiques), les **espèces exotiques envahissantes**, le **changement climatique**. La **première cause** d'érosion de la biodiversité est la **destruction et fragmentation des habitats**."}$exo$::jsonb),
  ('7ee89269-3a85-5e93-a2fb-24887dde127b'::uuid, 2, 'application', $exo${"titre":"Le marais de Saint-Aubin","consigne":"Lis la situation, puis réponds en justifiant avec le vocabulaire du cours.","enonce":"**Situation (fictive).** La commune de Saint-Aubin possède un marais de 40 hectares. Il épure l'eau de la rivière, retient l'eau lors des crues, abrite des oiseaux observés par de nombreux visiteurs et fournit du roseau utilisé pour les toitures. Un projet propose de l'assécher pour y construire une zone commerciale et une digue.\n\nPar ailleurs, en aval, les champs voisins sont fortement fertilisés : chaque été, l'étang communal se couvre d'algues et ses poissons meurent en partie.\n\n1. Classe les services rendus par le marais dans les trois catégories.\n2. Quels services seraient perdus si le marais était asséché ? Quelle pression humaine ce projet représenterait-il ?\n3. Nomme le phénomène qui touche l'étang et explique sa cause.\n4. Propose deux outils de gestion cités en cours qui pourraient être utilisés à Saint-Aubin, et explique leur intérêt.","bareme":[{"critere":"Approvisionnement (roseau), régulation (épuration, crues), culturel (observation des oiseaux)","points":5},{"critere":"Services perdus et destruction d'habitat identifiée","points":5},{"critere":"Eutrophisation due à l'excès de nutriments (nitrates)","points":5},{"critere":"Deux outils pertinents (aire protégée, corridor, restauration de zone humide, agroécologie…) justifiés","points":5}],"dureeMin":11,"corrige":"1. **Approvisionnement** : le roseau pour les toitures. **Régulation** : l'épuration de l'eau et la protection contre les crues. **Culturels** : l'observation des oiseaux (loisirs, tourisme, valeur esthétique).\n2. L'assèchement ferait perdre **tous ces services** : l'épuration, la rétention des crues (qu'il faudrait compenser par la digue), l'habitat des oiseaux et la production de roseau. Le projet est une **destruction d'habitat**, première cause d'érosion de la biodiversité. Il illustre un **choix entre services concurrents** : construire une digue peut supprimer une zone humide.\n3. C'est l'**eutrophisation** : un **enrichissement excessif du milieu aquatique en nutriments** (nitrates venus des engrais des champs) qui provoque la prolifération des algues et la mort de poissons. C'est une **pollution**.\n4. Exemples : créer une **aire protégée** sur le marais ; le relier à d'autres milieux par un **corridor écologique** (trame bleue) ; **restaurer** la zone humide ; encourager l'**agroécologie** dans les champs pour réduire les apports d'engrais ; des **paiements pour services environnementaux** aux agriculteurs qui les réduisent."}$exo$::jsonb),
  ('7ee89269-3a85-5e93-a2fb-24887dde127b'::uuid, 3, 'application', $exo${"titre":"Une forêt, plusieurs attentes","consigne":"Exploite les documents et rédige une argumentation nuancée, organisée en paragraphes.","enonce":"**Document 1 — Deux gestions possibles d'une même forêt (données fictives).**\n\n| | Gestion A : plantation d'une seule essence, coupe tous les 40 ans | Gestion B : forêt mélangée, coupes limitées |\n| Bois récolté par an | 12 m³/ha | 6 m³/ha |\n| Espèces d'oiseaux observées | 15 | 40 |\n| Fréquentation par les promeneurs | Faible | Forte |\n\n**Document 2.** Une association de promeneurs, un exploitant forestier et un apiculteur ne sont pas d'accord sur le choix de gestion.\n\n**Document 3.**\n> « La science établit les faits et éclaire les conséquences des options, elle ne décide pas à la place de la société. »\n\n1. Pour chaque gestion, indique quels services sont favorisés et lesquels sont réduits, en citant les données.\n2. Explique pourquoi le choix entre A et B est un **arbitrage** et non une question purement scientifique.\n3. Présente les **trois piliers** d'une décision de gestion et applique-les à cette forêt.\n4. Explique le document 3 en t'appuyant sur cet exemple.","bareme":[{"critere":"A : approvisionnement en bois (12 m³/ha) ; B : biodiversité et services culturels (40 espèces, forte fréquentation)","points":5},{"critere":"Arbitrage : maximiser un service se fait au détriment d'un autre","points":4},{"critere":"Trois piliers : état scientifique, évaluation coûts-bénéfices, débat social, appliqués","points":6},{"critere":"Rôle de la science distingué du choix de société","points":3},{"critere":"Argumentation organisée et nuancée","points":2}],"dureeMin":18,"corrige":"1. **Gestion A** : elle favorise le service d'**approvisionnement** (12 m³/ha de bois par an, le double de B) mais réduit la **biodiversité** (15 espèces d'oiseaux) et les services **culturels** (faible fréquentation). **Gestion B** : elle favorise la biodiversité (40 espèces) et les services culturels (forte fréquentation), probablement aussi la pollinisation utile à l'apiculteur, mais **divise par deux** la récolte de bois. Comme le dit le cours : maximiser la production de bois coûte une biodiversité forestière réduite.\n2. Les services sont **concurrents** : maximiser l'un se fait **au détriment d'un autre**. Aucune option ne satisfait tout le monde (document 2) : il faut choisir ce que l'on veut privilégier, ce qui relève de **valeurs** et d'intérêts, pas seulement de mesures.\n3. (1) Un **état scientifique** des connaissances : les données du document 1 (bois, espèces, fréquentation). (2) Une **évaluation des coûts et des bénéfices** de chaque option : revenus du bois, pertes pour l'apiculture et le tourisme. (3) Un **débat social** entre exploitant, promeneurs, apiculteur et élus, sur ce que l'on veut préserver. Des solutions intermédiaires peuvent en sortir (zones exploitées et zones protégées, corridors).\n4. La science **mesure** et **prévoit** les conséquences de A et de B ; elle ne dit pas lequel des services vaut le plus. Ce choix appartient à la **société**, éclairée par ces faits."}$exo$::jsonb),
  ('edac8366-9883-5a36-81d2-61e754d9910a'::uuid, 1, 'application', $exo${"titre":"Maladies génétiques : les modes de transmission","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Recopie et complète :\n\n| Mode de transmission | Qui exprime la maladie | Un exemple |\n| Autosomique récessive | … | … |\n| Autosomique dominante | … | … |\n| Liée à l'X | … | … |\n\n2. Qu'est-ce qu'un **porteur sain** ?\n3. Distingue une maladie **monogénique** d'une maladie **multifactorielle**, avec un exemple de chaque.\n4. Porter un allèle de prédisposition signifie-t-il qu'on développera la maladie ? Justifie.","bareme":[{"critere":"Tableau juste : homozygote/mucoviscidose ; un seul allèle suffit/Huntington ; surtout les garçons/hémophilie","points":8},{"critere":"Porteur sain : hétérozygote non malade qui peut transmettre l'allèle","points":4},{"critere":"Monogénique (un gène) / multifactorielle (gènes de prédisposition + environnement), exemples justes","points":5},{"critere":"Non : probabilité plus élevée seulement","points":3}],"dureeMin":8,"corrige":"1. **Autosomique récessive** : seul l'**homozygote** est malade, les parents sont **porteurs sains** ; ex. mucoviscidose, drépanocytose. **Autosomique dominante** : **un seul allèle muté suffit** ; un parent atteint transmet à la moitié de ses enfants ; ex. chorée de Huntington. **Liée à l'X** : **surtout les garçons**, qui n'ont qu'un X ; ex. hémophilie, daltonisme, myopathie de Duchenne.\n2. Un porteur sain possède **un allèle muté et un allèle normal** (hétérozygote) d'un gène de maladie récessive : il n'est **pas malade** mais peut **transmettre** l'allèle.\n3. Une maladie **monogénique** dépend d'**un seul gène** et suit les lois de Mendel (ex. mucoviscidose). Une maladie **multifactorielle** dépend de **plusieurs gènes de prédisposition** et de l'**environnement** (ex. diabète de type 2, hypertension).\n4. **Non** : porter un allèle de prédisposition n'est pas être malade, c'est avoir une **probabilité plus élevée** de le devenir."}$exo$::jsonb),
  ('edac8366-9883-5a36-81d2-61e754d9910a'::uuid, 2, 'application', $exo${"titre":"L'arbre de la famille Martin","consigne":"Raisonne à partir de l'arbre décrit et justifie chaque conclusion.","enonce":"**Situation.** Voici la description de l'arbre généalogique d'une famille touchée par une maladie génétique.\n\n- Génération I : **I-1** (homme, non atteint) et **I-2** (femme, non atteinte).\n- Génération II, leurs trois enfants : **II-1** (garçon, atteint), **II-2** (fille, non atteinte), **II-3** (fille, atteinte).\n\n**Rappel.** Un garçon reçoit son unique chromosome X de sa mère et son Y de son père ; une fille reçoit un X de chacun de ses parents.\n\n1. L'allèle responsable de la maladie est-il dominant ou récessif ? Justifie avec l'observation clé.\n2. Quel est le statut des parents I-1 et I-2 vis-à-vis de l'allèle ? Justifie.\n3. Montre que le gène ne peut pas être porté par le chromosome X. Déduis-en le mode de transmission.\n4. II-2 n'est pas atteinte. Peut-on affirmer qu'elle ne porte pas l'allèle muté ? Explique.","bareme":[{"critere":"Récessif : deux parents non atteints ont des enfants atteints","points":5},{"critere":"Parents porteurs sains (hétérozygotes)","points":4},{"critere":"Fille atteinte avec père non atteint : liaison à l'X exclue, transmission autosomique récessive","points":7},{"critere":"II-2 peut être porteuse saine","points":4}],"dureeMin":12,"corrige":"1. L'allèle est **récessif** : les parents I-1 et I-2 sont **non atteints** et ont des enfants **atteints** (II-1 et II-3). Ils portent donc l'allèle sans l'exprimer.\n2. I-1 et I-2 sont **porteurs sains** : chacun possède un allèle muté et un allèle normal, et chacun a transmis l'allèle muté à ses enfants malades.\n3. Si le gène était porté par l'X et récessif, la fille **II-3**, atteinte, devrait avoir reçu un X muté de chacun de ses parents, dont son **père I-1**. Or un homme n'a qu'**un seul X** : avec un X muté, I-1 serait lui-même atteint, ce qui n'est pas le cas. Le gène n'est donc pas porté par l'X : la transmission est **autosomique récessive** (comme la mucoviscidose).\n4. **Non**. II-2 peut avoir reçu deux allèles normaux, ou un allèle muté et un allèle normal : dans ce second cas, elle est **porteuse saine**, non malade mais capable de transmettre l'allèle. Seul un **séquençage** permettrait de le savoir."}$exo$::jsonb),
  ('edac8366-9883-5a36-81d2-61e754d9910a'::uuid, 3, 'application', $exo${"titre":"Du diagnostic au débat éthique","consigne":"Exploite les documents et rédige des réponses argumentées, en distinguant soigneusement les situations.","enonce":"**Document 1.** Samuel, 25 ans, a un père atteint de la chorée de Huntington, maladie autosomique dominante qui se déclare le plus souvent à l'âge adulte ; sa mère n'est pas atteinte. Samuel ne présente aucun symptôme.\n\n**Document 2.** Lina porte un allèle qui augmente le risque de diabète de type 2. Son frère porte le même allèle. Lina fait du sport et mange équilibré ; son frère est sédentaire et en surpoids. Seul son frère a développé un diabète.\n\n**Document 3.** Deux projets de recherche : (A) corriger par CRISPR-Cas9 la mutation dans des cellules sanguines prélevées chez un malade, puis les lui réinjecter ; (B) corriger la mutation dans un embryon humain.\n\n1. Quelle est la probabilité que Samuel ait hérité de l'allèle de son père ? Justifie avec le mode de transmission. Quel outil permettrait de le savoir avant l'apparition des symptômes ?\n2. Explique le document 2 en utilisant les notions de maladie multifactorielle et de prédisposition.\n3. Pour les projets A et B, indique quel type de cellules est modifié et qui est concerné par la modification.\n4. Explique pourquoi le projet B soulève des questions éthiques bien plus lourdes que le projet A.","bareme":[{"critere":"Une chance sur deux (dominante, parent atteint transmet à la moitié) ; séquençage","points":5},{"critere":"Diabète de type 2 multifactoriel : prédisposition + environnement, appliqué aux deux personnes","points":5},{"critere":"A : cellules somatiques, le seul patient ; B : cellules germinales, la descendance","points":5},{"critere":"B modifie la descendance : débat bioéthique et encadrement par la loi","points":3},{"critere":"Réponses nuancées, sans confondre prédisposition et maladie","points":2}],"dureeMin":18,"corrige":"1. La chorée de Huntington est **autosomique dominante** : un seul allèle muté suffit, et un parent atteint transmet la maladie à **la moitié de ses enfants**. Samuel a donc **une chance sur deux** (1/2) d'avoir hérité de l'allèle. L'absence de symptômes ne permet pas de conclure car la maladie se déclare souvent à l'âge adulte. Le **séquençage** permet de repérer la mutation avant l'apparition des symptômes.\n2. Le diabète de type 2 est une maladie **multifactorielle** : il dépend de **gènes de prédisposition** et de l'**environnement** (mode de vie). Lina et son frère portent le même allèle de prédisposition, qui augmente seulement la **probabilité** d'être malade ; le mode de vie du frère (sédentarité, surpoids) a favorisé la maladie, celui de Lina l'a limitée. Porter un allèle de prédisposition n'est pas être malade.\n3. **Projet A** : des cellules **somatiques** (sanguines) ; la modification ne concerne que **le patient** et disparaît avec lui (thérapie par édition du génome). **Projet B** : un embryon, dont les cellules donneront aussi les cellules **germinales** ; la modification serait transmise à **la descendance**.\n4. Le projet B modifierait le patrimoine génétique de personnes qui n'ont pas consenti (les descendants) et de façon héréditaire, avec des effets imprévisibles sur plusieurs générations. La distinction entre **soigner un individu** et **modifier sa descendance** est au cœur du débat bioéthique, et la loi l'**encadre strictement**."}$exo$::jsonb),
  ('ac46543c-71fd-5a8c-9fbb-b9446492b253'::uuid, 1, 'application', $exo${"titre":"Quand une cellule échappe au contrôle","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Recopie et complète :\n\n| Gène | Rôle normal | Effet de la mutation |\n| Proto-oncogène | … | … |\n| Gène suppresseur de tumeur | … | … |\n| Gène de réparation de l'ADN | … | … |\n\n2. Pourquoi le gène p53 est-il surnommé « gardien du génome » ?\n3. Nomme et décris dans l'ordre les quatre étapes de la cancérisation.\n4. Une seule mutation suffit-elle à provoquer un cancer ? Justifie.","bareme":[{"critere":"Tableau juste : oncogène hyperactif, perte de fonction du frein, accumulation accélérée des mutations","points":7},{"critere":"p53 : gène suppresseur de tumeur (réparation, apoptose), muté dans une grande part des cancers","points":3},{"critere":"Initiation, promotion, progression (angiogenèse, invasion), métastases","points":6},{"critere":"Non : accumulation de plusieurs mutations dans une même lignée","points":4}],"dureeMin":8,"corrige":"1. **Proto-oncogène** : favorise la division ; muté, il devient un **oncogène hyperactif** (l'accélérateur bloqué). **Gène suppresseur de tumeur** : freine la division, déclenche la réparation ou l'**apoptose** ; la mutation entraîne une **perte de fonction** (le frein qui lâche). **Gène de réparation de l'ADN** : corrige les erreurs ; muté, il laisse les autres mutations **s'accumuler plus vite** (le correcteur en panne).\n2. p53 est un **gène suppresseur de tumeur** : il freine la division et déclenche réparation ou apoptose d'une cellule à l'ADN endommagé. Il est **muté dans une grande part des cancers humains**.\n3. **Initiation** : une première mutation dans une cellule. **Promotion** : d'autres mutations s'accumulent, un clone prolifère. **Progression** : la tumeur devient maligne, recrute des vaisseaux (**angiogenèse**), devient invasive. **Métastases** : des cellules migrent par le sang ou la lymphe et colonisent d'autres organes.\n4. **Non** : le processus est progressif, il faut **plusieurs mutations accumulées** dans une même lignée cellulaire."}$exo$::jsonb),
  ('ac46543c-71fd-5a8c-9fbb-b9446492b253'::uuid, 2, 'application', $exo${"titre":"Le dossier de M. Leroy","consigne":"Analyse la situation et justifie chaque réponse avec le cours.","enonce":"**Situation (fictive).** M. Leroy, 62 ans, a fumé un paquet de cigarettes par jour pendant quarante ans. On lui découvre une tumeur du poumon. L'analyse des cellules tumorales montre :\n- une mutation qui rend hyperactif un gène stimulant la division cellulaire ;\n- une mutation qui inactive le gène p53 ;\n- des vaisseaux sanguins nouvellement formés qui irriguent la tumeur ;\n- des cellules tumorales identiques retrouvées dans un ganglion lymphatique.\n\n1. Identifie le type de gène touché par chacune des deux mutations et explique leurs effets combinés sur la cellule.\n2. Associe chacune des deux dernières observations à une étape de la cancérisation.\n3. Quel facteur de risque apparaît dans ce dossier ? À quelle catégorie appartient-il ? Explique pourquoi on parle de facteur de risque et non de cause suffisante.\n4. Les enfants de M. Leroy ont-ils hérité de ces mutations ? Justifie.","bareme":[{"critere":"Proto-oncogène devenu oncogène et suppresseur de tumeur inactivé : accélérateur bloqué et frein lâché","points":6},{"critere":"Angiogenèse (progression) et cellules dans un ganglion (métastases)","points":4},{"critere":"Tabac, facteur environnemental, première cause évitable ; augmente une probabilité","points":5},{"critere":"Mutations somatiques, non transmises aux enfants","points":5}],"dureeMin":12,"corrige":"1. Le gène stimulant la division est un **proto-oncogène** devenu **oncogène** hyperactif (l'accélérateur bloqué). p53 est un **gène suppresseur de tumeur**, ici **inactivé** (le frein qui lâche) : il ne peut plus déclencher la réparation ou l'**apoptose**. Ensemble, ces mutations poussent la cellule à se diviser sans contrôle et empêchent l'élimination des cellules anormales, ce qui favorise l'accumulation d'autres mutations.\n2. Les vaisseaux nouvellement formés correspondent à l'**angiogenèse** : étape de **progression**. Les cellules tumorales dans un ganglion ont migré par la lymphe : c'est le début des **métastases**.\n3. Le **tabac**, facteur **environnemental**, **première cause évitable** de cancer. C'est un facteur de risque et non une cause suffisante : il **augmente la probabilité** de cancer (en provoquant des mutations), sans qu'un fumeur développe forcément un cancer.\n4. **Non**. Ces mutations sont apparues dans des cellules du poumon : ce sont des mutations **somatiques**, **non transmissibles**. Dans les formes familiales, ce qui se transmet est une **prédisposition**."}$exo$::jsonb),
  ('ac46543c-71fd-5a8c-9fbb-b9446492b253'::uuid, 3, 'application', $exo${"titre":"Âge, hérédité et prévention","consigne":"Exploite les documents et rédige une argumentation structurée qui mobilise l'ensemble du cours.","enonce":"**Document 1 — Nombre de nouveaux cas de cancers pour 100 000 personnes selon l'âge (données simplifiées, fictives).**\n\n| Âge | 20 ans | 40 ans | 60 ans | 80 ans |\n| Nouveaux cas | 30 | 150 | 900 | 2 000 |\n\n**Document 2.** Dans la famille de Clémence, plusieurs femmes ont eu un cancer du sein. Un test montre que Clémence porte une mutation du gène *BRCA1*, présente dans toutes ses cellules. Elle ne présente aucun cancer.\n\n**Document 3.** Une campagne de santé recommande : ne pas fumer, se protéger du soleil, se faire vacciner contre le papillomavirus, participer aux dépistages.\n\n1. Décris le document 1 et explique cette évolution à partir du mécanisme de la cancérisation.\n2. La mutation *BRCA1* de Clémence est-elle somatique ou germinale ? Justifie. Explique pourquoi on parle de **prédisposition** et non de maladie.\n3. Pour chaque recommandation du document 3, indique le facteur de risque visé ou le type de prévention.\n4. Cite deux traitements des cancers et explique le principe d'une immunothérapie.","bareme":[{"critere":"Nombre de cas qui augmente avec l'âge, expliqué par l'accumulation progressive de mutations","points":5},{"critere":"Mutation germinale héritée (toutes les cellules) ; prédisposition = probabilité accrue","points":5},{"critere":"Tabac, UV, papillomavirus (prévention primaire), dépistage précoce","points":5},{"critere":"Deux traitements cités, immunothérapie qui réactive le système immunitaire","points":3},{"critere":"Données chiffrées utilisées","points":2}],"dureeMin":18,"corrige":"1. Le nombre de nouveaux cas **augmente fortement avec l'âge** : de 30 à 20 ans à 2 000 à 80 ans (près de 67 fois plus). Un cancer résulte de **plusieurs mutations accumulées** dans une même lignée cellulaire (initiation, promotion, progression) ; plus on vit longtemps, plus les cellules ont eu le temps d'accumuler des mutations et d'être exposées à des facteurs de risque.\n2. La mutation est présente dans **toutes ses cellules** : elle a été héritée d'un parent, c'est une mutation **germinale**. Clémence n'est pas malade : elle a une **prédisposition**, c'est-à-dire une **probabilité plus élevée** de développer un cancer ; d'autres mutations, somatiques, devront s'accumuler pour qu'un cancer apparaisse. Dans les formes familiales, c'est la prédisposition qui se transmet.\n3. Ne pas fumer : **tabac**, première cause évitable. Se protéger du soleil : **UV**. Vaccin : **papillomavirus**. Ces trois gestes relèvent de la **prévention primaire**. Le **dépistage** précoce permet de repérer un cancer tôt, quand il se traite mieux.\n4. Exemples : **chirurgie**, **radiothérapie**, **chimiothérapie**, **thérapies ciblées**, **immunothérapies**. Une immunothérapie **réactive le système immunitaire** du patient contre la tumeur."}$exo$::jsonb),
  ('97ea11d8-b76d-5944-a451-a2d8ecdf35d5'::uuid, 1, 'application', $exo${"titre":"Antibiotiques et résistance","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Sur quoi un antibiotique agit-il ? Pourquoi est-il inutile contre un rhume ?\n2. Cite les quatre origines possibles d'une résistance chez une bactérie et explique brièvement chacune.\n3. Vrai ou faux : « l'antibiotique provoque la mutation de résistance ». Justifie en décrivant ce qui se passe réellement.","bareme":[{"critere":"Agit sur les bactéries seulement, aucun effet sur les virus (rhume viral)","points":4},{"critere":"Mutation spontanée, conjugaison, transformation, transduction expliquées","points":8},{"critere":"Faux : mutation préexistante, sélection des résistantes qui se multiplient","points":8}],"dureeMin":7,"corrige":"1. Un antibiotique **tue les bactéries** ou bloque leur multiplication. Il n'a **aucun effet sur les virus** : un rhume, d'origine virale, ne se soigne pas par antibiotique.\n2. **Mutation spontanée** : le génome bactérien change au hasard. **Conjugaison** : échange de **plasmides** entre deux bactéries, même d'espèces différentes. **Transformation** : capture d'**ADN libre** dans le milieu. **Transduction** : transport de gènes par un **virus bactériophage**. Les trois dernières sont des **transferts de gènes**, qui expliquent la vitesse de diffusion.\n3. **Faux**. La mutation de résistance **préexiste**, apparue **au hasard** dans une population immense. L'antibiotique **élimine les bactéries sensibles** ; les rares résistantes ont alors la place et les ressources, se multiplient et deviennent **majoritaires**. L'antibiotique **sélectionne** les résistantes : c'est un exemple de **sélection naturelle**."}$exo$::jsonb),
  ('97ea11d8-b76d-5944-a451-a2d8ecdf35d5'::uuid, 2, 'application', $exo${"titre":"L'antibiogramme de Mme Diallo","consigne":"Exploite les résultats, pose ton calcul et justifie chaque réponse.","enonce":"**Situation (fictive).** Mme Diallo souffre d'une infection urinaire bactérienne. Le laboratoire réalise un **antibiogramme** : la bactérie est étalée sur une boîte, on y dépose des pastilles de quatre antibiotiques, et l'on mesure autour de chacune le diamètre de la zone où les bactéries ne poussent pas. On admet ici que la souche est **sensible** si le diamètre dépasse 20 mm, **résistante** s'il est inférieur à 15 mm.\n\n| Antibiotique | A | B | C | D |\n| Diamètre (mm) | 8 | 26 | 12 | 22 |\n\n1. À quoi sert un antibiogramme ? Classe la souche vis-à-vis de chaque antibiotique.\n2. Quel(s) antibiotique(s) le médecin peut-il prescrire ? Justifie.\n3. Dans de bonnes conditions, cette bactérie se divise toutes les **20 minutes**. Calcule le nombre de bactéries issues d'une seule bactérie résistante après **4 heures**.\n4. Mme Diallo se sent mieux après deux jours et veut arrêter le traitement prévu pour sept jours. Explique le risque.","bareme":[{"critere":"Antibiogramme = test de sensibilité ; A et C résistante, B et D sensible","points":5},{"critere":"Prescription de B ou D, justifiée","points":3},{"critere":"4 h = 12 générations, 2 puissance 12 = 4 096 bactéries","points":6},{"critere":"Arrêt prématuré : survie des moins sensibles qui se multiplient","points":6}],"dureeMin":12,"corrige":"1. L'antibiogramme **teste in vitro la sensibilité** d'une souche aux différents antibiotiques, pour **cibler la molécule efficace**. **A** (8 mm) et **C** (12 mm) : souche **résistante** (moins de 15 mm). **B** (26 mm) et **D** (22 mm) : souche **sensible** (plus de 20 mm).\n2. Le médecin peut prescrire **B ou D** : ce sont les seuls auxquels la souche est sensible. Prescrire A ou C serait inefficace et sélectionnerait encore davantage les bactéries résistantes.\n3. En 4 h = 240 min, il y a 240 / 20 = **12 générations**. Le nombre de bactéries double à chaque génération : 2 puissance 12 = **4 096 bactéries** à partir d'une seule.\n4. L'**arrêt prématuré** laisse survivre les bactéries **les moins sensibles**, qui se multiplient ensuite : l'infection peut revenir, avec une population de bactéries plus résistantes. Il faut **respecter la durée** prescrite (bon usage)."}$exo$::jsonb),
  ('97ea11d8-b76d-5944-a451-a2d8ecdf35d5'::uuid, 3, 'application', $exo${"titre":"La résistance, une sélection sous nos yeux","consigne":"Exploite les documents et rédige une argumentation rigoureuse : attention au rôle exact de l'antibiotique.","enonce":"**Document 1 — Expérience (données simplifiées).** Une population d'un milliard de bactéries n'a jamais été en contact avec un antibiotique X. On en analyse un échantillon représentatif : environ 3 bactéries sur un milliard portent déjà une mutation qui les rend résistantes à X. On ajoute alors X au milieu.\n\n| Temps après l'ajout de X | Bactéries sensibles | Bactéries résistantes |\n| 0 h | environ 1 milliard | 3 |\n| 6 h | presque aucune | quelques centaines |\n| 24 h | aucune | plusieurs millions |\n\n**Document 2.** Dans un hôpital, un gène de résistance porté par un plasmide a été retrouvé chez deux espèces de bactéries différentes, chez des patients du même service.\n\n**Document 3.** Pendant longtemps, des antibiotiques ont été ajoutés massivement à l'alimentation d'animaux d'élevage comme facteurs de croissance.\n\n1. Montre, avec le document 1, que l'antibiotique n'a pas créé la résistance. Explique les résultats à 6 h et 24 h.\n2. Pourquoi peut-on parler de sélection naturelle observable en quelques jours ?\n3. Explique le document 2 : par quel mécanisme le gène a-t-il pu passer d'une espèce à l'autre ? Quelle mesure d'hygiène limiterait sa diffusion dans le service ?\n4. Explique en quoi la pratique du document 3 a accéléré le phénomène. Propose deux autres leviers pour lutter contre les résistances.","bareme":[{"critere":"Mutants présents avant l'ajout de X ; élimination des sensibles, multiplication des résistantes","points":6},{"critere":"Sélection naturelle rapide : générations très courtes, population immense","points":3},{"critere":"Conjugaison (plasmide, même entre espèces) ; isolement ou lavage des mains","points":4},{"critere":"Usage massif en élevage : pression de sélection ; deux leviers (bon usage, antibiogramme, recherche…)","points":5},{"critere":"Formulation rigoureuse du rôle sélectif de l'antibiotique","points":2}],"dureeMin":18,"corrige":"1. Avant tout contact avec X, **3 bactéries sur un milliard** portent déjà la mutation : la résistance **préexiste**, apparue **au hasard**. L'antibiotique ne l'a donc pas créée. À **6 h**, X a **éliminé presque toutes les bactéries sensibles** ; les résistantes, qui ont désormais la place et les ressources, ont commencé à se multiplier (quelques centaines). À **24 h**, elles sont **plusieurs millions** et forment toute la population : X les a **sélectionnées**.\n2. Le milieu (l'antibiotique) favorise les porteurs d'un caractère héréditaire apparu au hasard, qui se reproduisent davantage et deviennent majoritaires : c'est la **sélection naturelle**. Chez des organismes dont les générations se succèdent en une vingtaine de minutes, on l'observe en quelques jours.\n3. Le gène est porté par un **plasmide** : il a pu être transmis par **conjugaison**, échange de plasmides entre bactéries, **même d'espèces différentes** (transfert de gènes propre au monde bactérien). Pour limiter sa diffusion : **isolement des patients porteurs** et **lavage des mains**.\n4. Un usage massif en élevage expose d'immenses populations bactériennes à l'antibiotique : il **élimine les sensibles** et **sélectionne les résistantes**, qui peuvent ensuite se transmettre. Autres leviers : le **bon usage** (prescrire seulement quand c'est nécessaire, respecter la durée, ne pas traiter une infection virale) ; l'**antibiogramme** pour cibler la molécule ; la **recherche** de nouvelles molécules et la phagothérapie."}$exo$::jsonb),
  ('9b7bfa3b-00e5-5048-b082-f341bbbe6af3'::uuid, 1, 'application', $exo${"titre":"La première ligne de défense","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Donne trois caractéristiques de l'immunité innée.\n2. Cite les quatre signes de la réaction inflammatoire aiguë et la cause de chacun.\n3. Nomme dans l'ordre les quatre étapes de la phagocytose.\n4. Quelle cellule fait le lien entre immunité innée et immunité adaptative ? Explique en une phrase comment.","bareme":[{"critere":"Immédiate, non spécifique, sans mémoire (présente dès la naissance)","points":4},{"critere":"Rougeur et chaleur (vasodilatation), gonflement (perméabilité), douleur (médiateurs sur les terminaisons nerveuses)","points":7},{"critere":"Adhésion, ingestion, digestion, élimination","points":5},{"critere":"Cellule dendritique présentatrice de l'antigène dans un ganglion","points":4}],"dureeMin":7,"corrige":"1. L'immunité innée est **immédiate**, **non spécifique** (elle réagit de la même façon quel que soit l'intrus) et **sans mémoire** ; elle est présente dès la naissance.\n2. **Rougeur** et **chaleur** : dues à la **vasodilatation** locale. **Gonflement** (œdème) : dû à l'**augmentation de la perméabilité** des vaisseaux. **Douleur** : due aux **médiateurs** qui stimulent les terminaisons nerveuses.\n3. **Adhésion** (le phagocyte se lie au microbe), **ingestion** (il l'englobe dans une vésicule), **digestion** (enzymes du phagolysosome), **élimination** des débris.\n4. La **cellule dendritique** : après avoir phagocyté, elle migre vers un **ganglion lymphatique** et y présente des fragments de l'intrus ; devenue **cellule présentatrice de l'antigène**, elle déclenche l'immunité adaptative."}$exo$::jsonb),
  ('9b7bfa3b-00e5-5048-b082-f341bbbe6af3'::uuid, 2, 'application', $exo${"titre":"L'écharde de Théo","consigne":"Explique chaque étape de la situation avec le vocabulaire du cours.","enonce":"**Situation.** Théo s'enfonce une écharde sale dans le doigt en jardinant. Quelques heures plus tard, la zone est rouge, chaude, gonflée et douloureuse.\n\n1. Quelle barrière a été franchie par les bactéries ? Cite deux autres barrières naturelles de l'organisme.\n2. Décris ce qui se passe dans le doigt, depuis la détection des bactéries jusqu'à l'arrivée des phagocytes. Nomme les cellules et les molécules en jeu.\n3. Relie chacun des symptômes observés à sa cause.\n4. Théo prend un anti-inflammatoire pour calmer la douleur. Explique l'intérêt et la limite de ce médicament.","bareme":[{"critere":"Peau franchie ; deux autres barrières (muqueuses, mucus, cils, acidité gastrique, microbiote)","points":4},{"critere":"Cellules sentinelles, récepteurs, médiateurs (histamine, prostaglandines, cytokines), attraction des phagocytes","points":7},{"critere":"Rougeur/chaleur : vasodilatation ; gonflement : perméabilité ; douleur : médiateurs","points":5},{"critere":"Anti-inflammatoire : soulage mais affaiblit une défense utile","points":4}],"dureeMin":11,"corrige":"1. L'écharde a franchi la **peau**. Autres barrières : les **muqueuses**, le **mucus**, les **cils**, l'**acidité gastrique**, le **microbiote**.\n2. Les **cellules sentinelles** des tissus (macrophages, cellules dendritiques, mastocytes) détectent les bactéries grâce à leurs **récepteurs**, qui reconnaissent des motifs moléculaires **communs à des familles entières** de microbes. Elles libèrent des **médiateurs de l'inflammation** (**histamine**, **prostaglandines**, **cytokines**) qui provoquent une **vasodilatation**, augmentent la perméabilité des vaisseaux et **attirent les phagocytes** sur le site, où ils phagocytent les bactéries.\n3. **Rougeur** et **chaleur** : la **vasodilatation** locale. **Gonflement** : l'**augmentation de la perméabilité** des vaisseaux (œdème). **Douleur** : les **médiateurs** stimulent les terminaisons nerveuses.\n4. L'anti-inflammatoire (ibuprofène, aspirine…) **réduit la réaction inflammatoire** : il soulage une douleur ou une réaction excessive. Mais il **affaiblit aussi une défense utile** contre les bactéries : d'où la **prudence** lors de certaines infections."}$exo$::jsonb),
  ('9b7bfa3b-00e5-5048-b082-f341bbbe6af3'::uuid, 3, 'application', $exo${"titre":"Des souris sans alarme","consigne":"Exploite les documents et construis une explication argumentée du rôle de l'immunité innée.","enonce":"**Document 1 — Expérience (données simplifiées).** On injecte sous la peau de souris une même bactérie.\n\n| Souris | Réaction inflammatoire au point d'injection | Bactéries au point d'injection après 48 h |\n| Normales | Forte, en quelques heures | Très peu |\n| Privées d'un récepteur des cellules sentinelles qui reconnaît un motif présent chez de nombreuses bactéries | Très faible | Très nombreuses |\n\n**Document 2.** Chez les souris normales, on retrouve 24 h après l'injection des cellules dendritiques contenant des fragments de la bactérie dans le ganglion lymphatique le plus proche. Quelques jours plus tard, des lymphocytes spécifiques de cette bactérie y prolifèrent.\n\n**Document 3.** Les souris normales, infectées ensuite par une bactérie d'une tout autre espèce portant le même motif, développent aussi une réaction inflammatoire rapide.\n\n1. Qu'apprend-on du document 1 sur le rôle des récepteurs des cellules sentinelles ?\n2. Montre, avec les documents 1 et 3, que la réponse innée est **non spécifique**. Explique pourquoi.\n3. Explique le document 2 et le lien entre immunité innée et immunité adaptative.\n4. Rédige une conclusion : l'immunité innée n'est-elle qu'une « première ligne » indépendante ?","bareme":[{"critere":"Sans récepteur, pas de détection, pas d'inflammation ni d'élimination des bactéries","points":5},{"critere":"Non-spécificité : motifs communs à des familles entières de microbes, même réponse pour une autre espèce","points":5},{"critere":"Cellule dendritique qui migre au ganglion, présente l'antigène et déclenche la réponse adaptative","points":5},{"critere":"Conclusion : l'inné commande l'adaptatif, les deux systèmes ne sont pas indépendants","points":3},{"critere":"Données des documents citées","points":2}],"dureeMin":18,"corrige":"1. Sans le récepteur, la réaction inflammatoire est **très faible** et les bactéries restent **très nombreuses** après 48 h. Les **récepteurs** des cellules sentinelles sont donc indispensables pour **détecter** l'intrus, déclencher la libération des **médiateurs**, l'inflammation et l'arrivée des **phagocytes** qui éliminent les bactéries.\n2. Le récepteur reconnaît un **motif présent chez de nombreuses bactéries** (document 1), et une bactérie d'une **autre espèce** portant ce motif déclenche la **même réaction rapide** (document 3). La réponse ne dépend pas de l'identité précise de l'intrus : les récepteurs détectent des motifs **communs à des familles entières** d'agents infectieux. C'est pourquoi l'immunité innée est **non spécifique**, et **immédiate**.\n3. Les **cellules dendritiques** ont phagocyté la bactérie au point d'injection, puis ont **migré vers le ganglion lymphatique**, où elles présentent des fragments de l'intrus : elles sont devenues **cellules présentatrices de l'antigène**. C'est ce geste qui **déclenche l'immunité adaptative** : des lymphocytes spécifiques prolifèrent quelques jours plus tard.\n4. L'immunité innée est bien la première ligne, **immédiate**, qui contient l'infection ; mais elle n'est **pas indépendante** : c'est elle qui **commande** le déclenchement de l'immunité adaptative. Sans détection innée, ni défense immédiate, ni réponse adaptative efficace."}$exo$::jsonb),
  ('f7d0513d-ad19-52e2-b26b-285be07cc806'::uuid, 1, 'application', $exo${"titre":"Une réponse spécifique et une mémoire","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Qu'est-ce qu'un **antigène** ? Explique le principe de la **sélection clonale**.\n2. Recopie et complète :\n\n| Voie | Cellule | Arme | Contre quoi |\n| Humorale | … | … | … |\n| Cellulaire | … | … | … |\n\n3. Quel est le rôle du lymphocyte T auxiliaire (LT4) ?\n4. Compare immunité innée et immunité adaptative selon le délai, la spécificité et la mémoire.","bareme":[{"critere":"Antigène défini ; sélection d'un clone préexistant puis prolifération","points":5},{"critere":"Tableau juste : LB/plasmocytes/anticorps/liquides ; LT8/destruction/cellules infectées","points":7},{"critere":"LT4 activé par la CPA, interleukines qui amplifient et coordonnent","points":4},{"critere":"Comparaison juste sur les trois critères","points":4}],"dureeMin":8,"corrige":"1. Un **antigène** est une molécule reconnue comme étrangère. Chaque lymphocyte possède un récepteur d'un seul type, et le répertoire, engendré **avant toute rencontre**, compte des milliards de spécificités. La rencontre avec l'antigène ne crée rien : elle **sélectionne** le clone qui possédait déjà le bon récepteur, puis le fait **proliférer** : c'est la **sélection clonale**.\n2. **Humorale** : **lymphocyte B**, différencié en **plasmocyte** ; arme : les **anticorps**, qui forment des **complexes immuns** éliminés par phagocytose ; contre les agents **dans les liquides** de l'organisme. **Cellulaire** : **lymphocyte T cytotoxique (LT8)** ; arme : la **destruction de la cellule cible** ; contre les agents **à l'intérieur des cellules** (virus, cellule cancéreuse).\n3. Le **LT4**, activé par la cellule présentatrice de l'antigène, sécrète des **interleukines** qui **amplifient et coordonnent** les deux voies : c'est le chef d'orchestre.\n4. Innée : **immédiate**, **non spécifique**, **sans mémoire**. Adaptative : **plusieurs jours**, **spécifique** d'un antigène, **avec mémoire**."}$exo$::jsonb),
  ('f7d0513d-ad19-52e2-b26b-285be07cc806'::uuid, 2, 'application', $exo${"titre":"Deux contacts avec le même antigène","consigne":"Exploite les données, calcule et justifie avec le cours.","enonce":"**Situation (données simplifiées).** On injecte à un lapin un antigène A au jour 0, puis de nouveau le même antigène A au jour 60. On mesure la concentration d'anticorps anti-A dans le sang (unités arbitraires).\n\n| | 1er contact (jour 0) | 2e contact (jour 60) |\n| Délai avant l'apparition des anticorps | 7 jours | 2 jours |\n| Concentration maximale d'anticorps | 20 | 200 |\n\nAu jour 60, on injecte aussi un antigène B, jamais rencontré : les anticorps anti-B apparaissent au bout de 7 jours et atteignent une concentration maximale de 20.\n\n1. Compare les deux réponses contre A : calcule le rapport des concentrations maximales et compare les délais.\n2. Explique cette différence. Quelles cellules en sont responsables ?\n3. Pourquoi la réponse contre B ressemble-t-elle à la première réponse contre A ? Quelle propriété de l'immunité adaptative cela montre-t-il ?\n4. Quelles cellules produisent ces anticorps, et que deviennent les antigènes auxquels ils se lient ?","bareme":[{"critere":"Rapport 200 / 20 = 10 ; délai de 7 à 2 jours","points":5},{"critere":"Lymphocytes mémoire : réponse secondaire plus rapide, plus intense","points":6},{"critere":"B jamais rencontré : réponse primaire ; spécificité de la mémoire","points":5},{"critere":"Plasmocytes issus des LB ; complexes immuns éliminés par phagocytose","points":4}],"dureeMin":11,"corrige":"1. La concentration maximale passe de 20 à 200 : elle est **10 fois** plus élevée (200 / 20 = 10). Le délai passe de **7 jours à 2 jours** : la réponse est plus **rapide**.\n2. Après le premier contact, des **lymphocytes mémoire** spécifiques de A ont persisté. Au second contact, ils sont plus nombreux et réagissent vite : la **réponse secondaire** est **plus rapide, plus intense, plus efficace**. C'est la **mémoire immunitaire**.\n3. L'antigène B n'avait jamais été rencontré : aucun lymphocyte mémoire anti-B n'existe, la réponse est une **réponse primaire** (7 jours, maximum 20). La mémoire est **spécifique** : elle ne vaut que pour l'antigène déjà rencontré.\n4. Les anticorps sont produits par les **plasmocytes**, issus des **lymphocytes B** sélectionnés. En se liant à l'antigène, ils forment des **complexes immuns**, éliminés par **phagocytose**."}$exo$::jsonb),
  ('f7d0513d-ad19-52e2-b26b-285be07cc806'::uuid, 3, 'application', $exo${"titre":"Le VIH et le chef d'orchestre","consigne":"Exploite les documents et construis une explication argumentée qui mobilise l'ensemble du cours.","enonce":"**Document 1 — Évolution chez une personne infectée par le VIH, sans traitement (valeurs simplifiées).**\n\n| Années après l'infection | 0 | 2 | 5 | 8 | 10 |\n| Lymphocytes T4 (par mm³ de sang) | 1 000 | 700 | 500 | 300 | 100 |\n| Infections graves observées | Aucune | Aucune | Rares | Fréquentes | Très fréquentes |\n\n**Document 2.** Chez cette personne, des anticorps anti-VIH sont présents dans le sang, mais le virus continue de se multiplier à l'intérieur de ses cellules.\n\n**Document 3.** Les infections graves des dernières années sont dues à des agents variés (bactéries, champignons, virus) qui ne rendent habituellement pas malades les personnes en bonne santé.\n\n1. Décris l'évolution du nombre de LT4 et calcule le pourcentage de LT4 perdus en dix ans.\n2. Explique pourquoi la destruction des LT4 affaiblit **les deux voies** de la réponse adaptative.\n3. Explique le document 2 : pourquoi les anticorps ne suffisent-ils pas à éliminer le virus ? Quelle voie serait nécessaire ?\n4. Explique le document 3 et nomme le stade de la maladie qu'il décrit.","bareme":[{"critere":"Baisse régulière des LT4 ; (1 000 − 100) / 1 000 = 90 % perdus","points":4},{"critere":"LT4 chef d'orchestre : sans interleukines, ni voie humorale ni voie cellulaire amplifiées","points":5},{"critere":"Anticorps n'entrent pas dans les cellules ; voie cellulaire (LT8) nécessaire","points":5},{"critere":"Infections opportunistes liées à l'effondrement de la réponse adaptative : sida","points":4},{"critere":"Données chiffrées exploitées","points":2}],"dureeMin":18,"corrige":"1. Le nombre de LT4 **diminue régulièrement** : de 1 000 à 100 par mm³ en dix ans. Perte : (1 000 − 100) / 1 000 × 100 = **90 %**. Parallèlement, les infections graves deviennent de plus en plus fréquentes.\n2. Le **LT4**, activé par la cellule présentatrice de l'antigène, sécrète des **interleukines** qui **amplifient et coordonnent** la voie **humorale** (lymphocytes B → plasmocytes → anticorps) et la voie **cellulaire** (LT8). Sa destruction par le **VIH** prive les deux voies de leur chef d'orchestre : **toute la réponse adaptative est désorganisée**.\n3. Les anticorps agissent **dans les liquides** de l'organisme : **un anticorps n'entre jamais dans une cellule**. Le virus, qui se multiplie **à l'intérieur** des cellules, leur échappe. Il faudrait la **voie cellulaire** : les **LT8** détruisent les cellules infectées. Or cette voie est elle aussi affaiblie par la perte des LT4.\n4. Avec très peu de LT4, la réponse adaptative ne fonctionne plus : des agents variés, habituellement contrôlés, provoquent des infections graves. C'est le stade du **sida**, dont le mécanisme est la destruction des LT4 par le VIH."}$exo$::jsonb),
  ('aa5a63b6-6b74-5e3c-9d58-d231ca96c9ad'::uuid, 1, 'application', $exo${"titre":"Vaccin ou sérum ?","consigne":"Réponds à chaque question par des phrases complètes, avec le vocabulaire du cours.","enonce":"1. Sur quoi repose l'efficacité de la vaccination ? Cite deux types d'antigènes inoffensifs utilisés dans les vaccins.\n2. Recopie et complète :\n\n| Critère | Vaccination | Sérothérapie |\n| Ce qu'on injecte | … | … |\n| Délai de protection | … | … |\n| Durée | … | … |\n| Mémoire | … | … |\n\n3. Quel est le rôle d'un **rappel** ? Et d'un **adjuvant** ?","bareme":[{"critere":"Constitution d'une mémoire immunitaire ; deux types d'antigènes (inactivé, atténué, fragment, ARNm)","points":5},{"critere":"Tableau juste : antigène/anticorps, lent/immédiat, durable/brève, oui/aucune","points":9},{"critere":"Rappel : réponse secondaire des lymphocytes mémoire ; adjuvant : stimule l'immunité innée","points":6}],"dureeMin":7,"corrige":"1. La vaccination repose sur la **constitution d'une mémoire immunitaire** : le système immunitaire monte une réponse adaptative complète contre un antigène **inoffensif**, sans avoir subi la maladie. Antigènes utilisés : agent **inactivé**, agent **atténué**, **fragment protéique**, ou **ARN messager** codant un antigène.\n2. **Ce qu'on injecte** : un **antigène** inoffensif / des **anticorps** déjà formés. **Délai** : **lent** / **immédiat**. **Durée** : **durable** / **brève**. **Mémoire** : **oui** / **aucune**.\n3. Le **rappel** sollicite les **lymphocytes mémoire** et produit une **réponse secondaire** qui renforce durablement la protection. L'**adjuvant** **stimule l'immunité innée** au point d'injection, condition d'une bonne réponse adaptative."}$exo$::jsonb),
  ('aa5a63b6-6b74-5e3c-9d58-d231ca96c9ad'::uuid, 2, 'application', $exo${"titre":"Le clou rouillé","consigne":"Analyse la situation et justifie chaque décision médicale avec le cours.","enonce":"**Situation (fictive).** M. Petit, 70 ans, se blesse profondément avec un clou rouillé dans son jardin. Il n'a jamais été vacciné contre le tétanos, une maladie grave causée par une toxine bactérienne qui agit en quelques jours. Le médecin lui injecte le jour même des **anticorps anti-tétaniques**, puis commence une **vaccination** contre le tétanos.\n\nSa petite-fille Jade, 12 ans, s'est blessée de la même façon la semaine précédente. Elle est à jour de ses vaccins : le médecin ne lui a rien injecté.\n\n1. Comment s'appelle l'injection d'anticorps ? Pourquoi est-elle adaptée à l'urgence de M. Petit ?\n2. Pourquoi le médecin commence-t-il aussi une vaccination ? Pourquoi ne pas se contenter des anticorps ?\n3. Explique pourquoi Jade est protégée sans aucune injection, en décrivant ce qui se passerait si la toxine pénétrait dans son organisme.\n4. Le calendrier vaccinal de Jade prévoit des rappels. Explique leur intérêt.","bareme":[{"critere":"Sérothérapie : anticorps déjà formés, protection immédiate","points":5},{"critere":"Sérothérapie brève et sans mémoire ; vaccination pour une protection durable","points":5},{"critere":"Jade : lymphocytes mémoire, réponse secondaire rapide et intense","points":6},{"critere":"Rappels : sollicitent la mémoire et renforcent durablement la protection","points":4}],"dureeMin":12,"corrige":"1. C'est une **sérothérapie** : on injecte des **anticorps déjà formés**. La protection est **immédiate**, alors qu'une vaccination seule mettrait plusieurs jours à produire des anticorps, trop tard face à une toxine qui agit en quelques jours. C'est l'usage d'urgence type : **tétanos chez un non-vacciné**.\n2. La sérothérapie est **brève** et ne crée **aucune mémoire** : le système immunitaire est **remplacé**, il ne travaille pas. La **vaccination** fait travailler le système immunitaire et constitue une **mémoire** : M. Petit sera protégé **durablement** en cas de nouvelle blessure.\n3. Jade possède des **lymphocytes mémoire** spécifiques de l'antigène tétanique, issus de sa vaccination. Au contact de la toxine, ils déclenchent une **réponse secondaire** **plus rapide, plus intense, plus efficace** : l'infection est souvent stoppée avant tout symptôme.\n4. Le **rappel** sollicite les **lymphocytes mémoire** et produit une réponse secondaire qui **renforce durablement** la protection."}$exo$::jsonb),
  ('aa5a63b6-6b74-5e3c-9d58-d231ca96c9ad'::uuid, 3, 'application', $exo${"titre":"Protéger les autres, soigner autrement","consigne":"Exploite les documents et rédige une argumentation structurée qui mobilise l'ensemble du cours.","enonce":"**Document 1 — Cas d'une maladie très contagieuse selon la couverture vaccinale d'une région (données fictives).**\n\n| Couverture vaccinale | 70 % | 85 % | 95 % |\n| Cas par an | 600 | 120 | 6 |\n\n**Document 2.** Dans cette région vivent des nourrissons trop jeunes pour être vaccinés et des personnes immunodéprimées qui ne peuvent pas recevoir ce vaccin.\n\n**Document 3.** Chez certains patients atteints d'un cancer, les lymphocytes T reconnaissent la tumeur mais restent inactifs : la tumeur exerce sur eux un frein. Deux traitements sont proposés : (A) un médicament qui lève ce frein ; (B) le prélèvement des lymphocytes du patient, leur modification en laboratoire, puis leur réinjection.\n\n1. Décris le document 1 et calcule par combien le nombre de cas est divisé entre 70 % et 95 % de couverture.\n2. Explique, avec les documents 1 et 2, la notion d'**immunité collective** et pourquoi la vaccination a une dimension collective.\n3. Le seuil de couverture nécessaire est très élevé pour la rougeole. Explique pourquoi, d'après le cours.\n4. Nomme les deux immunothérapies du document 3 et explique en quoi elles utilisent le système immunitaire comme traitement. En quoi diffèrent-elles d'une vaccination ?","bareme":[{"critere":"Baisse des cas quand la couverture augmente ; 600 / 6 = 100","points":4},{"critere":"Immunité collective : chaîne de transmission rompue, protection des non-vaccinables","points":6},{"critere":"Seuil qui dépend de la contagiosité","points":3},{"critere":"A : inhibiteurs de points de contrôle ; B : CAR-T ; différence avec la prévention vaccinale","points":5},{"critere":"Argumentation appuyée sur les données","points":2}],"dureeMin":18,"corrige":"1. Plus la couverture vaccinale augmente, plus le nombre de cas **diminue** : 600 cas à 70 %, 120 à 85 %, 6 à 95 %. Entre 70 % et 95 %, il est divisé par 600 / 6 = **100**.\n2. Au-delà d'un certain **taux de couverture**, la **chaîne de transmission se rompt** : le microbe ne trouve plus assez de personnes réceptives pour circuler. Les personnes qui **ne peuvent pas être vaccinées** (nourrissons, immunodéprimés du document 2) sont alors **protégées par les autres** : c'est l'**immunité collective**. Se vacciner protège donc aussi autrui : la vaccination a une dimension **collective**, pas seulement individuelle.\n3. Le seuil **dépend de la contagiosité** de la maladie : plus elle est contagieuse, plus il faut de personnes immunisées pour rompre la chaîne. La rougeole étant très contagieuse, son seuil est très élevé.\n4. **A** : un **inhibiteur de points de contrôle**, qui **lève le frein** que la tumeur exerce sur les lymphocytes T ; ceux-ci peuvent alors attaquer la tumeur. **B** : une thérapie cellulaire **CAR-T** : les lymphocytes du patient sont modifiés en laboratoire puis réinjectés. Dans les deux cas, ce sont les **cellules immunitaires du patient** qui détruisent la tumeur. Une vaccination est une **prévention** qui construit une mémoire contre un agent infectieux avant la maladie ; ces immunothérapies sont des **traitements** d'une maladie déjà présente."}$exo$::jsonb)
) AS v (chapter_id, difficulte, style, contenu)
JOIN public.chapters c ON c.id = v.chapter_id
ON CONFLICT (id) DO UPDATE
  SET style      = EXCLUDED.style,
      contenu    = EXCLUDED.contenu,
      difficulte = EXCLUDED.difficulte,
      origine    = 'catalogue';

DO $$
DECLARE
  n INT;
BEGIN
  SELECT count(*) INTO n
    FROM public.chapter_exercices e
   WHERE e.origine = 'catalogue'
     AND e.chapter_id IN ('107e042d-818a-5b99-aecd-ef8c2e5676cd', '64406e4c-bdf6-5f8a-97ae-4eea97193e89', '66d17b6a-2283-59c9-b3ca-c543c78fe1d0', 'aad28990-b793-57bd-9233-a2f7393703d2', 'c3d67f85-7fa1-5f25-8445-4a93b12bdef7', '63eeb696-8889-5ff9-9d88-d1440f713a96', 'a764617f-b186-572f-9f22-403bfffdd22e', '95b6d4cf-95b1-5a36-9c9d-d5fd225889f0', '84553740-9424-5e81-b623-8e151f93b6e9', 'a546fa4b-ed58-5240-92e7-6b98b002abb8', '93495817-b48c-5f4c-943c-49e859698714', '1e2dfded-f4e7-5e6f-b057-58b12eee8ba2', '79f5875d-aa17-57cc-9c27-55c73466125f', '30588c6b-33e2-5fbc-8e20-0c35a0e2f713', '6912a692-5037-5348-9dcd-38bb57202202', 'a59242bd-b077-591e-b2c5-3fe816eff8cd', '8a8fd32a-db18-51b5-8151-7ce2f8f54a1a', '0c717a05-a7e7-58a0-8224-5a96565ad8fd', '5bdb8383-2a3e-50b2-aac0-32272b5090b7', 'de8ed94b-796f-5073-b843-116097058972', '21a7ae15-4688-5b42-9128-d3b611f7eca0', '18c1bed0-1b68-55d9-8d33-2f96974c1446', 'dca1c5d4-bf4e-5ee8-9d44-764e8cd1cb2e', '0f5ff5c6-af95-52a5-a98c-bbd2fbb87ce1', 'ece3f0db-2c41-50a7-912c-3cff320071de', '7e85f55e-fcca-5ea8-a5da-b86d96f85d96', 'f7e71d0d-eaf2-52c3-992e-f14727b42c4c', '00b37453-9a08-5b3d-885f-d374602e0c79', '1feef3e8-659c-578f-b480-22aa8b09f42c', 'a0bd4fbd-b592-586c-a3c3-036e8d0d2db5', 'd62a9762-feb6-5e49-b763-d9bb543c8f93', 'db568ee0-3901-5d3e-9e5b-e2116895f4e4', '7ee89269-3a85-5e93-a2fb-24887dde127b', 'edac8366-9883-5a36-81d2-61e754d9910a', 'ac46543c-71fd-5a8c-9fbb-b9446492b253', '97ea11d8-b76d-5944-a451-a2d8ecdf35d5', '9b7bfa3b-00e5-5048-b082-f341bbbe6af3', 'f7d0513d-ad19-52e2-b26b-285be07cc806', 'aa5a63b6-6b74-5e3c-9d58-d231ca96c9ad');
  RAISE NOTICE '412 : % sujets au catalogue (attendu : 117)', n;
  IF n < 117 THEN
    RAISE WARNING '412 : il manque des sujets — des fiches ont-elles changé d''identifiant ?';
  END IF;
END $$;
